INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES (11113,3,1,'နှစ်ဆယ့်ငါးလုံးမြောက်မွန်ဗျည်း။',NULL)
,(11114,3,1,'၁။ ဖခင်။ အဖေ။','မိမ = မိဘ။')
,(11114,3,1,'၂။ အစေ့။ အလုံး။','မအဳ = ဖာလာစေ့။ || မသြောအ် = စပါးစေ့။ || မကြေဟ် = ကျောက်ခဲ။ ခဲလုံး။')
,(11114,3,1,'၃။ မျိုးစေ့။','မလဵု = ဗူးမျိုးစေ့။ || သြောအ်မ = မျိုးစပါး။')
,(11114,3,9,'အလုံးကိုရေတွက်ရာတွင် သုံးသောစကားလုံး။','ကြုက်ၜါမ= သရက်သီးနှစ်လုံး။ || ခပဳထဝ်ပိမ = ရွှေဖရုံသီးသုံးလုံး။ || သ္ၚိမွဲမ = အိမ်တစ်လုံး။')
,(11115,3,16,'သၚ်။ (ယောကျာ်းကို ရည်ညွှန်းသည်။)','“မလ္ပအာညိ။” = “သၚ်မသွားပါနှင့်။” || “ဗြဴသ္အာၚ်မတုပ်ကဵုစိုတ်ဂှ် ဂၠာဲနၚ်တုဲ မဝေၚ်သဘၚ်ဗတ်မရ” သမ္ဘာဂှ်ဂးကဵုတြုံရ။ (ဇ—၁၄၇။ အစွောံ။) = “စိတ်ချင်းတူသော တစ်ပါးသောမိန်းမကိုရှာ၍ သင့်ဖာသာ သင်ပွဲသဘင်ကစားလေလော့” ဟုမယားသည် လၚ်အားပြော၏။')
,(11116,3,9,'၁။ ကြိယာကိုလေးနက်စေသောရှေ့ဆက်။','“တၞံဆုဝွံ မပေၚ်တဴကဵုသတ်ရ။” =“ဤသစ်ပင်သည် အသီးတို့ဖြင့် ပြည့်လျက်ရှိသည်။” || “မိမဂမၠိုၚ် မဆာန်ကောန်အိုတ်ရ။” =“မိဘများသည် သားသမီးကို ချစ်ကြသည်။”')
,(11116,3,9,'၂။ နဝိပုဒ်စု၏ရှေ့ဆက်။','‘မၞိဟ်မၞုံကဵုဓဝ်’ =‘တရားနှင့်ပြည့်စုံသောလူ။’ || ‘ညးမချိုတ်’ = ‘သေသောသူ။’ || ညးမအောန်ကဵုပညာ = ပညာနည်းပါးသောသူ။ || ညးမယုတ်မာ = ယုတ်မာသောသူ။')
,(11117,3,1,'မဂဏန်း။',NULL)
,(11118,3,3,'မကသော။ ပိုလွန်သော။',NULL)
,(11119,3,3,'တစ်မျိုးမကသော။ အမျိုးမျိုးသော။','“ဓဝ်လောဘဂှ် မၞုံဒုဟ်မဂၠိုၚ် မကမွဲသာ်ရ။” (ဇ—၄၄ဝ။ အစွောံ။) = “လောဘတရားသည် များစွာသော အမျိုးမျိုးသောအပြစ်ရှိ၏။” || “(လၟေန်ဂှ် ပေါဟ်ပထောၚ်လဝ်တုဲ) ပ္ဍဲသၠဇြဲဂှ် မပ္တံရုပ်စိၚ်ရုပ်ချေံ ရုပ်မကမွဲသာ် က္တဵုဒှ်အိုတ်ရ။” (ဇ—၁ဝ၇။ အစွောံ။) = “ထိုၚဆွံ့ပစ်ဖောက်ထား၍ ညောင်ရွက်တို့­ ဆင်ရုပ်မြင်းရုပ်အစရှိသော အရုပ်အမျိုးမျိုးဖြစ်ပေါ်ကုန်၏။” || “ဂၠိုၚ်ကဵုအခိုက် ကွိၚ်ကွိုက်ဒယှ်ေလှ်ေမကမွဲပြကာရ။” (ဇ—၅၂၆။ အစွောံ။) = “ကဟန်သံစဉ်အမျိုးမျိုး အတီးအမှုတ် အဆိုအကမျိုးစုံ။”')
,(11120,3,3,'တစ်ရာမကသော။ အရာမကသော။','“ဗောဓိသတ်ပိုဲဒှ်စာၚ်ဂြိုပ် မၞုံတွဳဝါရမကမွဲကၠံ ပဒတဴပ္ဍဲဂြိုပ်ဂှ်ရ။” (ဇ—၃၈၃။ အစွောံ။) = “ဘုရားလောင်းသည် တောကြက်အမျိုး­ဖြစ်၍ အရာမကသော ကြက်အပေါင်းခြံရံလျက် တော­နေ၏။”')
,(11121,3,3,'တစ်ထောင်မကသော။ အထောၚ်မကသော။','“ဣသိပဗ္ဗတမွဲဂှ် နိဿဲကဵုနဳဂီုအဋပိပ္ဍဲသပိုဟ်ဂြိုပ်မွဲတုဲ တွဳဗွိုၚ်ကေတ်ဣသိမကမွဲလ္ၚီတုဲ ပဒတဴရ။” (ဇ—၄၂၃။ အစွောံ။) = “ပဗ္ဗတအမည်ရှိသောရသေ့သည် တစ်ခုသောတောအုပ် ဇနပုဒ်ကိုမှီ၍ အထောၚ်မကသောရသေ့တို့သည်ခြံရံအပ်သည်ဖြစ်၍ နေ၏။” (ညောင်ကန်) || “ဇန်ဂမၠိုၚ် တက်တဲသဝဲယာတ် မကမွဲလ္ၚီ ဒ္ဂေတ်တဴအိုတ်ရ။” (ဇ—၂၄၃။ အစွောံ။) = “လူတို့သည် လက်ခုပ်တီး၍၄င်း အဝတ်ကိုဝှေ့ယမ်း၍၄င်းအထောၚ်မက ကောင်းချီးပေးကြကုန်၏။”')
,(11122,3,1,'မှို။ မှိုတက်ခြင်း။ (မကလု = ပ္တိုဟ်။) (ပါဠိ—ကဏ္ဏကိတ)','(တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။စန္ဒိမာ။)')
,(11123,3,3,'ညိုဝါရောင်ဖြစ်သော။ လိမ္မော်ရောင်ဖြစ်သော။','ဝုန်မကာဲ = ညိုဝါရောင်၊ လိမ္မော်ရောင်ရှိသောကန်စွန်းဥ။')
,(11124,3,11,'(န) မကရရာသီ။ (ဆယ့်နှစ်ရာသီတွင် မကန်းရုပ်ဖြင့်မှတ်အပ်သော ဒသမရာသီ)',NULL)
,(11125,3,1,'မိန်းမအၚ်္ဂါဇာတ်၏အစေ့။ စောက်စေ့။',NULL)
,(11126,3,1,'ပိတ်ချင်း။ (ပါဠိ—ဥသဏာ','ကောလာ)')
,(11127,3,1,'ဝှေးစေ့။',NULL)
,(11128,3,1,'ကျောက်စရစ်။',NULL)
,(11129,3,1,'သစ်ဆိမ့်သီး။',NULL)
,(11130,3,1,'စိပ်ပုတီး။','“ရပ်မဂတောန်၊ ယောန်အာညံက်ညံက်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “စိပ်ပုတီးကိုကိုင်လျက် ဦးခေါင်းငိုက်စိုက်ဖြင့် အသာအယာလျှောက်သွား၏။”')
,(11131,3,3,'ဆိုအပ်သော။ မည်သော။',NULL)
,(11131,3,4,'မည်သည်။ ဟူသည်။','“တၠပညာမ္ဂးဂှ် နွံကဵု ဂမြင်ရ။” = “ပညာရှိမည်သည် အမြော်အမြင်ရှိသည်။”')
,(11131,3,7,'အကယ်၍—လျှင်။','“မၞးအာဘာမ္ဂး ကေတ်နၚ်လိက်အဲညိ။” = “သၚ်ကျောင်းသွားလျှင် ကျွန်တော့်စာအုပ်ကို ယူလာပါ။”')
,(11132,3,1,'လည်ဆွဲ။',NULL)
,(11133,3,1,'မှန်ကူပင်။',NULL)
,(11134,3,4,'မာသည်။','‘မ္ၚိုဟ်’ ရှု။')
,(11135,3,1,'(အပြော) မျိုးရိုးဗဳဇ။',NULL)
,(11136,3,9,'အမေးဝါကျ ကြိယာကိုလေးနက်စေသောစကားလုံး။','‘မွဲစိ’/‘မူစိ’ ရှု။ || “ယွံကောန်အဲရာဓ၊ မိနာဲဂှ် ပွမယုတ် မစိဍေံပ ဟွံပဟာကောန်။” (ဇ—၁၉၈။ အစွောံ။) = “ချစ်သားရာဓ၊သင်၏အမိသည် ယုတ်မာသောအကျင့်ကို ကျင့်သလော၊ မကျင့်သလော။” (ညောင်ကန်) || “ဗြဴကမၠောန်ဂှ် မစိမရှာတ်သ္ဍိုက်မၠိုက်တဴညိဟာ။” (ဇ—၁၉၅။ အစွောံ။) = “မင်းမြတ်၊ ထိုမင်းမိန်းမအားလည်း သင်မင်းမြတ်သည် ချစ်မြတ်နိုးပေသလော။”')
,(11137,3,1,'ပစ္စည်းအသေးအဖွဲစု။ တိုလီမိုလီ။ ဗူလိနတ်စ။',NULL)
,(11138,3,13,'(န) မျက်စဉ်း။','‘မက်စေန်’ ရှု။')
,(11139,3,1,'ဟင်းခတ်အမွှေးအကြိုင်မှုန့်။ မဆလာ။','“ခရိက်ဖျုန်ဂၠဴ၊ နှဴမဆာလာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ၊) = “အမဲသားကိုခုတ်ပိုင်း၍ မဆလာနှင့်ရောသည်။”')
,(11140,3,1,'သွေးနီဥ။ (သွေးတွင်ပါဝင်သော အနီရောင်ကလာပ်စည်း။)',NULL)
,(11141,3,1,'သွေးဖြူဥ။ (ရောဂါပိုးများကို ခုခံတိုက်ခိုက်နိုင်သော၊ သွေးတွင်ပါဝင်သည့် အဖြူရောင်ကလာပ်စည်း။)',NULL)
,(11142,3,1,'မျိုးရိုး။',NULL)
,(11143,3,4,'လှုပ်ခါသည်။',NULL)
,(11144,3,1,'ရဲယိုပင်။ ရဲယိုသီး။',NULL)
,(11145,3,11,'(န) မတကဘတ်။ ကွယ်လွန်သူကိုရည်စူး၍ ပေးလှူသောဆွမ်း။ သပိတ်သွတ်ဆွမ်း။',NULL)
,(11146,3,1,'ပိုင်ရှင်လစ်လျှင်ခိုး၍ ပိုင်ရှင်တွေ့လျှင် လုယက်တိုက်ခိုက်သည့် သူခိုးဓါးပြ။','‘ဒမၠမတာ’ဟူ၍ အများအားဖြင့် တွဲစပ်သုံးနှုန်းသည်။')
,(11147,3,1,'လွန်လေပြီးသောကာလ။',NULL)
,(11148,3,16,'(န) မတြာ။ (မျက်စိတစ်မှိတ်၊ လက်ဖျစ်တစ်တွက်ခန့်ကာလ။)',NULL)
,(11149,3,3,'ဆိုအပ်သော။ ဟူသော။ ဟူသည့်။ တည်းဟူသော။','“ဓဝ်အဂတိပန် မတွံဂး ဆန္ဒာဂတိ၊ ဘယာဂတိ၊ ဒေါသာဂတိ၊ မောဟာဂတိ။” = “ဆန္ဒာဂတိ၊ ဘယာဂတိ၊ ဒေါသာဂတိ၊ မောဟာဂတိတည်းဟူသော အဂတိတရားလေးပါး။” || “ကျာ်ဓဝ်သၚ်မတွံဂး ရတ်ပိပြကာ။” = “ဘုရားတရားသံဃာဟူသောရတနာသုံးပါး။” || “ဂွံဝေၚ်ကၠေံကာမဂုန်မသုန်ပြကာ မတွံဂးဂျိဂှ်တုဲ တၠပညာဂှ် — မဂွံတိတ်ဗၠးနူဒုဟ်သံသာရောၚ်။” (ဇ—၃၆၆။ အစွောံ။) = “အဆိပ်တည်းဟူသော ကာမဂုဏ်ငါးပါးတို့ကို ရှောင်ကြဉ်နိုင်သောပညာရှိသည် သံသရာဘေးမှ လွတ်မြောက်ရ၏။”')
,(11150,3,11,'(န) (စာပေ) မဓုရတာဂုဏ်။ (ကာရန်တူ၊ အသတ်တူ၊ စာလုံးတူ စသည်ဖြင့် ချိုသာနာပျော်ဖွယ်ဖြစ်အောင် စပ်ဆိုထားသောဂုဏ်။)',NULL)
,(11151,3,11,'(န) ချိုမြိန်ဖွယ်သောအရသာ။ (ပါဠိ—မဓုရရသ)','“ညးဖျိန်ကဵုဖျုန်ဒကောတ်ဂှ်သီုမထီုဗးပ္ဍးတမှာဲဒၟံၚ် ဖျုန်မဓုရှ်ဂှ် ဣသိစၞာဲဂွံစရ။” (ဇ—၃၂၅။ အစွောံ။) = “ဒကာတို့ချက်ထားသော မွှေးကြိုင်သင်းပျံ့စွာသော ချိုမြိန်ဖွယ်အရသာရှိသော ဖွတ်သားဟင်းလျာကို ရသေ့စဉ်းလဲစားရ၏။”')
,(11152,3,4,'မေ့လျော့သည်။ ပေါ့ဆသည်။','“သတိဗလ၊ လ္ပမနညိ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်) = “သတိဝီရိယရှိပါ၊ မမေ့လျော့မပေါ့ဆပါလေနှင့်။”')
,(11153,3,10,'(န) မနသိကာရ။ နှလုံးသွင်းခြင်း။ နှလုံးပိုက်ခြင်း။ အလေးဂရုပြုခြင်း။','ဟွံသ္ပမနသိကာရ = အရေးမလုပ်၊ ဂရုမစိုက်။ နှလုံးမသွင်း။')
,(11154,3,4,'အရေးမလုပ်။ ဂရုမစိုက်။ အလေးမထား။ နှလုံးမသွင်း။','‘မနသိကာရဟွံမွဲ’ နှင့်အတူတူ။ || “(ဂစေံဂှ်) စဒၟံၚ်ဒၞာဲဂှ် မိၚ်ဗရုကွဳမကၠုၚ်ဂှ် ကွဳဂှ်သ္ၚောဲဒၟံၚ်ဏီဂးတုဲ မနဟွံမွဲ (ဟွံဒြေပ်ပဲါရ။)” (ဇ—၁၁၅။ အစွောံ။) = “ထိုငှက်သည် ထိုနေရာ­ အစာစားနေရာ လာသောလှည်းသံကိုကြား၍လည်း လှည်းသည်ဝေးနေသေးသည်ဟုဆို၍ ဂရုစိုက်ခြင်းမရှိ မပြေးရှောင်ဘဲနေ၏။”')
,(11155,3,10,'(န) ကျောက်မျက်ရတနာ။',NULL)
,(11156,3,1,'မနိမေခလာနတ်သမီး။',NULL)
,(11157,3,10,'(န) ၁။ စိတ်။',NULL)
,(11157,3,10,'(န) ၂။ အမျက်ဒေါသ။','‘က္တဵုဒှ်မနော။’ = ‘ဒေါသထွက်သည်။’ || “မၚ်ရာဲကယျဝ်ဆွာမိၚ်သာ်ဂှ်တုဲ က္တဵုဒှ်မနောဗွဲမလောန်ရ။” (အကြီုရာဇာဓိရာဇ်) = “မင်းရဲကျော်စွာသည် ထိုသို့ကြား၍ ဒေါသဖြစ်၏။”')
,(11157,3,10,'(ကြိ) ဒေါသထွက်သည်။','“ဟိုတ်နူဍေံပလဳဘာတုဲ အပါဍေံမနောဒၟံၚ်ကဵုဍေံရ။” = “သူကျောင်းပြေးသောကြောင့် သူ့အဖေက သူ့ကိုဒေါသထွက်နေသည်။”')
,(11158,3,11,'(န) စိတ်ဖြင့်ကြံစည်မှု။ မနောကံ။',NULL)
,(11159,3,11,'(န) ဆေးဒန်းမြင်းသီလာကျောက်။ (ပါဠိ—မနောသိလာ)','“(တဳလပစ္စေဂဗုတ်) က္ၜဴပါၚ်ပၠဳမုက္ခဝါ ဍာ်လစအနုတတ်တုဲ ဒတဴဒၟံၚ်လတူတၞးတၟံမနောသိလာ—။” (ဇ—၄ဝ။ အစွောံ။) = “(အရှင်ပစ္စေကဗုဒ္ဓာသည် အနဝတတ်အိုၚ်မှရေဖြင့် ပလုတ်ကျင်း) မျက်နှာသစ်တော်မူ၍ ဆေးဒန်းမြင်းသီလာဖြင့်ပြီးသော ကျောက်ဖျာအပြင်­ (ရပ်တော်မူ၏။)” (ညောင်ကန်)')
,(11160,3,1,'ကိုက်ခဲသောရောဂါ။','“ယဲဂိထမက်၊ မနက်က္တဵုဒှ်။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) || “ယဲဂျိမာနက်၊ ကသက်ကသာဒးဒှ်။” (လိက်ပယးအနိစ္စ) = “ကိုက်ခဲသောအဆိပ်ရောဂါကြောင့် ပူလောင်ခြင်းဝေဒနာခံစားရ၏။”')
,(11161,3,1,'ပတ္တမြား။','‘မၞိက်’ ရှု။')
,(11162,3,10,'(န) လူသား။ မနုဿ။',NULL)
,(11163,3,10,'(န) လူဆင်းသက်ဖြစ်ပေါ်ပုံနှင့်တကွ လူသားတို့၏သဘာဝကို လေ့လာသောအတတ်ပညာ။ မနုဿဗေဒ။',NULL)
,(11164,3,11,'(န) လူ့ဘုံလောက။ မနုဿလောက။','“ပ္ဍဲမနုဿလိုက်ကီု ပ္ဍဲဒေဝလိုက်ကီု။” (ဇ—၅၁၅။ အစွောံ။) = “လူ့ဘုံလောက­၄င်း၊ နတ်ဘုံလောက­၄င်း။”')
,(11165,3,10,'(န) မနုဿီဟ။ လူ၏မျက်နှာတစ်ခုနှင့် ခြင်္သေ့၏ကိုယ်နှစ်ခွ ပါရှိသောရုပ်သဏူဌာန်။',NULL)
,(11166,3,1,'တစ်ခဏအချိန်။',NULL)
,(11167,3,5,'ခဏခဏ။',NULL)
,(11168,3,3,'စသော။ စသည့်။','“ညးမွဲဗတဳကွာ်တရဴတံဂှ် မပတံဝတ္ထုကၠေၚ်လ္ၚဴ၊ ဍာ်၊ အှ်ော၊သ္ၚုတံဂှ် မဒးပ္ဍိုက်ဏာကွဳ စောတ်တုဲ ကာလဗ္တံ မဒးအာရောၚ်။” (၅၅ဝ။ ဇ—၂။ အစွောံ။) =“ခရီးသွားသောသူတို့သည် နှမ်းဆီ၊ ရေ၊ ထင်း၊ ဆန် စသောဝတ္ထုတို့ကို လှည်းပေါ်တင်ဆောင်ကြပြီးလျှင် ညအခါသွားကြရကုန်၏။” || “တၞောဝ်ကောန်သၟိၚ် မပ္တံကဵုဘဒ္ဒိယထေရ်တုဲ ညးထပှ်တိတ်ပခမဳ ဇရေၚ်ကျာ်တြဲရ။” (၅၅ဝ။ ဇ—၁ဝ။ အစွောံ။) = “ဘဒ္ဒိယမထေရ် စသည့်မင်းသားမျိုးနွယ် ခုနစ်ယောက်တို့သည် မြတ်စွာဘုရားအထံတော်­ ထွက်၍ရဟန်းပြုကြကုန်၏။”')
,(11169,3,1,'ကြယ်သီး။ ကမ္ပတ်သီး။ (ပါဠိ—ဂဏူဌိကာ)',NULL)
,(11170,3,1,'မိုးသီး။',NULL)
,(11171,3,3,'ဤကဲ့သို့သော။','“ယွံမိ၊ ဗြဴမပတၠရုပ်သာ်ဍေံ မဖှ်ညံၚ်သာ်ဏအ်ဂှ် ယာံရသ္ဂောံတုဲဂှ် အဲပသၟိၚ်ပကၚ်ရၚ်ကၟိန်ဍုၚ်ရ” ဗောဓိသတ်ဂး။ (ဇ—၄၅၈။ အစွောံ) = “မယ်တော်၊ ဤကဲ့သို့သော ရုပ်ရည်ပိုင်ရှင်မိန်းမကိုရသော် အကျွန်ုပ်တိုင်းပြည်အုပ်ချုပ်မင်းလုပ်အံ့” ဟု ဘုရားလောင်းဆို၏။')
,(11172,3,3,'ငါ','ငါတို့ကဲ့သို့သော။ || “ယွံကောန်၊ မိမဖှ်ညံၚ်အဲဝွံ မထဏိက်တုဲ မအာက္ၜၚ်မ္ဂး မဂွံတသိုက်စိုတ်ညိဟာကောန်။” (ဇ—၄၃၉။ အစွောံ။) = “ချစ်သား၊ ငါကဲ့သို့သောမိခင်ကို ကန်ကျောက်၍ သင်္ဘောသွားခြင်းဖြင့် စိတ်၏ချမ်းသာခြင်းကို သၚ်ရလေမည်လော။”')
,(11173,3,3,'၁။ ထိုသို့သော။ ယင်းသို့သော။ ဤသို့သော။','“ယွံတဳလမၞုံပိုန်၊ ဗရုမဖှ်သာ်ဂှ် အဲမဂွံမိၚ် ပသာ်ဒှ်ညိရောအဴ” သၟိၚ်ဂး။ = “ဘုန်းတော်ကြီးသောအရှင်ဘုရား၊ ထိုသို့သောအသံကို အကျွန်ုပ်ကြားခြင်းကြောင့် အဘယ်သို့ဖြစ်လတ္တံ့နည်း။” || “မူရဴဟိုတ် (ပွကုသဵု) မွဲတုဲ (ဒေံဗြဴ) မဂွံပတၠစရာဲရုပ် မဖှ်သာ်ဝွံဂှ်ရော။” (ဇ—၄၁၅။ အစွောံ။) = “အဘယ်တစ်စုံတစ်ခုသော ကုသိုလ်ကောင်းမှုကြောင့် ချစ်နှမသည် ဤသို့သောရုပ်ရည်အလှပိုင်ရှင် ဖြစ်လာရပါသနည်း။”')
,(11173,3,3,'၂။ အကြင်မည်သော။ ဤမည်သော။ (such and such)','“ယွံကောန်ပိုဲ၊ မူနူကွာန်မွဲမကၠုၚ်ရော။ မဒှ်ကောန်ညးဂှ်ရော” ဇမၞော်ဒမာတ်ဂှ်သၟာန်။ “ယွံမအံက်၊အဲဍိက်မဒၟံၚ်ကွာန်မဖှ်သာ်ဂှ်ရ၊ အဲဒှ်ကောန်ဒမာတ်မဖှ်သာ်ဂှ်ရအဴ” ဗောဓိသတ်ဂး။ (ဇ—၃၈၇။ အစွောံ။) = “ချစ်သား၊ အဘယ်ရွာမှလာသနည်း။ အဘယ်သူ၏သားနည်း” ဟု ပန်းဘဲသူကြီးမေး၏။ “ဤမည်သောရွာ­ နေထိုင်ပါ၏၊ ဤမည်သောသူ၏သားဖြစ်ပါ၏” ဟုဘုရားလောင်းဆို၏။ || “(ယွံခမဳတံ) ၊ မူဂလာန် မၞးတံက္တဵုဗဒှ်ရော” ကျာ်တြဲဂး။ “ဂလာန်မဖှ်သာ်ဝွံ ပိုဲက္တဵုဗဒှ်ရောၚ်အဴ” ခမဳတံဂး။ (ဇ—၂၉၃။ အစွောံ။) = “ရဟန်းတို့၊ ယခုအခါ အဘယ်စကားဖြင့် စည်းဝေးကြကုန်သနည်း” ဟု (မြတ်စွာဘုရား) မေးတော်မူ၍ “ဤမည်သောစကားဖြင့် စည်းဝေးပါကုန်၏” ဟု နားတော်လျှောက်သည်ရှိသော်။ (ညောင်ကန်)')
,(11174,3,1,'သကြားလုံး။',NULL)
,(11175,3,1,'မျိုးဗီဇ။',NULL)
,(11176,3,1,'မျိုးပၚ်။ ပျိုးပၚ်။',NULL)
,(11177,3,3,'အနည်းငယ်သော။ အနည်းငယ်မျှ။ စိုးစဉ်းမျှ။','“ပ္ဍဲလိုက်ဝွံ ဟိုတ်နူဝဳဝဲပ္ဍဲညး မဒးပ္တုဲလဝ်တုဲ ဝဲတံဂှ် မမိက်ကဵုကာလညိည ဟွံဂွံလလံအာဟေၚ်။” (ဇ—၄၂၈။ အစွောံ။) = “လောက­ သူတစ်ပါးအား ရန်ငြိုးရန်စပြုထားသဖြင့် ထိုရန်ငြိုးရန်စတို့သည် အနည်းငယ်သောကာလမျှလည်း မငြိမ်း။” || “ယွံဒေံဗြဴ၊ မမိက်ကဵုပြဝဒုဟ်ညိညဂှ် ဟွံမွဲသက်သက်ပ္ဍဲအဲရ။” (ဇ—၉၂။ အစွောံ။) = “အိုချစ်နှမ၊ စိုးစဉ်းမျှသောပြစ်မှုဟူ၍ လုံးဝငါ့မှာမရှိပါ။”')
,(11178,3,3,'တစ်စုံတစ်ခုသော။ တစ်စုံတစ်ယောက်သော။ တစ်စုံတစ်ခုမျှ။တစ်စုံတစ်ယောက်မျှ။','“ယွံမၞးတံ၊ မမိက်ကဵုညးမွဲကီု ကျာဗြဲဒွအ်ဇကုမၞးတံဟာ။” (ဇ—၁။ အစွောံ။) = “အချင်းတို့၊ တစ်စုံတစ်ယောက်သောသူ၏ကိုယ်ကို မိုးသက်လေသည် ထိခတ်သလော။” || “ပ္ဍဲကာလတၠအဲမဂစိုတ်သၟိၚ်ဂှ် မမိက်ကဵုညးမွဲမွဲ တီညာတ်ကီုဟာ” ဂၞကျာ်သၟာန်။ (ဇ—၄၁၆။ အစွောံ။) = “ဘုရင်အား သၚ်သတ်သောအခါ­ တစ်စုံတစ်ယောက်သောသူသည် သိမြင်သလော” ဟုမိဖုရားမေး၏။ || ‘မမိက်ကုမွဲမွဲ’ ဟုလည်းသုံးနိုင်သည်။ || “မမိက်ကဵုကိစ္စမွဲမွဲ ဗမၞးတိတ်အာနူသ္ၚိရ။” (ဇ—၂၁၂။ အစွောံ။) = “တစ်စုံတစ်ခုသောကိစ္စကြောင့် ပုဏ္ဏားသည် အိမ်မှထွက်သွား၏။” || “ပၞောဝ်ညးဂမၠိုၚ် မမိက်ကုမွဲမွဲ ညာတ်မတ်ဗြဲဟာ။” (ဇ—၁။ အစွောံ။) =“လူများအနက်မှ တစ်စုံတစ်ယောက်သောသူသည် မိုးတိမ်ညွန့်ကို မြင်သလော။” || “ယွံမရာတ်၊ဗရုပံက်ဂှ် မမိက်ကဵုအန္တရာဲမွဲမွဲ ဟွံဒှ်ကုမရာတ်ရ။” (ဇ—၄၁၈။ အစွောံ။) = “အရှင်မင်းမြတ်၊ထိုဥဗျိုင်းမြည်သံသည် အရှင်မင်းကြီးအား တစ်စုံတစ်ခုသောအန္တရာယ်မဖြစ်။” || “သၟိၚ်ဂှ်တုန် —ရာဒနာမိက်တဴကောန်တြုံတုန်လေဝ် မမိက်ကဵုကောန်တြုံမွဲဟေၚ် ဟွံကလိဂွံရ။” (ဇ—၅ဝ၅။ အစွောံ။) = “ထိုမင်းသည် သားဆုပန်သော်လည်း တစ်စုံတစ်ယောက်သောသားကိုမျှ မရ။” || ‘မမိက်မွဲမွဲ’ ဟုလည်းတွေ့ရသည်။ || “နဇုက်ဗၜန်ဂှ်ကဵုဒှ်၊ နဇုက်စၞာံဂှ်ကဵုဒှ်၊ နကၞာၚ်ဆုဂှ်ကဵုဒှ်၊ —နမမိက်မွဲမွဲဂှ် ဂိုၚ်ကေတ်တုဲ—။” (ဇ—၁၃ဝ။ အစွောံ။) = “ကြိုးဖြင့်၄င်း လွန်ဖြင့်၄င်း သစ်ခက်ဖြင့်၄င်း တစ်စုံတစ်ခုကိုယူ၍—။”')
,(11179,3,4,'တစ်စုံတစ်ခုမျှ—တစ်စုံတစ်ယောက်မျှ အနည်းငယ်မျှ။','“ဋ္ဌာန်ဒၞာဲသၟတ်ဗြဴမအာဂှ် မမိက်ကဵုညးမွဲညိညကီု တီဟွံမွဲရ။” = “သူငယ်မ၊သွားသော နေရာအရပ်ကိုတစ်စုံတစ်ယောက်မျှ အနည်းငယ်မျှ မသိကြကုန်။” || “ပွမဟွံသေၚ်ကဵုသဘဴဓဝ်ဂှ် မမိက်ကဵုကာလမွဲညိညဂှ် လ္ပကဵုအဲဒးညာတ်ညိ။” (ဇ—၂၈ဝ။ အစွောံ။) = “တရားနှင့်မညီသော အပြုအမူကိုမည်သည့်အခါမျှ အနည်းငယ်မျှလည်း ငါ့ကိုမမြင်ရစေနှင့်။” || “မမိက်ကဵုကိစ္စမွဲညိညဂှ် ကွာ်လုပ်ဍုၚ်။” (ဇ—၄၉၇။ အစွောံ။) = “အနည်းငယ်သော တစ်စုံတစ်ခုသော ပြုဖွယ်ကိစ္စဖြင့် မြို့တွင်းသို့ ခြေကျင်လျှောက်၍ဝၚ်၏။” || “ယွံသၟိၚ်ၜိုပ်ထဝ်၊ မမိက်သတြုမွဲညိညဂှ် ဟွံမွဲပ္ဍဲအဲရ။” (ဇ—၅ဝ၂။ အစွောံ။) = “ရွှေဟင်္သာမင်း၊ ငါ့အား တစ်စုံတစ်ယောက်သောရန်သူမျှ အနည်းငယ်မျှမရှိ။”')
,(11180,3,1,'အစောင့်နတ်။','‘ဗယိ’ (န) ရှု။')
,(11181,3,1,'လူသေအလောင်းထားသော အဆောက်အဦး၊ ပြာသာဒ်။','“ဗတ်ရဣတဇုသ္ဍိုက်မအံက်ကျာ်ဂန် မပကာဂစိုတ်ပ္ဍဲဍုၚ်ပိုဲတေံဂှ် နကဵုမယူထဝ် ဣတအံက်နာဲထ္ၜုတ်လဝ်ဇွနာဲရလေဝ်ကောန်။” (သၠပတ်အရုဒုမ္မ) = “အကယ်၍သာ ခမည်းတော်ချစ်သောသားတော်သည် ငါတို့မြို့­သေဆုံးပါမူကား အလောင်းထားရာရွှေပြာသာဒ်ဖြင့် ဖခမည်းတော်သည် သင့်အလောင်းကို ထားနိုင်ပါမည်တကား အိုချစ်သား။” || “ဒဵုကဵုလၟုဟ် ပိုဲညးဂမၠိုၚ် မဒးရံၚ်ကမ္မဋ္ဌာန် ပ္ဍဲမယူရောၚ်။” (သၠပတ်ကာလထေရ်) = “ယခုထက်တိုၚ် ငါတို့သည် အလောင်းထားရာအဆောက်အဦး­ အလောင်းကို ကြည့်ရှုကြရကုန်၏။” || “မျူတလာတုန်၊ ပ္ဍုန်တူအှ်ောထဝ်။ တိုန်ပ္တန်လဝ်ရ၊ ဇွတဳလဓဝ်။” (လိက်မေဃကောန်ဒြာဲ) = “အလောင်းထားရာပြာသာဒ်နှင့် ခေါင်းတလားတို့ကို ရွှေထင်းပုံပေါ်တၚ်ကာ အရှင်မြတ်၏အလောင်းကို တၚ်၍ထား၏။”')
,(11182,3,1,'လမ်းပြ။ လမ်းညွှန်။ ရှေ့ဆောင်။','‘မျောဝ်’ (န) နှင့်အတူတူ။ || “ပ္ညပ်အနန္တံ၊ ဓမ္မဂုဏ္ဏာ။ ဒှ်မယျောဝ်ရော၊ သတ်ပ္ဍဲလောကာ။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “အနန္တဂုဏ်တော်ရှိသော တရားတော်မြတ်သည် လောကသတ္တဝါအပေါင်းတို့၏ လမ်းညွှန်ရှေ့ဆောင်ဖြစ်၏။”')
,(11183,3,1,'သေခြင်း။ မရဏ။','သၟိၚ်မရဏ = သေမင်း။')
,(11184,3,9,'အရေအတွက်အစဉ်ကို ပြသောစကားလုံး။ —မြောက်။','မရနုက်ကဵုပိတ္ၚဲ = သုံးရက်မြောက်။ || မရနုက်ကဵုမသုန်သၞာံ = ငါးနှစ်မြောက်။ || မရနုက်ကဵုၜါစှ်ောဝါ = အကြိမ်နှစ်ဆယ်မြောက်။ || “နူဝွံ ပ္ဍဲမရနုက်ကဵုထပှ်တ္ၚဲ ဣတေံစှ်ေကၠုၚ်ရ။” (ဇ—၄၉၇။အစွောံ။) = “ဤမှ ခုနစ်ရက်မြောက်နေ့­ သူဆင်းလာလိမ့်မည်။”')
,(11185,3,1,'စက်သီး။ (ပစ္စည်းဆွဲတၚ်ရာတွင်သုံးသည်)','“မရံက်တိုၚ်ယာ။” (လိက်ကာကဒိပ္ပ။ မဟာကြၚ်။) = “လှေသင်္ဘောရွက်တိုၚ် တၚ်ရာတွင်သုံးသောစက်သီး။”')
,(11186,3,11,'(န) ရှင်ဘုရင်။ ဘုရင်မင်းမြတ်။ ဘုရင်မင်းကြီး။ (ပါဠိ—မဟာရာဇ)','“ယွံမရှာတ်၊ ပ္ဍဲပယာံတ္ၚဲမသၠုၚ် မရှာတ်မကၠုၚ်ဝွံဂှ် မူပၟိက်မွဲမနွံရော” ကျာ်တြဲဂး။ (ဇ—၁၅၁။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ သင်မင်းကြီးသည် အဘယ်အကြောင်းကြောင့် ယခုအလွန်နေမြင့်မှသာလျှင် လာခဲ့တုံသနည်း။” (ညောင်ကန်) || “ဂၞကျာ်မရှာတ်ဝွံ အဲဇိုန်ကဵုမရှာတ်ရ” ဣသိဂး။ (ဇ—၆၆။ အစွောံ။) = “အရှင်မင်းကြီး၏မိဖုရားကို အရှင်မင်းကြီးအား ငါပြန်ပေးအပ်အံ့” ဟုရသေ့ဆို၏။ || “ယွံသၟိၚ်ဣန်၊ ဂလာန်ကနိက်မုသာဂှ် မရာတ်ဟီုရောၚ်သွံ။” (ဇ—၃ဝ၁။ အစွောံ။) = “သိကြားမင်း၊ လိမ်လည်ထိမ်ဝှက်သော မုသားစကားကို သင်မင်းကြီးဆိုဘိ၏။”')
,(11187,3,1,'သြဇာသီး။','မရိုတ်ကၞုဲ = အညာသြဇာ။ || မရိုတ်ဇၞော် = ပိနနဲသြဇာ။ || မရိုတ်ဒူရေန်= ဒူးရင်းသြဇာ။')
,(11188,3,1,'မြရာပင်။',NULL)
,(11189,3,1,'ထိုင်ရာတွင်မှီသောကျောအမှီ။',NULL)
,(11190,3,1,'ဆဲလုံး။',NULL)
,(11191,3,1,'စာလုံး။ အက္ခရာအရေးအသား။',NULL)
,(11192,3,1,'လောက်စာလုံး။','“တိတၟာမလွေၚ် ကဵုညးဟွံဒှ်။” (အာန်ဇုနာန်) =“လောက်စာလုံးပမာဏရှိသောမြေကိုမျှ သူတစ်ပါးအားမပေးနိုင်။”')
,(11193,3,1,'ဆွေမျိုး။',NULL)
,(11194,3,4,'အနံ့နံသည်။','မသသ္အုဲ = ပုပ်စော်နံသည်။ || မသသ္အေၚ် = ကျင်ငယ်နံ့ကဲ့သို့ နံစော်သည်။')
,(11195,3,1,'ဆွေခုနစ်ဆက်။ ဂကူမသထပှ်ဒတောဝ်မ္ဂးဂှ်တုန် ၁) ကောန်၊ ၂) စဴ၊ ၃) စေက်၊ (၄) စး၊ ၅) စေက်၊ ၆) စောက်၊ ၇) စက်၊ ဣၚုဟ်ဗွဲသၟဝ်ထပှ်ဒတောဝ်။ || ဗွဲလတူတုန် ၁) မ၊ ၂) မဇၞော်၊ ၃) မဇၞေက်၊ ၄) မဇၞက်၊၅) မဇၞံက်၊ ၆) မဇၞိဟ်၊ ၇) မဇၞး၊ ဣၚုဟ်မသ္ဂးရောၚ်။ (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။)','မိမိအထက် ၁) ဘ၊ ၂) ဘိုး၊ ၃) ဘေး၊ ၄) ဘီ၊ ၅) ဘၚ်၊ ၆) ဘဲ၊ ၇) ဘော ဟူသော မျိုးဆက်ခုနစ်ဆက်။ || မိမိအောက် ၁) သား၊ ၂) မြေး၊ ၃) မြစ်၊ ၄) တီ၊ ၅) တွတ်၊ ၆) ကျွတ်၊၇) ဆက် ဟူသော မျိုးဆက်ခုနစ်ဆက်။ (မြန်မာအဘိဓါန်)')
,(11196,3,4,'နံစော်သည်။','“ဇွပုဘရံက်၊ လမ္စံက်ဟွံခၠန်။ ဒှ်တယုရ၊ မသမသောန်။” (လိက်သောဝါနနဟောၚ်) = “အလောင်းကောင်သည် ပုပ်ပွမည်းညိုကာ လောက်တက်၍ပုပ်နံနေ၏” || “သ္အုဲအာလအ်လ၊ မသမသောန်။” (လိက်သောဝါနနဟောၚ်) = “ပုပ်သွားသည်မှာကြာ၍ ပုပ်နံနေ၏။”')
,(11197,3,1,'သာဂူ။ သာဂူစေ့။',NULL)
,(11198,3,16,'ငါးခု။','မသုန်စှ်ော = ငါးဆယ်။ || မသုန်လ္ၚီ = ငါးထောၚ်။')
,(11199,3,4,'မရှိသည်။ ကင်းမဲ့သည်။ (နာမ်ပုဒ်တစ်ခုခုနှင့်ဖြစ်စေ၊ ကြိယာပုဒ်တစ်ခုခုနှင့်ဖြစ်စေ တွဲစပ်၍သုံးသော ရှေ့ဆက်ဖြစ်သည်။ ကြိယာဟုဆိုထားသော်လည်း ကြိယာဝိသေသနအဖြစ်သော်၄င်း နာမဝိသေသနအဖြစ်သော်၄င်း သုံးနိုင်သည်ကို သတိပြုရာသည်။ သုံးစွဲသည့်နေရာကိုလိုက်၍ ကြိယာ (သို့မဟုတ်) ကြိယာဝိသေသန (သို့မဟုတ်) နာမဝိသေသနဖြစ်ကြောင်းသိနိုင်သည်။ မိမိဉာဏ်စွမ်းရှိသလောက် အတိုင်းအဆမရှိ တွဲစပ်ဖန်တီးယူနိုင်သည်။ အောက်ပါဥပမာများကို လေ့လာနည်းယူပါ။)',NULL)
,(11200,3,5,'တုန်လှုပ်ခြင်းကင်းစွာ။ မတုန်မလှုပ်။ ခိုင်မြဲစွာ။ (ပါဠိ—နိစ္စလ)','“(ၜိုန်လကိုဟ်ဂှ် ပပရိုက်ကဵုဗောဓိသတ် ဗွဲမလောန်ကီုလေဝ်) စိုတ်ဗောဓိသတ်တုန် မသက္ကုကသဳဟေၚ်။” (ဇ—ဝိဓုရ။ အစွောံ။) = “ထိုဘီလူးက အလွန်နှိပ်စက်အန္တရာယ်ပြုသော်လည်း ဘုရားလောင်း၏စိတ်သည် တုန်လှုပ်ခြင်းမရှိ။” || “ဂတပဏ္ဍိတ မိၚ်ဂလာန်ကောမဟီုဂှ်တုဲ ဗွဲမသက္ကုကသဳတန်ဒၟံၚ်တုဲ ရဴဝွံဂးရ။” (ဇ—၄၅၄။ အစွောံ။) = “ဃဋပဏ္ဍိတမင်းသားသည် နောင်တော်ဝါသုဒေဝမင်းကြီး၏ စကားကိုကြားလျှင် မတုန်မလှုပ်ရပ်၍ (ဤသို့ဆို၏။)” (ညောင်ကန်) || “(သၟိၚ်နာ်တုန်) က္ဍိုပ်ဒလုက်ပၠောပ်ကၠေံ ပ္ဍဲကဝးဂှ်တုဲ မသက္ကုကသဳဟေၚ် တန်ဒၟံၚ်ရ။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “နဂါးမင်းသည် ဦးခေါင်းကို အခွေကြား­ လျှိုသွင်းကွယ်ဝှက်၍ တုန်လှုပ်ခြင်းမရှိဘဲ တည်နေ၏။” || “ပွမၞုံစိုတ်မသက္ကုကသဳဂှ်မွဲ။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “တုန်လှုပ်ခြင်းကင်းသောစိတ် ရှိခြင်းသည်လည်းတစ်ပါး။”')
,(11201,3,4,'အနှစ်မရှိ။ အနှစ်ကင်းမဲ့သည်။','“တၞံဆုဝွံ သြဝ်မသက္ကုကြက်ရောၚ်သွံ။” (ဇ—၂၄၅။ အစွောံ။) = “ဤသစ်ပင်သည် အနှစ်မရှိသလျှင်ကတည်း။” (ညောင်ကန်)')
,(11202,3,4,'အညစ်အကြေးကင်းသည်။','“ခၜိုန်ထဝ်မသ္အး မသက္ကုကၠိုက်လ္ၚေၚ်။” (ဇ—၃ဝ၆။ အစွောံ။) = “အညစ်အကြေးကင်းသော သန့်စင်သောရွှေခွက်။”')
,(11203,3,5,'မခြားမလပ်။ အဆက်မပြတ်။ ဆက်တိုက်။','“ညးပၞာန်တိုက်ဂမၠိုၚ် ဒြေပ်တိုန်အာတုဲ နလွဟ်ဗၞုဟ်တံဂှ် သြဝ်မၞးတံပြိုက်ညိ။ ဗွဲသာ်ဝွံ ညံၚ်ဗြဲမသက္ကုခြာကီု သြဝ်မၞးတံဗဂူဖျေံရ”သၟိၚ်ဂး။ (ဇ—၂၂၉။ အစွောံ။) = “ခြေသည်စစ်သည်များသည် ရှေ့တိုးပြေးတက်၍ လှံလက်နက်တို့ဖြင့် သင်တို့ထိုးနှက်ကြကုန်လော့။ ဤကဲ့သို့ မခြားမလပ်ရွာသောမိုးကဲ့သို့ လက်နက်မိုးကိုရွာချစေကုန်လော့။” || “(မၚ်ဗၠာဲ) ကတာဟကလေဝ် ကလောန်ဍိက်ညး ကၠောန်ဒၟံၚ်မသက္ကုခြာရ။” (ဇ—၁၂၅။ အစွောံ။) = “ကဋာဟကလုလင်လည်း ကျွန်တို့၏ပြုဖွယ်အမှုကို မပြတ်ဆောင်ရွက်နေ၏။”')
,(11204,3,4,'ပလိဗောဓကင်းသည်။ ကြောင့်ကြမဲ့သည်။','“ယွံသၟိၚ်မပြဲ၊ ပိုဲခမဳဂှ် မသက္ကုဂဗုတ်ရောၚ်၊ မဂပ်ဂဝ်ဖအောန်ဂဗုတ်ရောၚ်လေဝ် မရာတ်” ဣသိဂး။ (ဇ—၄ဝ၃။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ငါသည် ပလိဗောဓမရှိသော ရဟန်းတည်း။ (ပလိဗောဓကို နည်းစေအပ်၏။” (ညောင်ကန်)')
,(11205,3,5,'အဝတ်မပါ ကိုယ်ချည်းဗလာ။ ကိုယ်လုံးတီးဖြင့်။','“ကာလသကိုပ်ဒမၠမသက္ကုဂၠိက်ယာတ် မလောတ်ဒၟံၚ်ဂှ် မၚ်ဗၠာဲမိက်သၞာ်ကဵုဗြဴဂှ်ရ။” (ဇ—၃၇၄။ အစွောံ။) = “ခိုးသူကြီးသည် အဝတ်မပါ ကိုယ်လုံးတီးဖြင့်လဲနေစဉ် လုလင်သည် မယားအား သန်လျက်ကိုတောင်း၏။”')
,(11206,3,16,') အရှက်မရှိသော။—သည်။ အရှက်တရားကင်းမဲ့သော။—သည်။','“ညံၚ်တဳဟၟဲကဵုဂၠိက်ယာတ် မသက္ကုဂဝ—။” (ဇ—၅၁၂။ အစွောံ။) = “ကိုယ်ချည်းဗလာ အဝတ်မပါသောအရှက်ကင်းသောတိတ္ထိတို့ကဲ့သို့။”')
,(11207,3,4,'ကြောက်ရွံ့ခြင်းကင်းသည်။',NULL)
,(11207,3,5,'ကြောက်ရွံ့ခြင်းကင်းစွာ။','‘စမိုက်’/‘ဇမိုက်’ (န) လည်းရှု။ || “လၟုဟ်ဍေံဝွံလဝ် မသက္ကုဇမိုက်ရောၚ်ဍေံမကၠုၚ်၊ မတ်ဍေံဗ္ကေတ် သမၞိၚ်ဇကုဍေံဟွံမွဲ ဍေံတံဝွံ ကလော်ရောၚ်။” (ဗောဓိသတ်ချပ်။) (ဇ—၁။ အစွောံ။) =“ယခုလာသည့်သူတို့သည် ကြောက်ခြင်းကင်းစွာလာ၏၊ မျက်စိလည်းနီ၏၊ ကိုယ်အရိပ်လည်းမထၚ်၊ ဤသူတို့သည် ဘီလူးများတည်း” ဟုဘုရားလောင်းကြံ၏။ || “တြုံတၟေၚ်တၟဟ်ကွေံ လဟီုညံၚ်ဗတ်ဇဗတ် မသက္ကုစမိုက် ဂလာန်မဒှ်သၟတ်ရောၚ် မတိတ်ဟီု” ကလော်ချပ်။ (ဇ—၃၉၈။ အစွောံ။) = “ဤယောကျာ်းသည် အလွန်ထူးဆန်းပေစွ။ ဝရဇိန်လက်နက်ကဲ့သို့ အကြောက်ကင်းစွာ မှန်သောစကားကိုသာဆိုပေ၏” ဟုဘီလူးတွေး၏။ || “ပွမန်တံဝွံ မသက္ကုစမိုက်ကဵုပိုဲဟေၚ်သွံ” ဗမာသေံမဂး။ (အကြီုရာဇာဓိရာဇ်) = “မွန်တို့၏အပြုအမူသည် ငါတို့ကို အကြောက်ကင်းသည်တကား” ဟုဗမာနှင့်ရှမ်းတို့ဆိုကုန်၏။ || “ပၞာန်ဗမာဇက်စှ်ေ သက်ကဵုစမိုက်ဟေၚ်။” (အကြီုရာဇာဓိရာဇ်) = “ဗမာစစ်တပ်သည် အကြောက်ကင်းစွာ ချီတက်စုန်ဆင်းလာ၏။”')
,(11208,3,4,'အားကိုးရာမဲ့သည်။ ခိုကိုးရာမဲ့သည်။ ကူညီမည့်သူကင်းမဲ့သည်။','“သၟိၚ်အဇာတသတြုဂှ် ဝေၚ်အာနူကျာ်တြဲမွဲတုဲ မသက္ကုစ္ၜုဲစ္ၜော်ရ။” = “အဇာတသတ်မင်းသည် မြတ်စွာဘုရားမှတစ်ပါး အားကိုးရာမရှိ။” || “ယွံကောန်၊ ညံၚ်ကလေၚ်ကၠုၚ်ကဵုမိရ။ မိလေဝ်မသက္ကုစ္ၜုဲစ္ၜော်ရောၚ်။” (ဇ—၄၃၂။ အစွောံ။) = “ချစ်သား၊ အမေ့ထံပြန်လာခဲ့ပါ။ အမေ့မှာ ခိုကိုးရာမရှိပါ။”')
,(11209,3,3,'ရေမပါသော။','‘ပုၚ်ပၟန်မသက္ကုဍာ်။’ = ‘ရေမပါ နို့သက်သက်ဖြင့်ချက်ထားသောဃနာနို့ထမင်း။’')
,(11210,3,3,'အထိအခိုက်မရှိသော။ ထိပါးခြင်းမရှိသော။ သူတစ်ပါးတို့ ထိပါးနှိပ်စက်ခြင်းငှာ မစွမ်းနိုင်သော။','‘မၞုံညာဏ်မသက္ကုတဍဝ်။’ = ‘အထိအခိုက်မရှိသောဉာဏ်ရှိသည်။ (ဝါ) သူတစ်ပါးတို့ ထိပါးနှိပ်စက်ခြင်းမှကင်းသောဉာဏ်ရှိသည်။’ (ပါဠိ—အပ္ပဋိဟတညာဏ) || “မှာထေရ်ဂဝမ္ပတိ မိၚ်အနုညာတ်သဗ္ဗညုတုဲ ချိုန်ခဏဂှ် ညာဏ်မသက္ကုတဍဝ်က္တဵုဒှ်—။” (ပြကိုဟ်ဂဝမ္ပတိ)')
,(11211,3,3,'ပိုင်ရှင်မဲ့။','ဒြပ်မသက္ကုတၠ = ပိုင်ရှင်မဲ့ပစ္စည်း။')
,(11212,3,4,'ကြောက်ရွံ့ခြင်းကင်းသည်။','“ကၠိက်တံဝွံဂှ် ဍေံဟွံဒှ်ညံၚ်ကၠာတေံသွံ။ ဍေံသိပ်နှက်ဗိုန်လောန် မသက္ကုဒညကမၠရောၚ်” ကၠချပ်။ (ဇ—၄၉၂။ အစွောံ။) = “ဤတောဝက်တို့သည်ကား အခါတိုင်းနှင့်မတူ အလွန်မြဲမြံခိုင်ခံ့၍ ကြောက်ရွံ့ခြင်းကင်း၏” ဟုကျားသည်တွေး၏။')
,(11213,3,4,'အပြစ်ကင်းသည်။ အပြစ်မှလွှတ်သည်။','“အဲဍိက်ကလအ် သၟဝ်ဂၠးဂတာဇိုၚ်ထဝ်မသက္ကုဒုဟ်ကဵုအဲဍိက်ညိ။” (အကြီုရာဇာဓိရာဇ်) = “ရွှေဖဝါးတော်အောက် ရှိခိုးကန်တော့ပါ၏။ ကျွန်တော်မျိုးအား အပြစ်မှလွှတ်တော်မူပါ။”')
,(11213,3,3,'အပြစ်မဲ့သော။ အပြစ်မရှိသော။','“(အမာတ်) မသက္ကုဒုဟ်ဂှ် သၟိၚ်စုတ်ကၠေံဇရေဟ်စာံဂိုၚ်သ္ၚိစာတ်ရ။” (ဇ—၂၈၂။ အစွောံ။) = “အပြစ်မရှိသောအမတ်ကို (မင်းသည်) သံခြေချင်းအနှောင်အဖွဲ့ဖြင့် ဖွဲ့စေ၍ နှောင်အိမ်သို့သွင်းစေ၏။” (ညောင်ကန်)')
,(11214,3,4,'ဘေးရန်ကင်းရှင်းသည်။','“ပတွဵုနူဂှ်တုဲ ကၞိဂမၠိုၚ်ဂှ် မသက္ကုပရိုက်ဘဲဂှ် ဂွံတန်ဒၟံၚ်ရ။” (ဇ—၁၂၈။ အစွောံ။) = “ထိုအခါမှစ၍ ကြွက်အပေါင်းတို့သည် ဘေးရန်ကင်းသည်ဖြစ်ကုန်၏။”')
,(11215,3,5,'မငဲ့ကွက်ဘဲ။ ငဲ့ကွက်ခြင်းမဲ့စွာ။','“ကၠဵုဝွံ ဍေံထောံကၠေံဖျုန် မသက္ကုပမွဲစိုတ်တုဲ ဍေံမအာကၠေံတုဲရ။” (ဇ—မှာဇနက်။ အစွောံ။) = “ထိုခွေးကား ငဲ့ကွက်ခြင်းမဲ့၍ အမဲကၚ်ကိုချ၍ ပြေးလေပြီ။” (မင်းပူးဦးသြဘာသ) || “အနပေက္ခစိတ္တာ၊ ၚ်မၞုံစိုတ်မသက္ကုပၟဲ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ငဲ့ကွက်ခြင်းမရှိသောစိတ်ရှိသည်။”')
,(11216,3,4,'အကျိုးမဲ့သည်။ အချည်းအနှီးဖြစ်သည်။','“(ပ္ဍဲညး) မပကာဂစိုတ်ဂှ် ပွမယာံဂၠာဲရိုဟ်ရေၚ်ဂှ်ကီု ပွမယာံသဓဵုသမ္ၚဟ်တဴဂှ်ကီု မသက္ကုဖဵုဟေၚ်ရ။” (ဇ—၃၁၇။ အစွောံ။) = “သေသောသူ­ ငိုကြွေးမြည်တမ်းခြင်းသည်၄င်း ငိုကြွေးပူပန်ခြင်းသည်၄င်း အကျိုးမရှိ။” || “အဲသကဵုရဂးတုဲဟိုတ်နူမဟွံကဵုပၠန်ဂှ် ဂလာန်ဂှ် မသက္ကုဖဵုရ။” (ဇ—၄ဝ၁။ အစွောံ။) = “ငါပေးပါမည်ဟုဆိုပြီး၍မပေးပြန်ခြင်းကြောင့် ထိုစကားသည် အကျိုးမရှိ၊ အချည်းအနှီးသာတည်း။” || “ဒြပ်အဲမဂၠိုၚ်ဝွံသက္ကုဖဵုဟေၚ် သလေၚ်အာရ။” (ဇ—၁၃၇။ အစွောံ။) = “ငါ၏များစွာသောဥစ္စာတို့သည် အကျိုးမဲ့သာလျှင် ပျက်စီးကုန်ရာ၏။” || “ယြဴပူဂဵုမွဲဂှ် ဍေံဟွံတီဂုန်ညး ဍေံဟွံဂြၚ်ဂုန်ညး ဍေံဟွံခၠေဝ်ပလန်ဂုန်ညးဂှ် မဒးသိပ်ဂၠိပ်ဟုဲဟာဲကဵုပူဂဵုဂှ် မသက္ကုဖဵုရ။” (ဇ—၃ဝ၈။ အစွောံ။) = “ကျေးဇူးမသိတတ်သော ကျေးဇူးမတုံ့ပြန်တတ်သောသူနှင့်တကွ မှီဝဲပေါင်းဖော်ခြင်းသည် အကျိုးမရှိသည်သာတည်း။”')
,(11217,3,5,'အကြောက်ကင်းစွာ။',NULL)
,(11218,3,4,'တန်ဖိုးမထား။ အလေးမထား။ (?)','“ထောံကၠေံဗွဲမသက္ကုဗျဟ်” (ဇ—၁၇၉။အစွောံ။) = “အပပြု၍ (တန်ဖိုးမထားပစ်ပယ်၍) ။” || “ညံၚ်စက်ဂိတုသီုလျး မဒွံဂၠံမတ်ဗြဲလမ္စံက်ကီု မသက်ကဵုဗျဟ်မဒှ်ပ္ဍဲစိုတ်သၟိၚ်—။” (အာန်ဇုနာန်) = “အလင်းရောင်နှင့်တကွသောလမင်းသည်မည်းသောမိုးသားတိမ်လိပ်ကို ထိတွေ့သကဲ့သို့ မင်း၏စိတ်­ အလေးမထားခြင်းသည်ဖြစ်၏။”')
,(11219,3,4,'မာန်စွယ်ကျိုးသည်။ ထောင်လွှားခြင်းကင်းသည်။','“အမာတ်အ္စာသၟိၚ်ပန်တအ်ဂှ်ပြိုၚ်ပညာကဵုမဟောသဓဟွံမာန်တုဲ မသက္ကုဗျအ်ဂှ်ဒှ်တုဲ ဂွဒစိုၚ်ဒၟံၚ်မုက်ရ။” = “မင်း၏ဆရာအမတ်လေးယောက်တို့သည် မဟော်သဓာနှင့် ပညာချင်းမယှဉ်နိုင်သဖြင့် မာန်စွယ်ကျိုးကာ ရှက်၍ခေါင်းငုံ့နေရသည်။” || “နူတ္ၚဲဂှ်ဟေၚ်ပတွဵုတုဲ ခမဳမသုန်ကၠံ မာနသဝ်အာဂှ်ဒှ်တုဲ ရဴဇြုံမပိုက်ကၠေံဂၞေဟ်ကီုဒှ်တုဲ မသက္ကုဗျအ်ကီုဒှ်တုဲ —။” (ဇ—၂၄၅။ အစွောံ။) = “ထိုရဟန်းတို့သည် ထိုအခါမှစ၍ ပယ်အပ်သောမာနရှိကုန်သည်ဖြစ်၍ နုတ်အပ်သောအစွယ်ရှိကုန်သောမြွေတို့ကဲ့သို့ မာန်ထောင်လွှားခြင်းကင်းကုန်သည်ဖြစ်၏။” (ညောင်ကန်)')
,(11220,3,4,'မာန်ယစ်ခြင်းကင်းသည်။ မာန်ကင်းသည်။ မာနကင်းသည်။',NULL)
,(11221,3,5,'‘မသက္ကုပၟဲ’ နှင့်အတူတူ။',NULL)
,(11222,3,4,'အနာရောဂါကင်းသည်။','“လာပ်မဂွံမပြဲ ပွမသက္ကုယဲဝွံ ဂပ်ဂဝ်ရာဒနာမိက်ရ။”= “အနာရောဂါကင်းစၚ်ခြင်းသည် မြတ်သောလာပ်တစ်ပါးဖြစ်၍ တောင့်တအပ်၏။” || “ယွံသၟိၚ်မပြဲ၊ မရှာတ်မသက္ကုယဲဂှ်ဒှ်ညိဟာ။” (ဇ—၅ဝ၂။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ အရှင်မင်းကြီးသည် အနာရောဂါကင်းသည် ဖြစ်ပါ၏လော။”')
,(11223,3,16,'မသက္ကုတၟောၚ် (တၟောၚ်တၟိတ်) (ကြိဝိ) မောပန်းခြင်းမရှိဘဲ။ ပင်ပန်းခြင်းကင်းစွာ။','“ယွံဥပး၊ မူရဴဂၠံၚ်တရဴမွဲ ဥပးမကၠုၚ်ရော၊ ဥပးမကၠုၚ်ဂှ် မသက္ကုတမောင်ဂှ် ဂွံဒှ်ညိဟာ” ကျာ်တြဲသၟာန်။ = “ဒါယကာ၊ မည်သည့်လမ်းခရီးဖြင့် လာခဲ့သနည်း၊ ဤသို့လာခြင်း­ ပင်ပန်းခြင်းကင်းသဖြင့် လာရ၏လော။” || “အိုဿီုညးဂမၠိုၚ်ဂှ် မသက္ကုလၟောၚ် နတသိုက်ဂှ်ဒှ်တုဲ မသ္ဍးအာကၠေံနူကန္တာဂှ်—။” (ဇ—၄ဝ၅။ အစွောံ။) = “အားလုံးသောသူတို့သည် ပင်ပန်းခြင်းကင်းကုန်သည်ဖြစ်၍ ချမ်းသာသဖြင့် ထိုကန္တာရမှ ထွက်ခွါခဲ့ကုန်၏။”')
,(11224,3,4,'အားကိုးရာမဲ့သည်။ ခိုလှုံရာမဲ့သည်။','“လၟုဟ်ဝွံ မၞးတံညးဂမၠိုၚ် မသက္ကုသလဲလၜေါ်ရောၚ်သွံ။” (ဇ—၄၃၂။ အစွောံ။) = “ယခုသင်တို့သည် အားကိုးရာမဲ့နေလေပြီတကား။”')
,(11225,3,4,'ယုံမှားခြင်းကင်းသည်။ သံသယမရှိ။','“မိၚ်တဝှ်ကျာ်သာ်ဝွံတုဲ ခမဳပုထုဇန်တံမသက္ကုသၠေဟ် ဂွံဒှ်တဴအိုတ်ရ။” (ဇ—၂၆၄။ အစွောံ။) = “ဤသို့ဟောတော်မူသောခဏ­ ပုထုဇဉ်ရဟန်းတို့သည် ယုံမှားခြင်းကင်းကုန်၏။” (ညောင်ကန်)')
,(11226,3,4,'စေးနှဲခြင်းကင်းသည်။ အလှူအတန်းအပေးအကမ်း­ အလွန်ရက်ရောသည်။','“(ပ္ဍဲဘဝအတိက်တေံ) ဂမှဳဝွံ အဲဝေတ်တုဲ ဒဒှ်မသက္ကုသ္အေတ်ဂှ်အဲပတုဲ ပ္ဍဲဖဵုဒါန်အဲပ္တန်လဝ်တုဲရ”ကျာ်တြဲဂး။ (ဇ—၄၅ဝ။ အစွောံ။) = “အတိတ်ဘဝက ဤရဟန်းကို ငါဆုံးမ၍ စေးနှဲခြင်းကင်းအောင်ပြု၍ အလှူ၏အကျိုး­ တည်စေ၏” ဟုဘုရားမိန့်တော်မူ၏။')
,(11227,3,16,'မြဲမြံသော။—စွာ။ မချွတ်မလွဲ။','“(ကျာ်တြဲမၞုံ) ဉာဏ်မဂြၚ်တီအတိက်အနာဂတ်ပစ္စုပ္ပန် မသက္ကုသ္ဍဝ်ဂှ် နွံတဴရသေၚ်ဟာ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “မြတ်စွာဘုရားသည်အတိတ်အနာဂတ်ပစ္စုပ္ပန်ကို မချွတ်မလွဲ ထိုးထွင်းသိမြင်တော်မူသောဉာဏ်ရှိ၏။” || ‘သက်သ္ဍဝ်’နှင့်အတူတူ။')
,(11228,3,7,'ထိုနောက်။ တစ်ဆက်တည်း။','“အဲလ္ၚောဝ်ကျာ်ရ၊ ပ္ဍဲမသက္ကုသၟိၚ်ဂှ် အဲချူလိက်ရ။” = “ကျွန်တော်ဘုရားရှိခိုးသည်။ ထိုနောက် ကျွန်တော်စာရေးသည်။” || “ပ္ဍဲမသက္ကုသၟိၚ်အဲလ္ၚောဝ်ကျာ်တုဲဂှ် အဲချူလိက်ရ။” = “ကျွန်တော်ဘုရားရှိခိုးပြီးနောက်တစ်ဆက်တည်းကျွန်တော်စာရေးသည်။” || ‘မသက်သၟိၚ်’ ဟူ၍လည်းရေးသည်။')
,(11229,3,16,'(ကြိဝိ) အကြွင်းမဲ့။ မခြွင်းမချန်။ အကုန်အစင်။','“က္တဵုဒဒှ်ဍေံအိုတ်သီု နူတမ်ဒဵုကၞောတ် ဍေံလဴစကဵုမိဍေံ မသက္ကုသၟိဟ်ရ။” = “သူ၏အဖြစ်အပျက်အလုံးစုံကို အစမှအဆုံးအထိ မခြွင်းမချန်ဘဲ သူ၏မိခင်အား အကုန်အစင်ပြောပြ၏။” || “ပတွဵုနူလပှ်ဂွံကၞိ မသွံဂွံၚုဟ်ထဝ်မွဲကနန် သီုမသက္ကုသၟိဟ်ဟေၚ် (မၚ်ဗၠာဲ) ဟီုပ္တီသေဋ္ဌဳရ။” (ဇ—၄။ အစွောံ။) = “ကြွက်သေကိုကောက်ရပြီးလျှင်ရောင်း၍ တစ်ခြၚ်ရွေးသောအသပြာကို ရရှိသည်မှအစပြု၍ အကြောင်းအလုံးစုံကို မကြွင်းမကျန်စေဘဲ လုလင်သည် သူဋ္ဌေးအားပြောပြ၏။” || “ဗောဓိသတ်ရံၚ် တီကေတ်ကလော် မသက္ကုသၟိဟ်။” (ဇ—၆။ အစွောံ။) = “ဘုရားလောင်းသည် ဘီလူးကိုမြင်၍ဘီလူးဖြစ်ကြောင်းကို အကြွင်းမဲ့သိ၏။”')
,(11230,3,5,'အကြောင်းမဲ့။',NULL)
,(11231,3,4,'အစာအဟာရကင်းမဲ့သည်။ အစာအဟာရပြတ်လပ်သည်။','“(မိကဵုမအဲဒမၠုမတ်ၜါဝွံဂှ်) မသက္ကုအဟာမဒှ်တုဲ မ္ဒးဗျဵုထၚ်ဒၟံၚ်တုဲ မဒးပကၠေံကာဂစိုတ်ရသွံ” သၟိၚ်တၟာတ်ဂး။ (ဇ—၃၉၉။ အစွောံ။) = “ငါ၏မျက်မမြင်မိဘနှစ်ပါးသည် အစာအာဟာရကင်းမဲ့သည်ဖြစ်၍ ဆာလောင်ငတ်မွတ်လျက် သေကြရရှာတော့မည်တကား။”')
,(11232,3,5,'မကြာမြင့်မီ။','“ပ္ဍဲမသက်ဂတာပ်လအ် မၞိဟ်ပ္ဍဲသ္ၚိစာတ်ဂှ်အိုတ်အာ—။” (ဇ—၃၉၈။ အစွောံ။) = “မကြာမြင့်မီလျှင် နှောင်အိမ်တို့­ လူတို့သည်ကုန်၏။” || ‘ဟွံဂတာပ်လအ်’ နှင့်အတူတူ။')
,(11233,3,7,'ထိုနောက်။ ပြီးနောက်။ တစ်ဆက်တည်း။ အခြားမဲ့။','“ပ္ဍဲမသက်သၟိၚ် ညးလ္ၚောဝ်ကျာ်ဓဝ်သၚ်တုဲဂှ် ညးခၞံပြကိုဟ်ရ။ = “ဘုရားတရားသံဃာကို ရှိခိုးပြီးနောက်­ သူကျမ်းပြုစုသည်။” || “ညးလ္ၚောဝ်ကျာ်၊ လ္ၚောဝ်ဓဝ်၊ လ္ၚောဝ်သၚ်ရ။ ပ္ဍဲမသက်သၟိၚ်ဂှ် ညးခၞံပြကိုဟ်ရ။”= “ဘုရားတရားသံဃာကို သူရှိခိုး၏။ ထိုနောက်တစ်ဆက်တည်း သူကျမ်းပြုစုသည်။” || “ဇာဒိသိုၚ်ဗၠာဲဂှ် ပကာဂစိုတ်ရ။ ပ္ဍဲမသက်သၟိၚ်ဂှ် ဇာဒိသိုၚ်ဗၠာဲမွဲ ကၠုၚ်စိုပ်ပၠန်။” (ဇ—၁၅၂။ အစွောံ။) = “ထိုခြင်္သေ့ပျိုသည် သေလေ၏။ ထိုနောက်­ တစ်ခုသောခြင်္သေ့ပျိုသည် ရောက်လာပြန်၏။” || “ပ္ဍဲမသက်သၟိၚ်ဍေံမဟီုဂှ် ကောန်သၟိၚ်ဂှ်ဟီုတိုန်ရ။” (ဇ—၄၁၆။ အစွောံ။) = “သူပြောပြီးနောက်­ ထိုမင်းသားပြော၏။” || “ပ္ဍဲမသက်သၟိၚ်ချိုတ်တုဲဂှ် မူမကတဵုဒှ်ရော။” = “သေသည်၏အခြားမျဲ့­ ဘာဖြစ်လာမည်နည်း။” || ‘မသက္ကုသၟိၚ်’ နှင့်အတူတူ။')
,(11234,3,10,'(နဝိ) ကြီးသော။ ကြီးမြတ်သော။',NULL)
,(11235,3,11,'(န) လူများ။ ပြည်သူများ။','“မဟာဇန်ဂမၠိုၚ် ရပ်ကေတ်ထိုၚ်ဖျေဲနပရှ်ေတုဲကၠုၚ်ကောံပ္ဍဲတရၚ်သ္ၚိသေဋ္ဌဳရ။” (ဇ—၇၈။ အစွောံ။) = “လူအများသည် တောင်း၊ အိတ်အစရှိသည်တို့ကိုယူ၍ (သူဋ္ဌေး) အိမ်တံခါး­ စည်းဝေး၏။” (ညောင်ကန်) || ‘မှာဇန်’ နှင့်အတူတူ။')
,(11236,3,11,'(န) မဟာထေရ်။ (ဝါတော် ၂ဝ ကျော်သောရဟန်းတော်။)',NULL)
,(11237,3,10,'(န) မဟာဗျူဟာ။ (စစ်ရေး၊ နိုင်ငံရေးစသည်တွင် အဓိကရည်မှန်းချက် ပြီးမြောက်အောင်မြင်စေရေးအတွက် အကျုံးဝၚ်သော ကဏ္ဍအသီးသီးတို့ကို ဆက်စပ်လွှမ်းခြုံ၍ စီစဉ်ခင်းကျင်းခြင်း။)','‘နဲဗျူဟာ’ လည်းရှု။')
,(11238,3,11,'(န) မဟာဘုတ်။ ပထဝီ (မြေ) ၊ အာပေါ (ရေ) ၊ တေဇော (မီး) ၊ ဝါယော (လေ) ဟူသော ဓါတ်ကြီးလေးပါး။','(ပါဠိ—မဟာဘူတ)')
,(11239,3,11,'(န) မဟာမိတ်။','(ပါဠိ—မဟာမိတ္တ)')
,(11240,3,10,'(န) မဟာယာန ဗုဒ္ဓဘာသာဂိုဏ်း။ (မြောက်ပိုင်းဗုဒ္ဓဘာသာဟုလည်း ခေါ်သည်။)',NULL)
,(11241,3,10,'(န) မြတ်စွာဘုရား၏ ကြီးမြတ်သောတပည့်။ မဟာသာဝက။ (ရှစ်ကျိပ်ရှိသည်။)',NULL)
,(11242,3,11,'(န) သမုဒ္ဒရာ။','သုရာမဟာသမှိတ်ဒုဟ် (ဇ—၈၁။ အစွောံ။) = မဟာသမုဒ္ဒရာတမျှ ကဲ့ရဲ့၍မကုန်နိုင်သော သုရာအရက်၏အပြစ်။')
,(11243,3,3,'အမည်တွင်သော။ ဤမည်သော။','“ယွံဗမၞး၊ မူဆမစိုပ်ရော” ကၠဵုသၟာန်။ “စိုပ်ဋ္ဌာန်မဟိမုဝွံရ” ဗမၞးဂး။ (ဇ—၁၁၃။ အစွောံ။) = ပုဏ္ဏားကို မြေခွေးသည် “ပုဏ္ဏား၊ အဘယ်အရပ်နည်း” ဟုမေးလေ၏။ “ဤမည်သောအရပ်တည်း” ဟု ပုဏ္ဏားဆိုသည်ရှိသော်—။ (ညောင်ကန်) || “ကောန်အဲမဟိမုသာ်ဝွံ အဲမကဵုစှ်ေသဟာဲအဲ—။” (ဇ—၁၂၅။ အစွောံ။) = “ငါသည် ဤအမည်ရှိသောငါ၏သားကို သင်၏အထံသို့ စေ၏။” (ညောင်ကန်) || “ဖျုန်သတ်မဟိမုသာ်ဂှ် အဲဍိက်မိက်စအဴ” ကၠဵုဂးကဵုဇာဒိသိုၚ်။ (ဇ—၁၄၃။ အစွောံ။) = “ဤမည်သောသား၏အသားကို အကျွန်ုပ်စားလိုပါ၏။”')
,(11244,3,12,'(န) မဟူရာကျောက်။ (သ—မဓုရာ)',NULL)
,(11245,3,10,'(န) မိဖုရား။',NULL)
,(11246,3,1,'ဖာလာစေ့။ (ပါဠိ—လောလုပ)','မအဳသၟတ် = ဖာလာငယ်။ (ပါဠိ—ကောရဂ·) || မအဳဇၞော်= ဖာလာကြီး။ (ပါဠိ—ပထဝဳကာ)')
,(11247,3,1,'အဖ။ ဖခင်။ အဖေ။','“ယွံကောန်၊ ပြောဟိတ်သၟိၚ်ဂှ် မဒှ်မအံက်နာဲရကောန်” မိဂး။ (ဇ—၄၈၇။ အစွောံ။) = “ချစ်သား၊ မင်း၏ပုရောဟိတ်သည် သင်၏ဖခင်တည်း။” || (၁၊ ဒေဝပုတ္တမာရ် = မာရ်နတ်သား။ ၂၊ ကိလေသမာရ် = ကိလေသာဆယ်ပါး။ ၃၊ အဘိသၚ်္ခါရမာရ်= ကမ္မဝဋ်။ ၄၊ ခန္ဓမာရ် = ခန္ဓာငါးပါး။ ၅၊ မစ္စုမာရ် = သေခြင်းတရားဟူ၍ ငါးမျိုးရှိသည်။)')
,(11248,3,11,'(န) မာရ်။ ကောင်းမှုကို ပယ်သတ်တတ်သောတရား။ (ပါဠိ—မာရ)','“ဟာဲမာအရိုၚ်၊ မဂၠိုၚ်မောဟ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “ဟယ်မောဟထူပြောသောမာရ်နတ်ရိုင်း။”')
,(11249,3,1,'အဖုအလုံးအနာ။ အိုင်းအမာ။','ယဲမာ = အိုင်းအနာရောဂါ။')
,(11249,3,4,'ဝပ်သည်။','“ညးဂမၠိုၚ်ညာတ်ဒမၠတံဂှ်တုဲ ဖေက်တုဲ မာကၠေံသြိုဟ်ဒဵုတိရ။” (ဇ—၂၆၅။ အစွောံ။) = “လူတို့သည်ဓါးပြတို့ကိုမြင်သည်ရှိသော် ကြောက်ကုန်၍ ရင်ဘတ်မြေထိအောင် ဝပ်ကုန်၏။” || “ပ္ဍဲတံဇိုၚ်ကျာ်တြဲဂှ် စိၚ်မာဒၟံၚ်တုဲ—။” (ဇ—၄ဝ၉။ အစွောံ။) = “(ထိုဆင်မသည်) သဗ္ဗညုမြတ်စွာဘုရား၏ခြေတော်ရင်း­ ဝပ်၍—။” (ညောင်ကန်)')
,(11250,3,9,'—ကား။ —မူကား။','“ဍေံဟွံအာဘာရ။ ဟိုတ်မ္ဂးမာ ဍေံယဲအာရ။” = “သူကျောင်းမသွားပါ။ အကြောင်းမူကား သူဖျားသွားသည်။”')
,(11251,3,10,'(န) ၁။ မာဂဓတိုင်းသားတို့ပြောဆိုသော ရှေးဟောင်းဘာသာစကား။',NULL)
,(11251,3,10,'(န) ၂။ ပါဠိဘာသာ။',NULL)
,(11252,3,10,'(န) သိကြားမင်း၏အမည်တစ်မျိုး။',NULL)
,(11253,3,10,'(န) သိကြားမင်း၏ ရထားထိန်းနတ်သားအမည်။',NULL)
,(11254,3,10,'(န) အမိ။ မိခင်။ အမေ။',NULL)
,(11255,3,10,'(န) ခေါင်းစဉ်အညွှန်း။ မာတိကာ။',NULL)
,(11256,3,11,'(န) မာတုဂါမ။ မိန်းမ။ (ရဟန်းတော်က အမျိုးသမီးကို ခေါ်သောအမည်။)',NULL)
,(11257,3,11,'(န) ၁။ ကလေးသူငယ်တို့ကို ဖမ်းစားတတ်သည်ဟုဆိုသော နတ်သမီး။',NULL)
,(11257,3,11,'(န) ၂။ သူငယ်နာရောဂါတစ်မျိုး။','(ပါဠိ—မာတရ)')
,(11258,3,10,'(န) မာန။','မာနဇၞော် = မာနကြီးသည်။ || မာနသၠုၚ် = ဘဝင်မြင့်သည်။')
,(11258,3,10,'(ကြိ) မာနကြီးသည်။ မာနထားသည်။','“လ္ပမာနကဵုမိမညိ။” = “မိဘကို မာနမထားပါနှင့်။”')
,(11259,3,1,'‘မနက်’ ရှု။',NULL)
,(11260,3,10,'(န) မာယာ။ လှည့်ပတ်ဖြားယောင်းခြင်း။','“မိၚ်ဂၞကျာ်ဟီု၊ သီုကဵုမာယျာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “မာယာနှင့်တကွ မိဖုရားပြောသည်ကို (မင်းသား) ကြားလတ်သော်။”')
,(11261,3,10,'(န) ပန်း။ ပန်းကုံး။',NULL)
,(11262,3,1,'၁။ ပန်းကုံး။',NULL)
,(11262,3,1,'၂။ တောစံပယ်ပင်။',NULL)
,(11263,3,1,'ပန်းကုံး။ ပန်းဆိုင်း။','မာလေကၟက်ကအ် = လည်ဆွဲပန်းကုံး။ || “(သၟိၚ်တုန်) မာလေနူကအ်ဇကုဂှ် ဂိုၚ်ပ္တိတ်တုဲ ပ္ကဴဇၟန်ဂ္ညိကအ်ဂှ် ကွက်စုတ်ပ္ဍဲကအ်မၚ်ဗၠာဲ (ဗောဓိသတ်) တုဲ—။” (ဇ—၃ဝ၉။ အစွောံ။) = “(မင်းသည်) မိမိလည်­ဆင်သော ပန်းဆိုင်းကို (ချွတ်၍) ဘုရားလောင်း၏လည်­ ဆင်စေ၍—။” (ညောင်ကန်) (မာလေ = ပ္ကဴဇၟန်ဂ္ညိကအ်) || “ဂၞကျာ်ဟွံညာတ် မၞိက်မာလေဝ်ကၟက်ကအ်ဂှ်တုဲ သၟာန်တိုန်သၟိၚ်နာ်ဂှ်ရ။” (ဇ—ဝိဓုရ။ အစွောံ။)')
,(11264,3,1,'၁။ အမေ။ အမိ။ မိခင်။',NULL)
,(11264,3,1,'၂။ ငယ်ရွယ်သောအမျိုးသမီး၏အမည်ရှေ့တွင် တပ်၍ခေါ်သောအခေါ်အဝေါ်။ မ။','မာံသိုက်မန်ကေုာံမိမန်ဆာန် = မောင်သိုက်မွန်နှင့်မမွန်ချမ်း။')
,(11264,3,1,'၃။ လူကြီးအမျိုးသမီး၏အမည်ရှေ့တွင် တပ်၍ခေါ်သောအခေါ်အဝေါ်။ ဒေါ်။','နာဲသာအံၚ်ကဵုမိအံၚ်မန် = ဦးသာအောင်နှင့်ဒေါ်အောင်မွန်။')
,(11264,3,1,'၄။ ရွယ်တူအမျိုးသမီးကို ယဉ်ကျေးစွာခေါ်ဝေါ်သော အခေါ်အဝေါ်အသုံးအနှုန်း။ အမိ။ သင်။ ခင်ဗျား။','“ယွံမိဆာန်မန်၊ မိစပုၚ်တုဲရဟာ။” = “အိုမချမ်းမွန်၊ အမိထမင်းစားပြီးပြီလား။”')
,(11265,3,1,'၁။ အဘွား။',NULL)
,(11265,3,1,'၂။ အထိန်းတော်မ။','“မိနဳမိတှ် အတိုၚ်ဂၞကျာ်မဂး ပဗက်ရ။” (သၠပတ်ကုလဇာတ်) (မိနဳ = မိတှ်) = “အထိန်းတော်မသည် မိဖုရားဆိုသည့်အတိုင်း လိုက်နာလုပ်၏။” || “မိမိန်တံကီု၊ သီုၝဲဂမာ။ မိနဳမိတှ်၊ သၟဟ်သၟန်ညဳသာ။” (လိက်ပဒုမဝတဳ) (မိမိန်၊ မိနဳ၊ ၝဲဂမာ၊ မိတှ် = အထိန်းတော်မ)')
,(11266,3,1,'ကလေးထိန်းအမျိုးသမီး။ အထိန်းတော်မ။ (ကလေး၊ လူအို၊ သူနာစသူတို့ကို) ပြုစုစောင့်ရှောက်သောမိန်းမ။ (A Nurse)','ကောန်ဗြဴသေဋ္ဌဳမွဲဂှ် ညာတ်ဂၠဴဥဿဘမွဲ မၞုံသဗအ်မသၠုၚ်လောန်တုဲ ပ္ဍဲသ္ၚိဂှ် ညးရဴဂဴပူဇဴသကာဍေံ (သၟတ်ဗြဴ) ညာတ်တုဲ ဍေံသၟာန်မိမိန်ၝဲဂမာဍေံဂှ်ရ။ “ယွံမိ၊ ဍေံမၞုံသဗအ်ပ္ဍဲစးဂှ် ညးပူဇဴသကာဍေံဂှ် မူယၟုသတ်ဂှ်ရော။” “ယွံကောန်ဗြဴ၊ သတ်မဒုၚ်ပူဇဴသကာညးဂှ်ဒှ်သၟိၚ်ဂၠဴဥဿဘရကောန်ဗြဴ” မိနဳဂှ်ဂး။ (ဇ—၂၃၂။ အစွောံ။) (A rich man''s daughter noticed that in her father''s house, a great fuss was made over a fine bull, and asked her nurse what it meants. “Who is this, nurse, that is honoured so?” The nurse replied that it was a right royal bull. (The Jataka)” =“ချစ်သမီး၊ သူတကာတို့၏အပူဇော်ကို ခံရသောသတ္တဝါသည် နွားမင်းဥဿဘတည်း” ဟု အထိန်းတော်မ၊ဆို၏။/ “မိနဳဂမၠိုၚ်တုန် ဗလိုပ်ဖုံဗဗိုဟ်မြမောဝ်ကဵုဗောဓိသတ်တုဲ—။” (ဇ—တေမဳ။အစွောံ။) = “အထိန်းတော်မတို့သည် ဘုရားလောင်းအား ရေချိုးပေး၍ နံ့သာလိမ်းကျံပေး၏။”/ “မိနဳရုဇာမိၚ်တုဲ ဂရေၚ်ပ္တီကောန်ဗြဴသၟိၚ်ရ။” (ဇ—နာရဒ။ အစွောံ။) = “ရုစာမင်းသမီး၏အထိန်းတော်သည်ကြားလတ်၍ — (မင်းသမီးအား) ကြားလျှောက်၏။” (မင်းပူးဦးသြဘာသ) /‘မိမိန်’၊ ‘ၝဲဂမာ’ တို့နှင့်အတူတူ။')
,(11271,3,1,'အဘွား။',NULL)
,(11272,3,1,'မိဘ။',NULL)
,(11273,3,1,'ကလေးထိန်းအမျိုးသမီး။ အထိန်းတော်မ။ (ကလေး၊ လူအို၊ သူနာစသူတို့ကို) ပြုစုစောင့်ရှောက်သောမိန်းမ။ အလုပ်အကျွေးမိန်းမ။','“ကောန်ဗြဴသေဋ္ဌဳမွဲဂှ် ညာတ်ဂၠဴဥဿဘမွဲ မနွံသဗအ်မသၠုၚ်လောန်တုဲ — ဍေံသၟာန်မိမိန်ၝဲဂမာဍေံဂှ်ရ။” (ဇ—၂၃၂။ အစွောံ။) = “တစ်ယောက်သောသူဋ္ဌေးသမီးသည် မြင့်သောလဘို့ရှိသော နွားဥသဘကိုမြင်၍ အထိန်းတော်မအားမေး၏။” || (မိမိန် = ၝဲဂမာ) || “ကောန်ပြောဟိတ်ဂှ် (သၟိၚ်) ကဵုအာကေတ်နၚ်တုဲ ဇိုန်ကဵုမိမိန် မွဲဟာန်ကေုာံကောန်တြုံသၟိၚ်ဂှ် မွဲစွံကဵုညးမြိမြန်လဝ်ရ။” (ဇ—၃၁ဝ။ အစွောံ။) (So the king had the chaplain’s son brought and given into the charge of nurses to be carefully tended together with the young prince. (The Jataka) = “(ပုရောဟိတ်၏သားကို) ယူငင်စေ၍ အထိန်းတို့အားပေး၍ မင်းသားနှင့်တကွနက်မွေးမြူစေ၏။” (ညောင်ကန်) || “လဗြဴမွဲဂှ် မဒှ်မိမိန်သမ္ဘာဗမၞးဂှ်ရ။” (ဇ—၆၂။အစွောံ။) = “ထိုမိန်းမအိုသည် ပုဏ္ဏားမယား၏အလုပ်အကျွေးမိန်းမတည်း။” || ‘မိနဳ’ နှင့်အတူတူ။')
,(11274,3,1,'အထိန်းတော်မ။','“သီုမိလေၚ်ၝဲဂမာ။” (သၠပတ်ရာဇာသာန်) (မိလေၚ် = ၝဲဂမာ) = “အထိန်းတော်မနှင့်တကွ။”')
,(11275,3,1,'မိခင်။ အမေ။','“ရဴဝွံဟီုကဵုမိအံက်မအံက်တံဂှ်ရ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) =“ထိုကဲ့သို့ မိခင်ဖခင်တို့အားပြော၏။” || “ကဵုအခေါၚ်ညိ၊ မိအံက်ကျာ်ဂန်။” (လိက်သၟိၚ်အသး။နန္ဒသာရ။) = “အခွင့်ပေးတော်မူပါ မယ်တော်ဘုရား။” || “လဴဗစစိ၊ ကဵုမိအံက်ဂၞဴ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “မွေးသမိခင်အား ပြောပြ၏။”')
,(11276,3,1,'မီးပေါက်။ (နားခွက်ရှိ ယမ်းကို မီးရှို့၍ပစ်ရသော ရှေးခေတ်သေနတ်၊ အမြောက်။)','“ရေၚ်လဝ်ကမံက်၊ အမၠံက်ပြမ။ မ္ၚးအမၠံက်၊ မဳဖံက်ကံတ္ၚ။ မ္ၚးမဳဖံက်၊ သေဏာတ်ပြံက်ရ။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) || “ညးအပ္ဍဲဍုၚ် ဗိုတ်ကၠဟ်ဒးမဳဖံက်မြတ္ၜူ ပၞာန်တၠညးစိၚ်ဗ္တာၚ် တသိုတ်တိတ်အာ။” (အကြီုရာဇာဓိရာဇ်) = “မြို့တွင်းမှ မီးပေါက်သေနတ်များ ပစ်ခတ်သဖြင့် (ဆင်ဖြူရှင်) ဗညားဦး၏တပ်များ ဆုတ်ထွက်ရပြန်သည်။” (ရာဇာဓိရာဇ်အရေးတော်ပုံကျမ်း။ နိုင်ပန်းလှ။) || “သေနာတ်အမၠံက်၊ မေဖံက်ဂၠိုၚ်ရာ။” (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “သေနတ်၊ အမြောက်၊ မီးပေါက်စုံလၚ်စွာ။”')
,(11277,3,1,'ကျပ်ခိုး။',NULL)
,(11278,3,1,'ဘာ။ အဘယ်။','‘မူ’ နှင့်အတူတူ။ || “နာဲထောံလဝ်ယာဲ၊ မုယာဲမံၚ်ပ။” (လိက်ရတနပဇ္ဇောတ) = “ငါမိခင်အား သၚ်ချစ်သားစွန့်ထားသဖြင့် မိခင်နေ၍ ဘာထူးတော့မည်နည်း။”')
,(11279,3,16,'(ပါ) (န) မျက်နှာကိုကြည့်ခြင်း။ မျက်နှာလိုက်ခြင်း။',NULL)
,(11280,3,5,'ဧကန်။ မုချ။','“ဓဝ်ရုပ်နာံဂှ်၊ ဒှ်လီုမုချ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “ရုပ်နာမ်တရားသည် မုချအမှန်ဖြစ်ပျက်နေ၏။”')
,(11281,3,3,'မုချသေချာဖြစ်သော။','“ဣဝွံ ဖဵုဒါန်ဗွဲမုချဖလရ။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) =“ဤသည်ကား မုချသေချာဖြစ်သော ဒါန၏အကျိုးတည်း။”')
,(11282,3,10,'(န) သူတစ်ပါးကောင်းကျိုးခံစားရသည်ကို ဝမ်းမြောက်ဝမ်းသာဖြစ်ခြင်း။ မုဒိတာ။',NULL)
,(11283,3,10,'(န) နူးညံ့ခြင်း။',NULL)
,(11284,3,12,'(န) မုဒရက်သီး။ စပျစ်သီး။',NULL)
,(11285,3,10,'(န) ဘုရားရဟန္တာစသည့် သူတော်သူမြတ်။ မုနိ။',NULL)
,(11286,3,10,'(န) လိမ်လည်ပြောဆိုသောစကား။ မုသား။','‘ဟွံမွဲမုသာ လၚ်္ကာဟွံကလိတ်။’ = ‘မုသားမပါ လၚ်္ကာမချော။')
,(11286,3,10,'(န) (ကြိ) လိမ်လည်ပြောဆိုသည်။ လိမ်ညာသည်။','“အဲမၚ်မွဲဒၟံၚ်သဳလရောၚ်၊ အဲဟွံမုသာရ။” = “ငါသီလစောင့်နေပါသည်။ ငါမုသားမပြောပါ။”')
,(11287,3,10,'(န) လိမ်လည်သောစကား။ လှည့်စားသောစကား။','“မုသာဝါစာမ္ဂးဂှ် လဟီုကနိက်တလန်။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “မုသာဝါစာဆိုသည်မှာ လိမ်လည်လှည့်စားသောစကားတည်း။”')
,(11288,3,10,'(န) လိမ်လည်ပြောဆိုခြင်း။ မုသာဝါဒ။',NULL)
,(11289,3,1,'မုသားသမား။',NULL)
,(11290,3,1,'၁။ ရာသီ။ (season)','“က္ၜၚ်မွဲဂှ် ယဝ်ကျာမုသုံဒးမ္ဂး အာဍုၚ်သုဝဏ္ဏဘုံရောၚ်ဂး။” (ဇ—၃၆ဝ။ အစွောံ။) = “တစ်စီးသောသင်္ဘောသည် ရာသီလေလမ်းကြောင်းမှန်လျှင် သုဝဏ္ဏဘူမိပြည်သို့ သွားမည်ဟုဆို၏။” || “မသုန်ကၠံပြၚ်၊ ကောန်က္ၜၚ်ရဲသာ။ ရံၚ်မုသုံဒး၊ ပိုက်တၟံပၠးယာ။” (လိက်တပူတဗဝ်) = “ငါးရာကျော်သော သင်္ဘောသားတို့သည် ရာသီလေကိုကြည့်၍အခါသင့်သောအခါ ကျောက်ဆူးကိုနုတ်၍ ရွက်လွှင့်ထွက်ခွါကုန်၏။”')
,(11290,3,1,'၂။ မုတ်သုံလေ။ မုတ်သုံရာသီ။ (monsoon)',NULL)
,(11290,3,1,'၃။ အချိန်အခါ။','“ဒှ်ကျာ်ပြာ်သတ်၊ ပ္ဍဲဘဒြကဝ်။ မုသုံဒးအဴ၊ နဳဗာန်စဴလ္ၚောဝ်။” (လိက်ဂါထာလ္ၚောဝ်ကျာ်) = “ဘဒ္ဒကမ္ဘာ­ ဘုရားဖြစ်ပွင့်တော်မူကာ သတ္တဝါအပေါင်းကို ကယ်ချွတ်တော်မူပြီးနောက် အချိန်အခါတန်၍ နိဗ္ဗာန်စံဝၚ်တော်မူ၏။” || “ခါဂှ်နာဲညး၊ ဇမၞးပၞာန်မာ။ ဒးမုသုံရ၊ တၞဟ်နယာတြာ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “တိုအခါ မာရ်ကိုအောင်သောမြတ်စွာဘုရားသည် ကြွမြန်းတော်မူရန် အချိန်အခါတန်၏။”')
,(11291,3,1,'ဦးလေး။','သဳမူနော်တြ = ဒေါ်လေး၊ ဦးလေး၊ မိကြီး၊ ဘကြီးဟူသော ဆွေမျိုးများ။ || ‘အမူ’ ရှု။')
,(11292,3,1,'(ပန်းထိမ်သည်၊ ဆေးရောင်းသူတို့ ချိန်တွယ်ရာတွင်သုံးသော) အလေးငယ်လေး။ တစ်မူး။ တစ်ကျပ်သား၏ရှစ်ပုံတစ်ပုံ။','ထဝ်ၜါမူ = ရွှေနှစ်မူးသား။ || “ညးဗၞိက်အလီ၊ သမ္တီမူၜဲ။” (လိက်လက္ခဏပိ) = “မူးပဲကိုပင်မှတ်သားသော ကုန်သည်အလိမ်။”')
,(11293,3,1,'ဦးလေး။','မူဒေံမိ = အမေ့မောင်ဖြစ်သောဦးလေး။ || မူဒေံမ = အဖေ့ညီဖြစ်သောဦးလေး။')
,(11294,3,16,'ဘာ။ ဘာလဲ။','“မူဗှ်ေပဒၟံၚ်ရော။” = “နင်ဘာလုပ်နေသလဲ။”')
,(11295,3,3,'ဘယ်လောက်။ ဘယ်လောက်များ။',NULL)
,(11296,3,16,'ဘာ။ အဘယ်။ အဘယ်ဟာ။','“မူဂှ် မၞးတံမဟီုရော” ကျာ်သၟာန်ခမဳဂမၠိုၚ်ရ။ (ဇ—၁၃၂။ အစွောံ။) = “အဘယ်ကို သင်တို့ပြောဆိုကြကုန်သနည်း။” || “(ခမဳကောကာလိကဂှ် တွံဓဝ်ဂးတုဲ) မူဂှ်ဒှ်တမ်ဓဝ် မူဂှ်ဒှ်ဒေါဝ်ဓဝ် မူဂှ်ဒှ်ကၞောတ်ဓဝ်ရော ချပ်ဂၠာဲဟွံဒး—။” (ဇ—၁၇၂။ အစွောံ။) = “ကောကာလိကရဟန်းသည် တရားဟောအံ့ဟုဆိုကာ အဘယ်ဟာက တရား၏အစ၊အဘယ်ဟာက တရား၏အလယ်၊ အဘယ်ဟာက တရား၏အဆုံးဟု ရှာကြံမရဖြစ်ကာ—။”')
,(11297,3,3,'ဘယ်လောက်။ အဘယ်မျှ။','မွဲစိဗၞတ်ဇမ္ၚောဲ၊ မူစိဇမ္ၚောဲ = ဘယ်လောက်အကွာအဝေး။ || “ကျာဗြဲဝွံ မွဲစိဗၞတ်ဇမ္ၚောဲ ဍေံမပိုက်အာရော။” (ဇ—၁။ အစွောံ။) = “မိုးသက်လေသည်အဘယ်မျှလောက်သော အကွာအဝေးသို့ တိုက်ခတ်သွားသနည်း။”')
,(11297,3,9,'အမေးဝါကျကြိယာကို လေးနက်စေသောစကားလုံး။','‘မစိ’ ဟုလည်းရေးသည်။ || “ယွံကောန်အဲရာဓ၊ မိနာဲဂှ် ပွမယုတ် မစိဍေံပ ဟွံပဟာကောန်။” (ဇ—၁၉၈။ အစွောံ။) = “ချစ်သားရာဓ၊ သင်၏အမိသည်ယုတ်မာသောအကျင့်ကို ကျင့်သလော၊ မကျင့်သလော။” (ညောင်ကန်)')
,(11298,3,5,'ဘယ်လောက်ကြာကြာ။ ဘယ်သောအခါ။ ဘယ်တော့။ဘယ်တုန်းက။','“ယွံလၟ၊ တၠအဲကၠုၚ်နူဍုၚ်ဗာရာဏသဳတေံဂှ် မူစိလလအ်မသ္ဂောံစိုပ်ဏအ်ရော။” (ဇ—၅၁၄။ အစွောံ။) = “မုဆိုး၊ ဗာရာဏသီပြည်မှ သၚ်လာခဲ့သည်မှာ သည်ကိုရောက်ရန်ဘယ်လောက်ကြာပါသနည်း။” || “သၟတ်ဗြဴဝွံ မူစိလအ်မသလးဂဝ်ဂၞဴရောအဴ။” (ဇ—၄၅၄။ အစွောံ။) = “ဤအမျိုးသမီးငယ်သည် ဘယ်တော့သားဖွားမည်နည်း။” || “ယွံတၠညး၊ မွဲစိလအ်တၠညးမဟီုရောအဴ” ညးသၟာန်၊ “ထပှ်တ္ၚဲဂတတုဲ အဲဟီုရ” သၟိၚ်ဂး။ (ဇ—၄၂၂။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ဘယ်တော့ပြောပါမည်နည်း” ဟုမေးလတ်သော်၊ “ရှေ့ခုနစ်ရက်­ ငါပြောမည်”ဟုမင်းဆို၏။ || “ယွံတဳလ၊ မစိလအ်တဳလစိုပ်အဲဝွံရော” ကျာ်တြဲသၟာန်ထေရ်ဂှ်။ (ဇ—၃၇၆။ အစွောံ။) = “ငါ့ရှင်၊ ဘယ်တုန်းက သၚ်ရောက်ပါသနည်း။” (မှတ်ချက်။ အပြောစကားတွင် ‘ဆလအ်’/‘ဆောဝ်လအ်’ ဟုသုံးကြသည်။)')
,(11299,3,7,'ဘာဖြစ်လို့။ အဘယ်ကြောင့်။','“ခဍာ်ဂမၠိုၚ်ဂှ် မူဒှ်ကၠေၚ်အယိၚ်ဍေံ ဟွံမွဲသ္ဂးရော။” (ဇ—၁၄ဝ။ အစွောံ။) = “အဘယ်အကြောင်းကြောင့် ကျီးတို့အား အဆီမရှိသနည်း။” (ညောင်ကန်)')
,(11300,3,9,'တိုက်တွန်းသည့်အနက်ဖြင့် အမေးသဘောသက်ရောက်သော ဝါကျအဆုံးသတ်စကားလုံး။—ပါလား။','“အမူ၊ စပုၚ်တုဲစဴမူဒှ်ရော။” = “ဦးလေး၊ ထမင်းစားပြီးမှပြန်ပါလား။” || “(ယွံသၟိၚ်ကၞုဲ) ၊ ပ္ဍဲသြၚ်လ္ပာ်တေံဂှ် သတ်ကြုက်ကီု သတ်ဖါကီု နွံဗဝ်ဒၟံၚ်ရ။ ကၠောံအာဂၠာဲစဍေံမူဒှ်ရော” ကျာံဂး။ (ဇ—၂ဝ၈။ အစွောံ။) = “မျောက်မင်း၊ ထိုမှာဘက်ကမ်း­ သရက်သီး၊ တောင်ပိနနဲသီးတို့သည် အလွန်ပေါများကုန်၏။ သင်သည် သွား၍ရှာစားပါလား။”')
,(11301,3,16,'ဘယ်နေရာ။','“မူဒၞာဲမအာရော။” = “ဘယ်ကိုသွားမလဲ။”')
,(11302,3,5,'ဘယ်က။ အဘယ်မှ။','“မူနူသၟိၚ်ၜိုပ်မကၠုၚ်ရော။” (ဇ—၁၃၆။ အစွောံ။) = “ဟင်္သာမင်း ဘယ်ကလာသနည်း။” || “မူနူအဲမပကာဂစိုတ်တုဲ မကၠုၚ်က္တဵုဒှ်ၜိုပ်ထဝ်ဝွံရော” ဗောဓိသတ်ဗစာရဏာမွဲ—။ (ဇ—၁၃၆။ အစွောံ။) = “ငါသည် အဘယ်မှစုတေ၍လျှင် ဤရွှေဟင်္သာအဖြစ်­ဖြစ်သနည်း” ဟုဆင်ခြင်သည်ရှိသော်—။ (ညောင်ကန်)')
,(11303,3,5,'ဘာပြုလို့။ ဘာကြောင့်။','“မူပဗှ်ေဟွံကၠုၚ်ဝေၚ်သ္ၚိပိုဲရော။” = “ဘာဖြစ်လို့ ငါတို့အိမ်ကို နၚ်လာမလည်သလဲ။”')
,(11304,3,16,'မေးမြန်းရာ­သုံးသော အမေးစကား။ အဘယ်။','“မူရဴကိစ္စမွဲ မၞးတံမကၠုၚ်ရော။” (ဇ—၃၂၆။ အစွောံ။) = “အဘယ်ကိစ္စဖြင့် သင်တို့လာကြကုန်သနည်း။” || “ပၞောဝ် (တြုံ) ပန်သာ်ဝွံ မူရဴတြုံမွဲ အဲမဂပ်ဂဝ်ဂိုၚ်လဝ်ညိရော။” (ဇ—၂ဝဝ။ အစွောံ။) = “ဤယောကျာ်းလေးယောက်အနက် အဘယ်ယောကျာ်းတစ်ယောက်ကို ငါယူရန်သင့်လျော်မည်နည်း။” || “ယွံခမဳတံ၊ မူရဴဂလာန်မွဲ မၞးတံမဟီုရော” ကျာ်တြဲသၟာန်။ (ဇ—၁၁၈။ အစွောံ။) = “ရဟန်းတို့၊ အဘယ်မည်သောစကားကို သင်တို့ပြောဆိုကြကုန်သနည်း။” || “မူရဴညးမွဲ သှ်သၟာန်အဲမသၟဟ်ရထရော။” (ဇ—၂၄၄။အစွောံ။) = “ငါနှင့်ကွပြောဆိုခြင်းကို ပြုအံ့သောငှာ အဘယ်သူသည် စွမ်းနိုင်အံ့နည်း။” (ညောင်ကန်)')
,(11305,3,10,'(န) မူလအစ။ အခြေခံ။ အရင်းခံ။',NULL)
,(11306,3,10,'(န) အခြေခံအကြောင်းရင်း။ မူလဘူတ။',NULL)
,(11307,3,11,'(န) မုန်လာ။ (ပါဠိ—မူလက)','“ယြဴပ္ဍဲကာလမွဲ သၠမူလာဂှ် သ္ပက္ဍိုၚ်တုဲ ဂွံဗၠးဗြဲရ။” (ဇ—၄၂၅။ အစွောံ။) = “အကြင်အခါ­ မုန်လာရွက်ကို ထီးလုပ်၍ မိုးလွတ်ရာ၏။” || “ရာဲကီု မူလာကီု က္ဍိုပ်ကြဴကီု က္ဍိုပ်ကွာဲကီု—။” (ဇ—၅ဝ၅။ အစွောံ။) = “မုန်ညင်းကို၄င်း မုန်လာကို၄င်း ပိန်းဥကို၄င်း မျောက်ဥကို၄င်း—။”')
,(11308,3,1,'မူလမှဆင့်ပွားသောအရာ။ မူလီ။',NULL)
,(11309,3,1,'လိုက်နာရမည့် အခြေခံချမှတ်ချက်။ မူဝါဒ။',NULL)
,(11310,3,5,'ဘာကြောင့်။ အဘယ်ကြောင့်။','“မူဟိုတ်ညးဟွံကၠုၚ်ရော။” = “ဘာကြောင့်သူမလာသနည်း။”')
,(11311,3,5,'အမှန်တကယ်။','“အဲသ္အာမေခု၊ လၟုဟ်ဝွံဂျ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ယခုပင်လျှင် ကျွန်ုပ်အမှန်တကယ်သွားတော့အံ့။” || “ဇက်တိတ်တွဳ၊ သ္ပဂမှဳဂျ။ ထပှ်က္ဍိုၚ်ရ၊ သီုဗော်ပြဝါ။ ဇက်တိတ်မေခု၊ ဍုၚ်လ္ၚုအာ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ခုနစ်ပြည်ထောင်မင်းတို့သည် ပရိသတ်အခြံအရံများနှင့်တကွ အမှန်တကယ် တောထွက်ရဟန်းပြုကြရာ တိုင်းနိုင်ငံတို့သည် လူသူကင်းဆိတ်ကုန်၏။” || “ဗစဲဒါန်မွဲမေခု၊ ဇကုမဒးပ္တုဲကၠာ။ ဒါန်ဂှ်ရောၚ်သ္ဂောံဗက်အာ၊နာဲသာတိတ်ဟီုတွံထ္ၜး။” (လိက်ပရေၚ်ခန္ဓ) = “မိမိပြုထားအပ်သော အမှန်တကယ် အထောက်အပံ့ဒါနတစ်ခုတည်းသာလျှင် မိမိနှင့်တကွလိုက်ပါသွားနိုင်မည်ဟု မြတ်ဘုရားဟောပြထားတော်မူ၏။” || “သဘဴညးဝေၚ်၊ လလေၚ်မွဲစု။ ဓဝ်ကုသဵုဟေၚ်၊ ဟွံသေၚ်လ္ၚု။ အကုသဵုကၠာ၊ ယောၚ်ယာထဥ။ ဍေံလေပ်ကျဇၞး၊ အဲညးမေခု။” (လိက်ဝိဓူရ) = “လောင်းကစားခြင်းမည်သည် အဆုံးအရှုံးလည်းတစ်မျိုးဖြစ်တတ်၏၊ ကုသိုလ်ချည်း အကျိုးပေးသည်မဟုတ်၊ အကုသိုလ်အကျိုးပေးသောအခါ အရှုံးအနိုင်သည် သူသူငါငါအား အမှန်တကယ်ဖြစ်တတ်စမြဲပင်။”')
,(11312,3,10,'(န) ကောင်းကင်။',NULL)
,(11313,3,5,'‘မေခု’ နှင့်အတူတူ။','“သၟတ်ဂှ်တုန်ကွေံ၊ ဒှ်မၞိဟ်မေဃု။ ဝိမာလကၠာ၊ ကုမ္မာဒုၚ်ယၟု။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။)')
,(11314,3,1,'ဘုရင့်မယ်တော်မိဖုရားကြီး။',NULL)
,(11315,3,11,'(န) ၁။ မေထုန်ရာသီ။ (ဆယ့်နှစ်ရာသီတွင် မိန်းမယောကျာ်းရုပ်ဖြင့် မှတ်အပ်သောတတိယရာသီ။)',NULL)
,(11315,3,11,'(န) ၂။ မေထုန်။ လိၚ်ဆက်ဆံခြင်း။', 'ပအာတဴဓဝ်မေထုန်။ သွိုန်ဗပိုန်ဓဝ်မေထုန်။ သိပ်ဂၠိပ်ဓဝ်မေထုန်။ = မေထုန်အမှုကိုပြုသည်။ မေထုန်မှီဝဲသည်။ လိၚ်ဆက်ဆံသည်။ကာမစပ်ရှက်သည်။')
,(11316,3,1,'နန်းတွင်းသူ။',NULL)
,(11317,3,1,'‘မဳဖံက်’ ရှု။',NULL)
,(11318,3,11,'(န) သေရည်။ အရက်သေစာ။ သုရာ။ (ပါဠိ—မေရယ)','သုရာမေရဲ =သေရည်သေရက်အမျိုးမျိုးကို ခြုံခေါ်သောအမည်။')
,(11319,3,1,'လေမုန်တိုင်း။','လဗိုတ်ကျာမေလံၚ် = လေပြင်းမုန်တိုင်း။ || “ညံၚ်ရဴဂြိုပ်ထဝ် ဒွံကျာမေလံၚ်ဇမ္ကာတ်တုဲ ရဴမတၟဝ်ဒၟံၚ်ကီု။” (ဇ—ဝိဓုရ။ အစွောံ။) = “လေပြင်းထိသောတောသည် လဲလျက်တည်နေဘိသကဲ့သို့။”')
,(11320,3,4,'ငဲ့သည်။ ငဲ့ကွက်သည်။ ငဲ့ညှာသည်။','မမဲတဴဒဒှ်ပယျၚ် = ပဥ္စင်းအဖြစ်ကို ငဲ့သည်။ (ပါဠိ—ဥပသမ္ပဒါပေက္ခ) || “ဥပသမ္ပဒါပေက္ခဿ။ န်ညးမမဲဒဒှ်ပယျၚ်။ ဝါ။ န်ပယျၚ်လံၚ်။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “ပဥ္စင်းအဖြစ်ကိုငဲ့သောသူ။ ပဥ္စင်းခံလိုသောသူ။ ပဥ္စင်းလောင်း။” || “သှ်ပ္တဴလဝ်ဓဝ်သဳလတုဲ မဲကဵုလာပ်လာဘ—တုဲ ပလီုကၠေံသဳလရ။” (သ္ဂုတ်သွာတ်သဳမသုန်။ နာဲမန်ၜိုပ်ထဝ်။) = “သီလကိုဆောက်တည်ပြီးလျှင် လာဘ်လာဘကိုငဲ့ကွက်၍ သီလကိုဖျက်၏။”')
,(11321,3,10,'(န) အနုမောဒနာပြုခြင်း။',NULL)
,(11322,3,10,'(န) မိုက်မှောင်ခြင်း။ တွေဝေခြင်း။ အမှန်အမှား မခွဲခြားနိုင်ခြင်း။ မောဟ။',NULL)
,(11323,3,10,'(န) တွေဝေမိုက်မဲခြင်းကြောင့်ဖြစ်သော အဂတိတရား။ မောဟာဂတိ။',NULL)
,(11324,3,4,'(နို့) စို့သည်။','မဴတှ် = နို့စို့သည်။ || “ဂွံမဴတှ်မိသေၚ်ဟာ၊ မာတာမိကျာ်ဂန်။” (လိက်လက္ခဏာဒိပ္ပဗိန္ဒော) = “မာတာမယ်တော်၏နို့ကို စို့ရသည်မဟုတ်လော။”')
,(11325,3,1,'တစ်ကျပ်၏လေးပုံတစ်ပုံ။ တစ်မတ်။','ထဝ်လယိုင်မွဲမး = ရွှေတစ်မတ်သား။')
,(11326,3,1,'ဝှေးသီး။',NULL)
,(11327,3,1,'သလဲသီး။',NULL)
,(11328,3,1,'ရှောက်နူပင်။',NULL)
,(11329,3,11,'(န) ၁။ လမ်းကြောင်း။',NULL)
,(11329,3,11,'(န) ၂။ ကိလေသာကိုပယ်၍ နိဗ္ဗာန်ကိုအာရုံပြုနိုင်သောလမ်းကြောင်း။ မဂ်။',NULL)
,(11330,3,11,'(န) နိဗ္ဗာန်ရောက်ကြောင်း အကျင့်လမ်းစဉ်။ မဂ္ဂၚ်ရှစ်ပါး။ (၁။ သမ္မာဒိဋ္ဌိ =ကောင်းစွာမြင်ခြင်း။ ၂။ သမ္မာသၚ်္ကကပ္ပ = ကောင်းစွာကြံခြင်း။ ၃။ သမ္မာဝါစာ = ကောင်းစွာပြောခြင်း။ ၄။ သမ္မာကမ္မန္တ = ကောင်းစွာပြုခြင်း။ ၅။ သမ္မာအာဇီဝ = ကောင်းစွာအသက်မွေးခြင်း။ ၆။ သမ္မာဝါယာမ = ကောင်းစွာအားထုတ်ခြင်း။ ၇။ သမ္မာသတိ = ကောင်းစွာအောက်မေ့ခြင်း။ ၈။ သမ္မာသမာဓိ = ကောင်းစွာတည်ကြည်ခြင်း။)',NULL)
,(11331,3,4,'တပ်မက်သည်။ မက်မောသည်။ တွယ်တာသည်။','“သ္ပဟိုတ်ကဵုပွမသ္ဍိုက်ဆာန်၊ ပွမသ္ဍိုက်မၠိုက်၊ ပွမသၞေံသၞဴ၊ ပွမမက်ဂၠက်တံဂှ်တုဲ မက္တဵုဒှ်ဒတူတလာဲအိုတ်ရောၚ်။” (အဘိဏှသုတ်။နာဲမန်ၜိုပ်ထဝ်။) = “ချစ်ခင်ခြင်း၊ နှစ်သက်ခြင်း၊ မြတ်နိုးခြင်း၊ တပ်မက်ခြင်းတို့ကို အကြောင်းပြု၍ ပူပန်ပင်ပန်းခြင်းဖြစ်ရကုန်၏။” || “ပွမဟွံဂွံထၞေန်စပ်မက်ဂၠက် ပ္ဍဲဒဒိုက်ဝဋ်သံသာကီု။” (မိတၠထဝ်။ ပါလိတ။) = “သံသရာဝဋ်ဆင်းရဲ­ မတပ်စွန်းမတွယ်တာခြင်း။”')
,(11332,3,16,'(န) မျက်စဉ်း။ မျက်စဉ်းဆေး။','‘မစေန်’/‘ယန်မတ်’ လည်းရှု။')
,(11333,3,11,'(န) မဂ်တရား ဖိုလ်တရား။',NULL)
,(11334,3,4,'တပ်မက်သည်။ လိုချင်စိတ်ပြင်းပြသည်။',NULL)
,(11335,3,11,'(န) တပို့တွဲလ။ (ပါဠိ—မာဃ)',NULL)
,(11336,3,1,'၁။ ကျိတ်ပၚ်။ (အစေ့ကို ပုတီး၊ လက်ကောက် လုပ်ရသော အလေ့ကျပေါက်သောအပၚ်တစ်မျိုး)','မမာ် = ကျိတ်စေ့။')
,(11336,3,1,'၂။ ပြောင်းစပါး။ (ကောက်နှံ) (သြောံမာ်) (ပါဠိ—ဝရက)',NULL)
,(11336,3,1,'၃။ ကုလားပဲ။','“တၞဟ်နဗ္စချေံဂှ် သတ်မာ်ညးၜိုဟ်ကၠေံတုဲ ညးကေတ်နၚ်သကိုဟ်စုတ် ပ္ဍဲဒၞိဟ်ဂှ်ရ။” (ဇ—၁၇၆။ အစွောံ။) = “မြင်းတို့၏အကျိုးငှာ ကုလားပဲတို့ကိုပြုတ်ပြီးလျှင် ဆောင်ခဲ့ကုန်၍ မြင်းစားခွက်­ ထည့်ကုန်၏။” (ညောင်ကန်) || “(ကၞုဲဂှ်) ဍေံစတဴမာ်ဂှ်ရ။” (ဇ—၁၇၆။အစွောံ။)')
,(11337,3,4,'ချိတ်သည်။','မာ်သၞေဝ်ဂၠုၚ် = လှေပဲ့ကိုချိတ်သည်။ || ‘ဂၟာ်’ ရှု။')
,(11338,3,4,'၁။ တောင်းသည်။','မိက်ဂတှ် = အကြွေးတောင်းသည်။ မြီတောင်းသည်။ || “သမ္ၚေဟ်ညးၜါ သမ္ဘာကဵုတၠသ္ၚိ ပြာပ်စှ်ေအာကွာန်ဗ္ၚတေံတုဲ အာမိက်ဂတှ်ရ။” (ဇ—၃၂ဝ။ အစွောံ။) = “သူကြွယ်လင်မယားနှစ်ယောက်တို့သည် အကြွေးတောင်းရန် လယ်တောရွာသို့သွား၏။” || “မၚ်ဗၠာဲမိက်သၞာ်ကဵုဗြဴဂှ်ရ။” (ဇ—၃၇၄။ အစွောံ။) = “လုလင်သည် မယားထံ သန်လျက်ကိုတောင်း၏။”')
,(11338,3,4,'၂။ လိုချင်သည်။ အလိုရှိသည်။','“တ္ၚဲဏအ် အဲဟွံမိက်အာဘာရ။” = “ဒီနေ့ကျွန်တော်ကျောင်းမသွားချင်ဘူး။”')
,(11339,3,4,'ဆိုလိုသည်။ ရဟန်းသံဃာများ တရားဟောရာတွင် အဆုံးသတ်စကား။','“ကဵုဂွံအာစိုပ်နိဗ္ဗာန်ညိကၠာရမိဂ္ဂး။” = “နိဗ္ဗာန်ကိုရောက်ရပါစေသောဝ်။” || “ပူဂဵုဂှ် ကလိဂွံဒုတိယၛာန်တုဲ ဂွံအာက္တဵုဒှ် ပ္ဍဲဗြီုအဘဿဝဵုတေံရ မိဂ္ဂးအဓိပဲါရောၚ်။” (ဇ—၁၃၅။ အစွောံ။) = “ထိုပုဂ္ဂိုလ်သည် ရအပ်သောဒုတိယဈာန်ဖြင့် အာဘဿရဗြဟ္မာ့ပြည်သို့ လားရောက်ရ၏ဟု ဆိုလိုရင်းအဓိပ္ပါယ်တည်း။”')
,(11340,3,9,'၁။ ပြုလို၊ ဖြစ်လိုသည့်သဘောကို ပြသောစကားလုံး။ —ချင်။ —လို။','မိက်ဂွံစ =စားချင်သည်။ || မိက်ဂွံအာ = သွားချင်သည်။')
,(11340,3,9,'၂။ ဖြစ်ပျက်မည့်အရိပ်အယောၚ်ရှိသည့် သဘောကိုပြသောစကားလုံး။ —ချင်။','“ကောန်ၚာ်ဏအ် ဇကုမိက်ဂွံကတဴဒၟံၚ်ညိ။” = “ဤကလေးသည်အနည်းငယ်ကိုယ်ပူချင်နေသည်။” || ‘သၟိက်ဂွံ’ (စည်း) လည်းရှု။')
,(11341,3,4,'၁။ ချင်ခြင်းတပ်၍ (တစ်ခုခုကို) စားချင်သည်။','“ဗြဴမၞုံဂၠံဂဝ်ဂှ် မိက်စစၞဖျးဖျးရ။” =“ကိုယ်ဝန်သည်မိန်းမသည် ချဉ်သောအစာကို ချင်ခြင်းတပ်စားချင်သည်။”')
,(11341,3,4,'၂။ (တစ်စုံတစ်ဦးနှင့်တကွ) ဖောက်ပြားသည်။ လွန်ကျူးသည်။','“ဂၞကျာ်—ဂှ် မိက်စဂမာချေံသၟိၚ်ဂှ်လေဝ် အဲဂွံညာတ်တုဲရ။” (ဇ—၅၃၆။ အစွောံ။) = “ထိုမိဖုယားသည် မင်း၏မြင်းထိန်းနှင့်တကွ ဖောက်ပြားသည်ကိုလည်း ငါမြင်ခဲ့ရပြီးပြီ။” || “သမ္ဘာပြောဟိတ်ဂှ် ဍေံမိက်စဗမၞးမွဲ။” (ဇ—၄၈၁။ အစွောံ။) = “(ထိုပုရောဟိတ်၏မယားသည်) ပုဏ္ဏားတယောက်နှင့် လွန်ကျူးသောအကျင့်ကို ကျင့်၏။” (ညောင်ကန်)')
,(11342,3,4,'တောင့်တသည်။','“တသိုက်ကာမ၊ ပၠစေတနာ။ သၟိက်ဂွံစသိုၚ်၊ အတိုၚ်မိက်ရာ။” (လိက်ဝိဓူရ) = “ကာမချမ်းသာကို တောင့်တသည့်အတိုင်း ခံစားလို၏။” || “အဲကောန်မိက်ရာ၊ဒဒှ်ဂမဳ၊ သာံမဏဳယျာ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ရဟန်းသာမဏေအဖြစ်ကို သား ဖြစ်သောကျွန်ုပ်သည် တောင့်တပါ၏။”')
,(11343,3,11,'(န) ၁။ မျက်နှာ။','လဳမုက်၊ လာၚ်မုက် = မျက်နှာသစ်သည်။ || ဗဗိုဟ်မုက် = (မျက်နှာကို) သနပ်ခါးလိမ်းသည်။')
,(11343,3,11,'(န) ၂။ အရှေ့မျက်နှာ။ မျက်နှာစာ။','မုက်သ္ၚိ = အိမ်မျက်နှာစာ။')
,(11343,3,11,'(န) ၃။ (စက်ဝိုင်း၏) အချင်း။','“ဆုတၞုၚ်ဏအ် မုက်ဍေံနွံစှ်သုန်ၝောံတဲရ။” = “ဤသစ်လုံးသည် မျက်နှာစာအချင်း ဆဲ့ငါးလက်မရှိသည်။”')
,(11343,3,11,'(န) ၄။ တည်ပၚ်။ တည်သီး။','သတ်မုက် =တည်သီး။ || “ပ္ဍဲဂအာၚ်ကွာန်ဂှ် တၞံမုက်ဇၞော်မွဲတၞံနွံ။” (ဇ—၁၇၇။ အစွောံ။) = “ထိုရွာဟောင်းမြေကွက်­ တည်ပၚ်ကြီးတစ်ပင်ရှိ၏။”')
,(11344,3,4,'မျက်နှာထားမပျော့မပျောင်းဖြစ်သည်။',NULL)
,(11345,3,4,'မျက်နှာပူသည်။ ရှက်ရွံ့အားနာသည်။',NULL)
,(11346,3,4,'မျက်နှာညှိုးနွမ်းသည်။ မျက်နှာမသာမယာဖြစ်သည်။',NULL)
,(11347,3,1,'လေမျက်နှာစာ။','“ရဴပ္တေၚ်ညးမပက်ဏာမုက်ကျာကီု ဒးချာဲဖဍာဲအာရ။” (ဇ—၅ဝ၆။အစွောံ။) = “လေတိုက်ရာမျက်နှာစာသို့ ပက်လိုက်သောဖွဲပြာကဲ့သို့ ဖရိုဖရဲကြဲလတ္တံ့။”')
,(11348,3,4,'မျက်နှာကြောတင်းသည်။ မျက်နှာမာသည်။',NULL)
,(11349,3,11,'(န) မြတ်စွာဘုရားမုက္ခပါဋ္ဌ်တော်။','“ကေုာံပိတကတ်ပိ မတိတ်နူမုက္ခပါတ်။” (သၠပတ်ဗုဒ္ဓဃောသာ) = “မြတ်စွာဘုရားမုက္ခပါဋ္ဌ်တော်လာ ပိဋကတ်သုံးပုံ။” || “တိတ်နူမုက္ခပါတ်၊ တွံကျာ်သံဗုဒ္ဓာ။” (လိက်ပဒုမ္မဝတဳ)')
,(11350,3,1,'မျက်နှာ။','‘တဳလမၞုံကုပိုန်ကျာ်တြဲ မၞုံမုက္ခဝါမတုပ်တဴညံၚ်ရဴဂိတုမပေၚ်။’ (ဇ—၁။ အစွောံ။) = ‘လပြည့်ဝန်းနှင့်တူသော မျက်နှာတော်ရှိသော ဘုန်းတော်ကြီးသောမြတ်စွာဘုရား။’ || လာၚ်မုက္ခဝါ = မျက်နှာသစ်သည်။')
,(11351,3,4,'မျက်နှာညှိုးသည်။ မျက်နှာမသာမယာဖြစ်သည်။','“ယွံရာဟုလ၊ မူဒှ်မုက်ချိုတ်ဒၟံၚ်ရော” သာရိပိုတ်သၟာန်။ (ဇ—၂၈၁။ အစွောံ။) = အရှင်သာရိပုတ္တရာမထေရ်သည် “ရာဟုလာ၊အဘယ်ကြောၚှ် မျက်နှာမသာလျက် ရပ်သနည်း” ဟုမေး၏။ (ညောင်ကန်)')
,(11352,3,4,'မျက်နှာညှိုးငယ်သည်။ မျက်နှာပျက်သည်။','“(ဂၞကျာ်) သီုမုက်မချိုတ်သရိုဟ်အာဂှ် ညာတ်တုဲ မူဂလိုၚ်အဲဍိုန်ဍူဂၞကျာ်ရော မရာတ်။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) =“အရှင်မင်းကြီး၊ မျက်နှာညှိုးငယ်သော မိဖုရားကိုမြင်၍ အကျွန်ုပ်သည် မိဖုရားကို များစွာသနားလိုက်ပါဘိ။”')
,(11353,3,4,'မျက်နှာလှသည်။ စိတ်ချမ်းသာ၍ မျက်နှာပြုံးရွှင်သည်။ ကြည်သာရွှင်ပျသည်။','“မိအဲဂွံညာတ်မုက်အဲတုဲ မုက်မိအဲဂေါဝ် ဟွံဒးဇွောဝ်ဍာ်ရမတ်—။” (ဇ—၃၉၈။ အစွောံ။) = “ငါ့မိခင်သည် ငါ့မျက်နှာကို မြင်ရသည်ရှိသော် ကြည်သာရွှင်ပျ မျက်နှာလှ၍ မျက်ရည်မကျရတော့ပြီ။” || “ဖေအ်ၜါဂှ် ညံၚ်ရဴညးမကျပးကသာပ်လ္ၚီကီု မုက်ဟွံဂေါဝ် ဂ္ဇအ်ဇောဝ်တဴရ။” (ဇ—၄ဝဝ။အစွောံ။) = “နှစ်ခုသောဖျံတို့သည် ကြွေအန်လောင်းကစားရာတွင် အသပြာတစ်ထောင်ရှုံးသောသူကဲ့သို့ မျက်နှာမကြည်မသာနှင့်ငေးမှိုင်လျက်ထိုင်၏။”')
,(11354,3,4,'မျက်နှာငယ်သည်။ သိမ်ငယ်သည်။',NULL)
,(11355,3,4,'မျက်နှာထူသည်။ မျက်နှာကြောတင်းသည်။',NULL)
,(11356,3,1,'မုခ်ဦး။','မုက်ထော်ဘာဂန္ဓကုဋဳ = ဂန္ဓကုဋဳကျောင်းမုခ်ဦး။ (ပါဠိ—ဂန္ဓကုဋိပ္ပမုခ)')
,(11357,3,12,'(န) မုဒရက်သီး။ စပျစ်သီး။','“ချေံသိန္ဓဴမသုန်ကၠံဂှ် ဍာ်သတ်မုက်ဒြာတ်မၞုံကုရှ်ဂှ် မၞးတံကဵုဍေံသုၚ်ညိ” သၟိၚ်ဂး။ (ဇ—၁၈၃။ အစွောံ။) = “ငါးရာကုန်သော သိန္ဓောမြင်းတို့အား အရသာရှိသော မုဒရက်အဖျော်ကို သင်တို့ပေးကုန်လော့” ဟုမင်းဆို၏။')
,(11358,3,1,'စစ်မျက်နှာ။ စစ်တိုက်ရာအရပ်။',NULL)
,(11359,3,1,'မျက်နှာထား။ မျက်စိမျက်နှာ။ မျက်နှာသွင်ပြင်။','“ဟိုတ်နူဒုဟ်ဍေံနွံတုဲ မုက်မတ်ဍေံလီုဒၟံၚ်ရ။” = “သူ့မှာအပြစ်ရှိသောကြောင့် သူမျက်စိမျက်နှာပျက်နေသည်။”')
,(11360,3,4,'မျက်နှာသွင်ပြင်ညှိုးငယ်သည်။',NULL)
,(11361,3,4,'မျက်နှာကြီးသည်။ ဂုဏ်အရှိန်အဝါကြီးသည်။',NULL)
,(11362,3,4,'မျက်နှာငယ်သည်။ ဂုဏ်အရှိန်အဝါနည်းသည်။',NULL)
,(11363,3,4,'မျက်နှာပွင့်လန်းသည်။',NULL)
,(11364,3,4,'မျက်နှာမသာမယာဖြစ်သည်။ မျက်နှာပျက်သည်။','“ယွံမၞးတံ၊ ဒေံဍေံမွဲဂှ် မၞးတံရံၚ်ရ။ ပ္ဍဲကောဍေံမချိုတ်အာဂှ်ကီုလေဝ် ဆဗၞတ်မုက္ခဝါဍေံမလီုအာညိညကီု ဟွံမွဲသွံ။” (ဇ—၃၁၇။ အစွောံ။) = “အချင်းတို့၊ ကြည့်ကြကုန်လော့။ အစ်ကိုသေလတ်သော် ဤသူအား မျက်နှာတွန့်ခြင်းမျှသည်လည်း မရှိ။”')
,(11365,3,1,'နန်း၊ အိမ်စသည်၏ အဦးအဝနေရာ။ ရင်ပြင်။','မုက်ရၚ်သၟိၚ် = မင်းရၚ်ပြၚ်။ || “ပတွဵုမဂွံပကၚ်ရၚ်ကၟိန်ဍုၚ်တုဲ ကဵုခၞံရုၚ်ဒါန်တရဴရ။ တရၚ်ပန်ဒိုဟ်ဍုၚ်ဂှ် ရုၚ်ဒါန်ပန်၊ ဒေါဝ်ဍုၚ်ရုၚ်ဒါန်မွဲ၊ ပ္ဍဲမုက်ရၚ်ဂှ် ရုၚ်ဒါန်မွဲ—။” (ဇ—၁၉၃။ အစွောံ။) = “မင်းပြုသည်ရှိသော် မြို့တံခါးလေးမျက်နှာတို့­၄င်း၊ မြို့လယ်­၄င်း နန်းဦးတံခါး­၄င်း ဤခြောက်ပါးကုန်သောအရပ်တို့­ အလှူတင်းကုပ်တို့ကို ဆောက်စေ၍—။” (ညောင်ကန်) || “(သၟတ်ဗြဴဂှ်) ဍေံယဵုသွံစဗဒဝ်တုဲ ဍေံကွာ်ကၠုၚ်ဆိုက်ညန်မုက်ရၚ်သၟိၚ်ဂှ်တုဲ—။” (ဇ—၃ဝ၆။ အစွောံ။) = “(ထိုသူငယ်မသည်) ဆီးသီးတောင်းကိုရွက်၍ — မင်းရင်ပြင်သို့သွား၏။” (ညောင်ကန်) || “မၞိဟ်ဂမၠိုၚ်ဒးဘဲကၞောဝ်တုဲ ကၠုၚ်ကောံပ္ဍဲမုက်ရၚ်သၟိၚ်ရ။” (ဇ—၅၂၆။ အစွောံ။) = “လူတို့သည် အငတ်ဘေးဆိုက်၍ မင်းရင်ပြင်­ စည်းဝေးကုန်၏။”')
,(11366,3,1,'(စာအုပ်ရှိ) စာမျက်နှာ။',NULL)
,(11367,3,4,'‘မုက်မတ်လီု’','‘မုက္ခဝါလီု’ နှင့်အတူတူ။ || “သၟိၚ်အဝိရာတပုရာံဟွံမိပ်စိုတ် မုက်လီုဒၟံၚ်။” (အာန်ဇုနာန်)')
,(11368,3,1,'အိမ်မျက်နှာစာ။',NULL)
,(11369,3,4,'မျက်နှာကြောတင်းသည်။ မျက်နှာပုပ်သည်။','“(ဗြဴမွဲ) ဂတိုပ်မတ်တီု၊ မုက်သ္ၚေက်ကီုရ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “မိန်းမတစ်ယောက်သည် မျက်ခွံထူ၍မျက်နှာကြောတင်း၏။” || “မၞိဟ်သ္ဒိုဟ်သ္ဒီု၊ ဟီုသၞောဝ်ဒှ်သၞ။ ဒးပ္တုဲဒါန်ဗိုန်၊ မုက်ဟေက်တိုန်ရ။” (သၠပတ်ပုံပမာ။ အစွောံ။)')
,(11370,3,4,'မျက်နှာသွင်ပြင်ညှိုးငယ်သည်။',NULL)
,(11371,3,1,'လဆန်းရက်။','ဂိတုဇှ်ေပိမံက် = နယုန်လဆန်းသုံးရက်။')
,(11371,3,4,'ပေါ်သည်။','“စက်ဂိတုမံက်တိတ်ကၠုၚ်နူဂၠံမတ်ဗြဲရ။” = “လဝန်းသည် မိုးသားတိမ်လိပ်ကြားမှ ပေါ်ထွက်လာသည်။”')
,(11372,3,4,'ပေါ်လွင်သည်။ ထင်ရှားသည်။','“ဒုဟ်ဍေံနွံဂှ် မံက်ဂတဝ်ပြာကတ်တဴရ။” =“သူ့မှာအပြစ်ရှိကြောင်း ပေါ်လွင်ထင်ရှားပါသည်။”')
,(11373,3,1,'စိုင်။ (ပါဠိ—ရောဟိတမိဂ)','‘ဒြာဲမၚ်’ လည်းရှု။')
,(11373,3,4,'စောင့်သည်။','“ဗှ်ေကၠုၚ်မ္ဂး အဲမၚ်ဒၟံၚ်ပ္ဍဲသ္ၚိရောၚ်။” = “နင်လာလျှင် အိမ်မှာငါစောင့်နေမည်။”')
,(11374,3,4,'ကင်းစောင့်သည်။',NULL)
,(11375,3,1,'ရှားစောင်းပင်။ (စောင်းကြမ်းပင်)',NULL)
,(11376,3,10,'(န) မင်္ဂလာ။','“ကိစ္စမွဲမွဲ မၚ်္ဂလကီု အမၚ်္ဂလကီု။” (ဇ—၂၂၁။ အစွောံ။) = “မင်္ဂလာသော်၄င်း အမင်္ဂလာသော်၄င်း တစ်စုံတစ်ခုသောကိစ္စသည်—။”')
,(11377,3,1,'မင်းဂွတ်သီး။','“ဒူရေန်မၚ်ဂုတ်၊ သတ်မံၚ်ဟွံခြာ။” (လိက်ကကၠာ်။ ကောန်ဍး။) =“ဒူးရင်းမင်းဂွတ်တို့သည် မခြားမလပ်သီးနေကုန်၏။”')
,(11378,3,1,'ရှဉ့်နက်ကြီးတစ်မျိုး။','“ပြိပ်၊ ယန်၊ လစေၚ်၊ မၚ်ဂဝ်၊ ကၞုဲ၊ ဂၚ်၊ လၚ်ဟေ။” (သၠပတ်စန္ဒဝတဳ) || “မၚ်ဂဝ်ပြိပ်ယန်၊ ဝုတ်အဵုကောန်သၞ။” (လိက်ဝိဓူရ)')
,(11379,3,1,'မိုးမခပၚ်။','‘မာဲဂြာဲ’ ရှု။')
,(11380,3,1,'မန်ကျည်းသီး။',NULL)
,(11381,3,4,'စောင့်မျှော်သည်။',NULL)
,(11382,3,16,'(တူတူပုန်းတမ်း စသည်ကစားရာတွင်) စောင့်ရသောအလှည့်ကျသည်။—သူ။','“ဝေၚ်ဒဴအောပ်အဴ၊ နာဲတအ်ဒဴအဲ။ အဲဟွံရံၚ်သၟတ်၊ ဒဝ်မတ်ကဵုတဲ။ ဒၞာဲဝွံသွိၚ်၊ သၟဝ်သမၞိၚ်ဇြဲ။ မၚ် ဆိၚ်ရၝဲ၊ ဒဝ်မတ်တဲၜါ။ ညးဂမၠိုၚ်ရော၊ ဒြေပ်အောပ်ဟောဒြာ။ — တုဲရဟီုသ္ကဲ၊ ကော်ဂးမွဲဝါ။ ညးမၚ်ဆိၚ်ဟေၚ်၊ တိတ်ဗက်သေၚ်ဟာ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “တူတူပုန်းတမ်းကစားကြမည်၊သင်တို့ငါ့ကို ရှောင်ပုန်းကြကုန်လော့၊ ငါမကြည့်ဘဲ ငါ့မျက်စိကို လက်ဖြင့်ပိတ်ထားပါမည်။ ဤညောင်ပင်ရိပ်အောက်မှာ ငါစောင့်ပါမည်။ လူအများသည် သောသောညံအောင် ပြေးပုန်းကြကုန်၏။ ပုန်းပြီးပြီဟု တစ်ကြိမ်ဆိုသောအခါ စောင့်ရသောအလှည့်ကျသူက ထွက်၍လိုက်ရှာရ၏။”')
,(11383,3,1,'စနည်း။ တဘောင်။ ကြိုတၚ်ဟောနိမိတ်စကား။','“သဘဴသၟိၚ် — နူၜါယာံမစိုပ်ပိယာံဂှ် အဂီုမၚ်ဇေန်မၚ်လာဲ ဂပ်ဂဝ်ပၚ်မှိၚ်ရ။” (ဓမ္မသာတ်။ MDT VII) = “မင်းတို့မည်သည် ဒုတိယယံမှ တတိယယံရောက်သည်အထိ ရိုးရာပုံပြင်၊ တဘောင်နိမိတ်စကားနှင့် သမိုင်းစာတို့ကိုနာကြားသင့်၏။” || “သုတ်ဇေန်ဇာတ်ဇေန်၊ မၚ်ဇေန်မူလ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။)')
,(11384,3,1,'အပြစ်။ စွဲချက်။ (?)','‘စုတ်မၚ်ဇေဝ်’ (ကြိ) တွင်ရှု။')
,(11385,3,1,'လုလင်။ ပျိုရွယ်သောယောကျာ်း။','‘မာၚ်ဗၠာဲ’ ဟုလည်းတွေ့ရသည်။')
,(11386,3,4,'၁။ စောင့်ရှောက်သည်။','“ယွံကောန်တၠ၊ ခၟာဲပိုဲကီု ကောန်ပိုဲသၟတ်ကီု တၠအဲမၚ်မွဲညိအဴ”ဂစေံဂမၠိုၚ်ဂးကဵုခ္ဍာ်။ (ဇ—၃၈၄။ အစွောံ။) = “အရှင်ကျီး၊ သင်သည် ငါတို့၏ဥတို့ကို၄င်း သားငယ်တို့ကို၄င်း စောင့်ရှောက်ပါလော့” ဟုငှက်များဆို၏။')
,(11386,3,4,'၂။ စောင့်စည်းသည်။ စောင့်ထိန်းသည်။','“သၟိၚ်ဂှ် မၚ်မွဲဓဝ်သၟိၚ်စှ်ပြကာ—။” (ဇ—၄၂၄။ အစွောံ။) = “ထိုမင်းသည် မင်းကျင့်တရားဆယ်ပါးကို စောင့်စည်း၏။” || မၚ်မွဲသဳလ = သီလစောင့်စည်းသည်။')
,(11387,3,1,'ဆေးမၚ်ထိုးခြင်း။',NULL)
,(11388,3,1,'တာ။ (၇) တောင်အတိုင်းအတာ။','“ၜါစှ်ောမၚ်လံၚ် ဒှ်မွဲဥသဘရ။” = “တာနှစ်ဆယ်သည် တစ်ဥသဘနှင့်ညီသည်။” || “က္ၜၚ်ဂှ်တုန် ဗွဲဇလိၚ်ဍေံ ဒစာံဇရိုက်ဥဿဘနာၚ်၊ ဗွဲလမၞၚ်ဍေံ ပန်ဇရိုက်ဥဿဘနာၚ်၊ လမျိုဟ်က္ၜၚ်ဂှ် ၜါစှ်ောမၚ်လံၚ်—။” (ဇ—၄၄၂။ အစွောံ။) =“ထိုလှေသည် အလျားဖြင့် ရှစ်ဥသဘရှိ၏။ အနံအားဖြင့် လေးဥသဘရှိ၏။ အစောက်အားဖြင့်တာနှစ်ဆယ်ရှိ၏။” (ညောင်ကန်) || “(၇) ဟတ် ဒှ်မွဲမၚ်လံ။” (သၠပတ်နိယမ (၅) နဲ (၁၅)')
,(11389,3,1,'သမိုင်းစာ။ (?)','“သဘဴသၟိၚ် — နူၜါယာံမစိုပ်ပိယာံဂှ် အဂီုမၚ်ဇေန်မၚ်လာဲ ဂပ်ဂဝ်ပၚ်မှိၚ်ရ။” (ဓမ္မသာတ်။ MDT VII) = “မင်းတို့မည်သည် ဒုတိယယံမှ တတိယယံရောက်သည်အထိ ရိုးရာပုံပြင်၊ တဘောင်နိမိတ်စကားနှင့် သမိုင်းစာတို့ကို နာကြားသင့်၏။”')
,(11390,3,1,'လုလင်ငယ်မ။ (ပါဠိ—မာဏဝဳ)',NULL)
,(11391,3,4,'သီလစောင့်သည်။ ဥပုသ်စောင့်သည်။','“ဍေံတံလေဝ် ဟွံဂွံမၚ်သဳဟေၚ်။” (ဇ—၃၅၆။အစွောံ။) = “သူတို့လည်း သီလကိုမစောင့်ကြကုန်။”')
,(11392,3,1,'ထိုးကွင်းမင်ကြောင်။ မင်သေ့။','ထ္ပက်မၚ်သေအ် = ထိုးကွင်းမင်ကြောင်ထိုးသည်။')
,(11393,3,1,'လုလင်။','“အခြၚ်မဒှ်ဨကရာတ် မာၚ်ဗၠာဲဂှ်ဟွံတီ။” (သၠပတ်ဒ္ၚောဝ်သၜေံါ) = “ဘုရင်ဖြစ်ကြောင်း လုလင်မသိ။”')
,(11393,3,1,'လုလင်။','‘မၚ်ဗၠာဲ’ နှင့်အတူတူ။')
,(11394,3,4,'ကြားသည်။','မိၚ်ရမ်သာၚ် = အသံကြားသည်။')
,(11395,3,1,'မှိန်း။',NULL)
,(11396,3,16,'(န) အမိန့်တော်။ (?)','“ဖျဴရာဇာသာန်၊ ထာန်နာဲနန်ထဝ်။ ပြုပြေၚ်တုဲသွံ၊ဂွံလိက်မိၚ်ဒဝ်။” (လိက်ပဒုမဝတဳ) = “မင်းစာချွန်တော်ကို ရွှေနန်းရှင်ရှိရာအရပ်သို့ ယူဆောင်ပြန်၍ စီမံပြီးစီးလတ်သော် အမိန့်တော်စာကို ရရှိ၏။” || “ဂွံမိၚ်အိုတ်သ္အး၊ လိက်တၞးထဝ်။ အသံသၟိၚ်မ္ဂး၊ တရးမိၚ်ဒဝ်။” (လိက်ပဒုမဝတဳ)')
,(11397,3,1,'မှိန်းလက်နက်။','“ယွံမၞးတံ၊ နဗၞုဟ်မိၚ်ဒၠုၚ်ဂှ် ထပက်ကျာံတုဲ မၞးတံရပ်ကျာံညိ” သၟိၚ်ဂး။ (ဇ—၂၃၃။ အစွောံ။) || “ဟာဲကျာံ — နမိၚ်ဒၠုၚ်ဂှ် အဲထပက်ကလှၚ်ကၠေံဗှ်ေတုဲရ။” (ဇ—၂၃၃။ အစွောံ။) || (မှတ်ချက်။ မြန်မာညောင်ကန်မူ­ ‘အရွက်မရှိသောမြှား’ ဟုဆိုသည်။) || “ကောန်ညးကအ်မှုက်မွဲ — ဍေံရပ်လဝ်မိန်ဓလုၚ် ဍေံတ္ၚီုဒးဂါပ်ပါၚ်စိၚ်တရာဗညာ။” (အကြီုရာဇာဓိရာဇ်) = “ကော့မှုတ်ရွာသားသည် တရဖျား (ဆင်) ၏ ဆင်စွယ်ဖုံးနှင့် နှုတ်ခမ်းဝအကြားကိုမှိန်းဖြင့်ထိုးလိုက်၏။” (ရာဇာဓိရာဇ်အရေးတော်ပုံကျမ်း။ နိုင်ပန်းလှ။)')
,(11398,3,4,'သတင်းကြားသည်။',NULL)
,(11399,3,4,'နှုတ်ထွက်စကားကိုကြားသည်။ ပြောစကားကိုကြားသည်။','“ပူဂဵုသတြုဂှ် မိၚ်ပါၚ်ဍေံတုဲ ဟွံဂွံသ္ဍိုက်မၠိုက် ဟွံဂွံအိုဟ်တၟိုဟ်စိုတ်ရ။” = “ရန်သူဖြစ်သောသူ၏ စကားကိုကြား၍ မနှစ်သက် ဝမ်းမမြောက်။”')
,(11400,3,4,'ပေးပို့လာသောစာထဲမှ ပြောဆိုသောအကြောင်းအချက်ကို ကြားသိသည်။',NULL)
,(11401,3,1,'ဘုရင်၊ မိဖုရားတို့၏ ရံရွေတော်။ မောင်းမ။ နန်းတွင်းသူ။','ကမၠောန်မောင်မ = ဘုရင်၏မောင်းမမိဿံများ။ နန်းတွင်းသူများ။ || “မံၚ်မ၊ မှံၚ်မှ” ဟူ၍လည်းရေးသည်။ (မြန်မာဝေါဟာရ ‘မောင်းမ’ သည် မွန်ဝေါဟာရ ‘မောင်မ’ မှ ဆင်းသက်လာသည်။) || ‘ဗြဴမှောင်မှစှ်တြဴလ္ၚီ။’ (ဇ—၄ဝ၆။ အစွောံ။) = ‘တစ်သောင်းခြောက်ထောင်သောမင်းမောင်းမ။’ || “ဒဒှ်ဂှ် ကမၠောန်မှောင်မှတံတီအာတုဲ ဂၞကျာ်ပြာပ်အာပ္တီသၟိၚ်ရ။” (ဇ—၃၉၁။ အစွောံ) = “ထိုအကြောင်းကို မင်း၏ကိုယ်လုပ်မောင်းမများ သိရှိသွားကြပြီး မိဖုရားသည် မင်းထံသွားရောက်အသိပေး၏။” || “ဒးကာလတိပိုန်အနန် စဴတွံဓဝ်ကဵုမောင်မတံဂှ်တုဲ—။” (ဇ—၁၅၇။ အစွောံ။) = “အရှင်အာနန္ဒာသည် မင်းမောင်းမတို့ကို သွားရောက်၍တရားဟော၏။”')
,(11402,3,1,'၁။ အသံမြည်သည့်မောင်း။','ၜုၚ်မံၚ်၊ တက်မံၚ် = မောင်းတီးသည်။ || “သီုဗရုတွိၚ်တွိုက်ဖံ၊ မံၚ်၊ ဂပဵု၊ ခရာ၊ ထ္ဍေဝ်၊ ဆာၚ်။” (ပြကိုဟ်နဝဗျတ္တိ) = “စည်၊ မောင်း၊ တံပိုး၊ ခရာ၊စည်း၊ လၚ်ကွင်းတို့၏တီးခတ်သံများဖြင့်။”')
,(11402,3,1,'၂။ ထောင်းသည့်မောင်း။ မောင်းဆုံ။','မံၚ်ချာန် =ရက်ကန်းနှတ်ခုံ။')
,(11402,3,4,'နေသည်။ နေထိုင်သည်။','“အဲမံၚ်ပ္ဍဲကွာန်လၟိုၚ်ရ။” = “လမိုင်းရွာတွင် ကျွန်တော်နေထိုင်သည်။”')
,(11402,3,9,'ဆက်လက်ဖြစ်နေကြောင်းကို ပြသောစကားလုံး။','တိက်မံၚ် = အိပ်နေသည်။ || အာမံၚ် = သွားနေသည်။ || ‘ဒၟံၚ်’ နှင့်အတူတူ။')
,(11403,3,4,'နေမထိထိုၚ်မထိဖြစ်သည်။ နေမထိထိုၚ်မသာဖြစ်သည်။',NULL)
,(11404,3,4,'ကျန်းမာသည်။ ကျန်းမာရေးကောင်းသည်။','“အပါနော်ဂှ် မံၚ်ထတ်ဒၟံၚ်ရဟာ။” =“မင်းတို့အဘိုး ကျန်းကျန်းမာမာ ရှိပါသလား။” || ‘မံၚ်မိပ်’ လည်းရှု။')
,(11405,3,1,'ရေတၚ်မောင်းတက်။ ယန္တရား။','‘ယန်ပကဲ’ နှင့်အတူတူ။')
,(11406,3,4,'ကျောင်းနေသည်။','“နူကဵုမံၚ်ဘာ၊ အစာဗတောန်၊ ပဥ္စသဳလာ။” (လိက်ဂစေံဍာ်မိတ်) = “ကျောင်းနေသည်မှစ၍ ငါးပါးသီလကို ဆရာသင်ကြားပေး၏။”')
,(11407,3,1,'မောင်းမ။ မင်းမောင်းမ။','“(ကြုက်လၟဆက်ကွာဲဂှ်) သၟိၚ်ကဵုအမာတ်သီုမံၚ်မဂၞကျာ်တံမစရ။” (ဇ—၄ဝ၇။ အစွောံ။) = “မုဆိုးဆက်သသောသရက်သီးကို မင်းသည် အမတ်များနှင့်မောင်းမမိဖုရားတို့ကို စားစေ၏။” || ‘မောင်မ’/‘မှောင်မှ’ နှင့်အတူတူ။')
,(11408,3,4,'ကျန်းမာသည်။ နေကောင်းသည်။','“အပါနော်ပိုဲ မံၚ်မိပ်ဒၟံၚ်ရ။” = “ငါတို့အဘိုးနေကောင်းပါသည်။” || “ဂၞကျာ်မံၚ်ဟွံမိပ်။” (ဇ—၄၇၂။ အစွောံ။) = “မိဖုရားမကျန်းမာ။”')
,(11409,3,10,'(န) အသား။','ကဖျုန်မံၚ်သံၚ် = အသားငါး။ || “ပ္ဍဲသြၚ်ဂၚ်ဂှ် မပ္တံကဖျုန်မံၚ်သံၚ် အဲစညိ” ခ္ဍာ်ဂှ်ချပ်။ (ဇ—၄၃၄။ အစွောံ။) = “ဂၚ်္ဂါကမ်းနား­ အသားငါးအစရှိသည်တို့ကိုစားအံ့” ဟုကျီးသည်ကြံ၏။')
,(11410,3,1,'တိရစ္ဆာန်တို့ခိုအောင်းရာနေရာ။ သားရဲတွင်း။',NULL)
,(11410,3,4,'လဲပြိုသည်။','“လ္ပာ်က္ဍုတ်ကွဳဂှ်ပ္ဍိုက်လဝ်လယိုင်ဂၠိုၚ်တုဲ ကွဳဂှ်မိုၚ်အာရ။” = “လှည်း၏နောက်ပိုင်းတွင် တင်ထားသောအလေးချိန်များလွန်းသောကြောင့် လှည်းသည်ထောၚ်တက်၍ ပြိုလဲသွားသည်။”')
,(11411,3,10,'(န) သေခြင်း။','ဘဲမစ္စု = သေဘေး။')
,(11412,3,10,'(န) ဝန်တိုစိတ်။ မစ္ဆရိယ။',NULL)
,(11413,3,10,'(န) ဝန်တိုခြင်း။ တွန့်တိုခြင်း။ စေးနှဲခြင်း။ မစ္ဆေရတရား။','“သေဋ္ဌဳဂှ် ဂၠိုၚ်ကဵုမစ္ဆေရလောန်၊ ဟွံကဵုဒါန်မွဲလှ်ေရ။” = “ထိုသူဋ္ဌေးသည် အလွန်စေးနှဲ၏၊ တစ်ခါမျှအလှူမပေးစဖူး။” || “ပူဂဵုသပ္ပရိုဟ် မလေပ်စၞေဟ်ကဵုပၞာန်မစ္ဆေရတုဲ မလေပ်ပ္တုဲဒါန်တံဂှ် မအာစိုပ်သွဝ်စၟတ်—။” (ဇ—၄၅ဝ။ အစွောံ။) = “ဝန်တိုခြင်းမစ္ဆေရတရားနှင့်စစ်ထိုး၍ အလှူဒါနပြုတတ်သော သူတော်ကောင်းတို့သည် စင်စစ်နတ်ပြည်သို့ လားရောက်၏။”')
,(11414,3,10,'(န) အလယ်အလတ်။ မဇ္ဈိမ။',NULL)
,(11415,3,11,'(န) (၁ဝ) ဝါမှ ဝါ (၂ဝ) အတွင်း ဖြစ်သောထေရ်။ မဇ္ဈိမထေရ်။',NULL)
,(11416,3,10,'(န) မဇ္ဈိမဒေသ။ အလယ်ပိုင်းဒေသ။',NULL)
,(11417,3,10,'(န) မဇ္ဇျိမပဋိပဒါ။ အလယ်အလတ်ကျင့်စဉ်။ (တင်းလွန်းခြင်း လျော့လွန်းခြင်းတည်းဟူသော အစွန်းနှစ်ဖက်သို့မရောက်စေသော အလယ်အလတ်လမ်းစဉ်။)',NULL)
,(11418,3,11,'(န) သန်းခေါင်ယံ။ မဇ္ဇျိမယံ (= ပယာံသ္ဂာတ္ၚဲ)','“(ခမဳဂှ်) လဆောဝ်ပ္ဍဲမဇ္ဇျိမယာံဂှ်လေဝ် ကော်ပၚုဟ်ညးကီု။” (ဇ—၁၁၉။ အစွောံ။) = “ထိုရဟန်းသည် ရံခါသန်းခေါင်ယံ­လည်း သူတစ်ပါးတို့ကို ခေါ်နှိုး၏။” || “ပ္ဍဲပထမပယာံကီု ပ္ဍဲမဇ္ဇျိမပယာံကီု ပ္ဍဲပစ္ဆိမပယာံကီု။” (ဇ—၃၃ဝ။ အစွောံ။) = “ညဉ့်ဦးယံ­၄င်း သန်းခေါင်းယံ­၄င်း မိုးသောက်ယံ­၄င်း။”')
,(11419,3,11,'လူလတ်ပိုင်းအရွယ်။ မဇ္ဈိမအရွယ်။ အသက် (၃ဝ) မှ (၆ဝ) အထိအရွယ်။ (မှတ်ချက်။ လူ့သက်တမ်း (၉ဝ) ဖြင့် တွက်ထားသည်။ လူ့အရွယ်အပိုင်းအခြားကို သုံးပိုင်းအညီမျှပိုင်းခြားသည်။)', '“ပ္ဍဲပဋ္ဌမအဝဲကီု ပ္ဍဲမဇ္ဇျိမအဝဲကီု ပ္ဍဲကၞောတ်အဝဲကီု အဲမဒးချိုတ်ရမ္ဂးဂှ် အဲဟွံတီအဲစၟတ်ဟွံဒး။” (ဇ—၁၆၇။ အစွောံ) = “ပထမအရွယ်­၄င်း မဇ္ဈိမအရွယ်­၄င်း ပစ္ဆိမအရွယ်­၄င်း သေလတ္တံ့သောကာလကို ငါမသိ၊ ငါ့အားမထၚ်။” || “ပ္ဍဲမဒှ်ပထမအဝဲကီု ပ္ဍဲမဒှ်မဇ္ဇျိမအဝဲကီုပ္ဍဲမဒှ်ပစ္ဆိမအဝဲကီု သတ္တံမဒးပြာပ်အာကဵုဂစိုတ်ကီု။” (ဇ—၃၂၈။ အစွောံ။) = “ပထမအရွယ်­၄င်းမဇ္ဈိမအရွယ်­၄င်း ပစ္ဆိမအရွယ်­၄င်း သတ္တဝါတို့သည် သေကြရကုန်၏။” || ‘ပထမအဝဲ’၊ ‘ပစ္ဆိမအဝဲ/ကၞောတ်အဝဲ’ တို့လည်းရှု။')
,(11420,3,11,'(န) အလယ်အလတ်။',NULL)
,(11420,3,11,'(နဝိ) အလယ်အလတ်ဖြစ်သော။','“ဆုတၞုၚ်ဂှ် ဟွံဇၞော်လောန် ဟွံဍောတ်လောန် ဗၞတ်တၟာဍေံမဇ္ဇျီုရ။” = “ထိုသစ်ချောင်းသည် မကြီးလွန်း မငယ်လွန်း အရွယ်အစားအလယ်အလတ်ဖြစ်သည်။” || “ကွတ်မ္ဂးဂှ် မယုတ်မပြဲမဒှ်မဇ္ဇျီု ဇၟာပ်ကွတ်အိုတ်သီု ဒဒှ်မၞုံကဵုဖဵုဂှ် ဂပ်ဂဝ်သတီရ။” (ဇ—၃၇၃။ အစွောံ။) = “အတတ်မည်သည် အယုတ်အမြတ်အလတ် အတတ်တိုင်းသည် အကျိုးရှိသည်ဟူ၍ မှတ်သားအပ်၏။” || “သၟတ်တြုံဂှ် ဟွံသၠုၚ်လောန် ဟွံသဝ်လောန် မၞုံသလုၚ်ဒတဴမဇ္ဇျီုရ။” = “ထိုသူငယ်သည် မမြင့်လွန်း မနိမ့်လွန်း အရပ်အမောင်း အလယ်အလတ်ဖြစ်သည်။” || “ယြဴပူဂဵုမွဲဂှ် မဂွံဒ္ဂေတ်ဓဝ်သဳလမ္ဂး သဳလဗွဲမယုတ်ဂှ်ဂွံဒှ်သၟိၚ်ရ။ သဳလဒေါဝ်မဇျီုဂှ် ဂွံဒှ်ဒေဝတဴသွဝ်ရ။ သဳလပြဲလောန်ဂှ် ဂွံစိုပ်ဍုၚ်နိဗ္ဗာန်ရ။” (ဇ—၄၂၄။အစွောံ။) = “သဳလတရားကိုကျင့်သော အကြင်ပုဂ္ဂိုလ်သည် ယုတ်သောသီလဖြင့် မင်းအဖြစ်ကိုရ၏။ အလယ်အလတ်ဖြစ်သောသဳလဖြင့် နတ်ပြည်သို့ရောက်ရ၏။ အလွန်မြတ်သောသီလဖြင့်နိဗ္ဗာန်သို့ရောက်ရ၏။” || “ကမၠောန်သၟတ်တံဂှ် ဟွံဂွံကောန်တုဲ သၟိၚ်ဗလးဏာ ကမၠောန်မဇျီုတံဂှ်ပၠန်ရ။ ကမၠောန်မဇျီုတံဂှ် ဟွံဂွံကောန်တုဲ သၟိၚ်ဗလးပတိတ် ကမၠောန်ဇၞော်တံဂှ်ရ။” (ဇ—၅၃၁။အစွောံ။) = “မောင်းမငယ်တို့သည် သားမရသည်ရှိသော် မင်းသည် အလတ်ဖြစ်ကုန်သောမောင်းမတို့ကို လွှတ်ပြန်၏။ အလတ်ဖြစ်ကုန်သောမောင်းမတို့သည် သားမရသည်ရှိသော် အကြီးဖြစ်ကုန်သောမောင်းမတို့ကို လွှတ်ပြန်၏။” || “ယြဴပူဂဵုလ္ၚဵု မကဵုဒါန်မသၟဟ်ကဵုဇကု မစဟာပ်ဂ္ညိဂ္ညာတ်ဂှ် မကဵုဒါန်သီုစိုတ်မသ္ဇုၚ်ဂှ် ဒါန်ဂှ် ပ္ဍဲဂကူမဇျီု ပိုန်ဟာန်မဇျီု မက္တဵုဒှ်ဂကူပူဂဵုဂှ်ရ။” (ပြကိုဟ်နဝဗျတ္တိ) = “အချို့ကုန်သောသူတို့သည် မိမိစားသောက်ဆင်ယင်သည်နှင့်တူမျှစွာ စိတ်စၚ်ကြည်စွာပေးလှူသဖြင့် ထိုအလှူသည် အလယ်အလတ်အမျိုး­၄င်း အလယ်အလတ်စည်းစိမ်­၄င်းဖြစ်ပေါ်စေ၏။”')
,(11421,3,16,'(န) လျစ်လျူရှုခြင်း။','သ္ပမဇ္ဇျဟ် = လျစ်လျူရှုသည်။ ဥပေက္ခာပြုသည်။ || “ကောန်ဒွအ်ဒဒိုက်မ္ဂး မိမတအ်သ္ပမဇ္ဇျဟ် ဟွံသၟဟ်ရထရ။” = “သားသမီးဒုက္ခတွေ့လျှင်မိဘများဥပေက္ခာမပြုနိုင်ပါ။” || “ရေၚ်ကာန်ဖဲသၟတ်၊ ကြဴပမတ်ၛဟ်။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “ပေါင်းဖက်၍ဝပြီးနောက် ဥပေက္ခာပြု၏။”')
,(11421,3,16,'(ကြိ) ၁။ လျစ်လျူရှုသည်။ ဥပေက္ခာပြုသည်။','“ပ္ဍဲလိုက်ဝွံ ညးသ္ဍိုက်ဇကုကီု ညးက္ဍုဟ်ဇကုကီု ညးမဇ္ဇျဟ်ကဵုဇကုကီု နွံတဴအိုတ်ရ။”= “လောက­ မိမိကိုချစ်ခင်သူများ၊ မိမိကိုမုန်းသူများ၊ မိမိကိုမမုန်းမချစ် လျစ်လျူရှုသူများ ရှိကုန်၏။” || “သဘဴခမဳမ္ဂးဂှ် — ညးမဇ္ဇျဟ်ကဵုဇကုကီု ညးသောဗၞုဟ်ကဵုဇကုကီု ဂပ်ဂဝ်ဗယာပ်ဏာမေတ္တာစိုတ်ရ။” (ဇ—၁၆၉။ အစွောံ။) = “ရဟန်းတို့မည်သည် မိမိကိုလျစ်လျူရှုသောသူအား၄င်း မိမိအကျိုးကို လိုလားသူအား၄င်း မေတ္တာစိတ်ဖြင့် နှံ့စေအပ်၏။” || “မူဟိုတ်တၠဂုန်အာကဵုပိုန်ပ္ဍဲသ္ၚိသၟိၚ်တုဲ ပမဇ္ဇျဟ်ဒၟံၚ်ကဵုပွမုတ်တံဂှ်ရော။” (ဇ—၅၂၈။ အစွောံ။) = “အရှင်ဘုရားသည် အဘယ်ကြောင့် မင်းအိမ်­ဆွမ်းဘုဉ်း၍ မှားယွင်းသောအမှုတို့ကို လျစ်လျူရှုတော်မူဘိသနည်း။” || “ပ္ဍဲမဒးစသိုၚ်ဒဒိုက်တသိုက် မမဇ္ဇျဟ်တဴဂှ် ဒှ်ဥပေက္ခာပါရမဳရ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) =“ဆင်းရဲခြင်းချမ်းသာခြင်း ခံစားရသောအခါ ဥပေက္ခာပြုလျစ်လျူရှုခြင်းသည် ဥပေက္ခာပါရမီဖြစ်၏။”')
,(11421,3,16,'(ကြိ) ၂။ ပျောက်ပြယ်သည်။ ပျက်ပြယ်သည်။','“ကိစ္စမွဲမပ္တုဲဂှ် တ္ၚဲဝွံအဲဟွံပ္တုဲဏီရ။ ယးဂတအဲပ္တုဲရ — ကလဳတေံအဲပ္တုဲရဂးတုဲ ပွမပၠဳပၠအ်တဴဂှ် ကုသဵုစိုတ်ဂှ် မဇ္ဇျဟ်အာရ၊ ကုသဵုဂှ်ဍိုန်အာရ။” (ဇ—၅ဝ၉။ အစွောံ။) = “ယနေ့ပြုအပ်သောအမှုကို နက်ဖြန်မှငါပြုအံ့ သန်ဘက်ခါမှပြုအံ့ဟု အချိန်ရွှေ့ဆိုင်းခြင်းကြောင့် ကောင်းသောကုသိုလ်စိတ်သည် ပျောက်ပြယ်သွားလိမ့်မည်။ အားပျော့သွားလိမ့်မည်။” || “တၠသ္ၚိသ္ဍိုက်အဲဂှ် ဟွံဂွံရာန်သကိုတ်ပျဲပျာံအဲမွဲလှ်ေ၊ သ္ဍိုက်စိုတ် (ပ္ဍဲ) အဲ ဟွံဂွံမဇ္ဇျဟ်အာစၟတ်။” (ဇ—၅၁၃။ အစွောံ။) = “ငါ၏ချစ်လင်သည် ငါ့ကိုမနှိပ်စက်မညှဉ်းဆဲစဖူး၊ ငါ့အပေါ်ထားရှိသော အချစ်မေတ္တာလည်း စင်စစ်မပျက်ပြယ်စဖူး။”')
,(11422,3,1,'၁။ မျက်စိ။','မတ်သ္ပါ = မျက်စိမှုန်သည်။')
,(11422,3,1,'၂။ ကျောက်မျက်ရတနာ။','မတ်ဗိုတ်= စိန်ကျောက်။ || မတ်မြ = မြကျောက်။')
,(11423,3,9,'ဆေးဖော်စပ်ရာတွင် ပါဝၚ်သောအမည်။ အမျိုးအစား။','ဂဥုဲထပှ်မတ် = ခုနစ်ပါးဆေး။ || ‘ဂဥုဲမသုန်မတ် မတွံဂးကၠေၚ်သွဟ်၊ ကၠေၚ်တၟိ၊ ကၠေၚ်လ္ၚဴ၊ ဍာ်သာဲ၊ တၚ်လာဲ။’ (ဇ—၄ဝ၆။အစွောံ။) = ‘ထောပတ်၊ ဆီဦး၊ နှမ်းဆီ၊ ပျားရည်၊ တၚ်လဲဟူသော ငါးပါးစပ်ဆေး။’ || ‘ကၞာၚ်ဆုဒစာံမတ်။’ (သၠပတ်ဒ္ၚောဝ်သၜောံ) = ‘ရှစ်မျိုးသောသစ်ကိုင်း။’ || ‘သစ္ဆုၜါမတ်။’ (လောကသိဒ္ဓိ။ အစွောံ။) = ‘သစ်သီးနှစ်မျိုး။’')
,(11424,3,1,'ဖဝါး­ဖြစ်တတ်သော တံသင်းကဲ့သို့သောအနာ။ (ပါဠိ—ပါဒခဳလာဗာဓ) (တံသင်း =ငြောင့် = ကၞက်)','“ပါဒခဳလာဝါအာဗာဓော။ ၚ်ယဲဖျုန်မလတ်တိတ်ပ္ဍဲဇိုၚ် ရဴကၞက်ကီု။ (မတ်ကပ္ဍဲဇိုၚ်စိဂး။)” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) || “ယဲမတ်ကခုတ်၊ ညံၚ်ရဴသ္ကုတ်အာ။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။)')
,(11425,3,4,'မျက်စိကြောင်သည်။','“ဒကုဲဒၟံၚ်ဖိုဟ် မတ်ကၚ်အာတုဲ တိက်ဟွံလှိၚ်ရ။” = “အိပ်ငိုက်နေလျက်နှင့် မျက်စိကြောင်သွားသဖြင့် အိပ်မပျော်ပါ။”')
,(11426,3,4,'မျက်စိတိမ်စွဲသည်။',NULL)
,(11427,3,4,'ငိုက်မျဉ်းသည်။ အိပ်ချင်၍ မျက်စိမဖွင့်နိုင်ဖြစ်သည်။','“ဟိုတ်မစဂၠိုၚ် ဇကုသ္ဇိုၚ်မတ်ကြုပ်က္ဍိုပ်ဘိုၚ်အာ—။” (ဇ—၂၅၅။ အစွောံ။) = “စားများသဖြင့် ကိုယ်လေးလံ၍ ငိုက်မျဉ်း၍ ခေါင်းမူးဝေ၏။”')
,(11428,3,4,'မျက်စိကန်းသည်။',NULL)
,(11429,3,4,'မျက်စိကြောင်သည်။','“သုၚ်ဒးလဝ်ဍာ်လက်ဖက်တုဲ မတ်ဂၚ်အာ တိက်ဟွံလှိၚ်ရ။”= “လက်ဖက်ရည်သောက်ထားသဖြင့် မျက်စိကြောင်၍ အိပ်မပျော်တော့ပါ။”')
,(11430,3,4,'၁။ မူးဝေ၍ မျက်စိလည်သည်။','“(သေဋ္ဌဳတြုံဂှ်) ဒးတ္ၚဲကတဴ ပုၚ်လေဝ်ဟၟဲပ္ဍဲဂၞဴမတ်ဂေတ်တုဲ ‘တိန်’ လောတ်စှ်ေလ္ၚာဒၟံၚ်—။” (ဇ—၃၄ဝ။ အစွောံ။) = “သူဋ္ဌေးကြီးသည် နေအပူဒဏ်ထိ၍ ဝမ်းတွင်လည်းအစာမရှိသဖြင့် မူးဝေ၍ ဗုန်းခနဲပက်လက်လဲကျသွား၏။”')
,(11430,3,4,'၂။မျက်စိလည်လမ်းမှားသည်။','“မတ်ဂေတ်အာ စဴဒၞာဲဟွံဒး။” = “မျက်စိလည်၍ နေရာမပြန်တတ်တော့။”')
,(11431,3,4,'၁။ မျက်မမြင်ဖြစ်သည်။ မျက်စိကွယ်သည်။','“(ဒြာဲ) မိကဵုမဗောဓိသတ်ၜါဂှ် ဗျုလောန်အာတုဲ မတ်ဂၠုသီုညးၜါရ။” (ဇ—၅ဝ၁။ အစွောံ။) = “ဘုရားလောင်းသမင်၏ မိဘနှစ်ပါးသည် အလွန်အိုမင်းကုန်၍ မျက်စိမမြင်ကုန်။”')
,(11431,3,4,'၂။ မမြင်မကန်းဖြစ်သည်။ အမှန်ကို မဆင် ခြၚ်နိုင်ဖြစ်သည်။','“မန်ကဵုမန် မတ်ဂၠုတုဲ သ္ပသၞရၚ်သ္ကအ်ဂှ် ဝေၚ်ပဲါလၟိုန်ညိ။” = “မွန်အချင်းချင်း မမြင်မကန်းဖြစ်ကာ မဆင်ခြင်နိုင်ဘဲ ရန်ပြုကြခြင်းကို အမြဲရှောင်ကြဉ်ပါ။”')
,(11432,3,1,'ခြေမျက်စိ။','“ဇုတ်ၜါဆက်ဗျိၚ်၊ မတ်စိၚ်ဟီုပ္ညန်။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) = “အရိုးနှစ်ခုဆက်စပ်ထားသောခြေမျက်စိ။”')
,(11433,3,4,'အိပ်မောကျသည်။','“အနှိန်အဲဂ္ဇအ်ဒၟံၚ် မတ်စှ်ေအာမွဲခဏ။” = “ငါထိုင်နေစဉ်တစ်ခဏမျှ အိပ်မောကျသွားသည်။”')
,(11434,3,1,'နတ်မျက်စိ။',NULL)
,(11435,3,4,'သက်ရှိထင်ရှားဖြစ်သည်။','“ဇဖန်မတ်ပိုဲနွံဝွံဂှ် ပိုဲဇိုန်ကဵုကၟိန်ဍုၚ် ကဵုကောန်ပိုဲရ” သၟိၚ်မသၟိၚ်မိဂး။ (ဇ—၂၅၂။ အစွောံ။) = “ငါတို့သက်ရှိထင်ရှားရှိစဉ် ငါတို့၏သားတော်ကို ထီးနန်းအပ်နှင်းပေးကြပါစို့” ဟု ခမည်းတော်မယ်တော်တို့ဆို၏။ || ‘မတ်ဟွံမွဲ’ (ကြိ) လည်းရှု။')
,(11436,3,4,'မျက်လုံးပြူး မျက်ဆန်ပြူးဖြစ်သည်။ မျက်ကလူးဆန်ပျာဖြစ်သည်။ ထိတ်ထိတ်ပျာပျာဖြစ်သည်။',NULL)
,(11437,3,4,'မျက်လုံးပြူးသည်။ (ဥပစာ) အံ့သြသည်။ အံ့အားသင့်သည်။',NULL)
,(11438,3,1,'ပညာမျက်စိ။ (ပါဠိ—ပညာစက္ခု)',NULL)
,(11439,3,4,'မျက်စိစွေသည်။','“ဍိက်ဗြဴမွဲဂ္ညိ၊ ပ္ဍဲသ္ၚိသေထဳ။ — ဒျိုၚ်ကွသၠေဝ် (သလေဝ်) ၊ မတ်ပေဝ်ဓလန်။” (လိက်ဘောဂရေန်) = “သူဋ္ဌေးအိမ်­ တစ်ယောက်သောကျွန်မသည် အသားမည်းပုကွ၍ မျက်စိစွေမျက်စိပြူး၏။” (သလေဝ် = မတ်ပေဝ်)')
,(11440,3,1,'ပကတိမျက်စိ။','“အရာဝွံ ရံၚ်ကဵုမတ်ဖျုန်ဏအ်မ္ဂး ဟွံညာတ်ရ။ ဒးရံၚ်ကဵုမတ်ပညာရောၚ်။” = “ဤအရာကား ပကတိမျက်စိဖြင့်ကြည့်လျှင် မမြင်နိုင်ပါ။ ပညာမျက်စိဖြင့် ကြည့်ရပါမည်။”')
,(11441,3,1,'ကြောင်ကျောက်။',NULL)
,(11442,3,4,'မျက်ဖြူဆိုက်သည်။',NULL)
,(11443,3,1,'စိန်ကျောက်။',NULL)
,(11444,3,1,'မိုးတိမ်။','ဂၠံမတ်ဗြဲ = မိုးသားတိမ်လိပ်။')
,(11445,3,4,'မျက်ဖြူဆိုက်သည်။ မျက်ဖြူလန်သည်။','“ဝေဒနာဒမၠိ၊ ဂျိလုံခန္ဓာ။ လတေၚ်တံၚ်ဒြဲ၊ ဇိုၚ်တဲကေမ်အာ။ ပါၚ်ၜေဲမတ်ဗၠိုက်၊ ဒဒိုက်ဂၠိုၚ်ရာ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) =“ဝေဒနာပြင်းထန်၍ တစ်ကိုယ်လုံးကိုက်ခဲ၏၊ အကြောဆွဲ၍ ခြေလက်ကွေးသွား၏၊ ပါးစပ်ရွဲ့၍မျက်ဖြူလန်ကာ ဒုက္ခဝေဒနာလွန်ကဲ၏။”')
,(11446,3,4,'မျက်စိနာသည်။',NULL)
,(11447,3,4,'၁။ မျက်စိမှုန်သည်။',NULL)
,(11447,3,4,'၂။ မျက်စိကျိန်းသည်။',NULL)
,(11448,3,4,'မျက်စိစွေစောင်းသည်။',NULL)
,(11449,3,4,'မျက်စိကွယ်သည်။ သေလွန်သည်။','“ယွံအမာတ်တံ၊ မတ်အဲဟွံမွဲတုဲ ကၟိန်ဍုၚ်ဇိုန်ကဵုအသဒိသကုမာရ” သၟိၚ်ဂး။ (ဇ—၁၈၁။ အစွောံ။) = “အမတ်တို့၊ ငါသေလွန်သည်ရှိသော်တိုင်းပြည်ကို အသဒိသမင်းသားအား ပေးလေလော့” ဟုမင်းဆို၏။ || ‘မတ်နွံ’ (ကြိ) လည်းရှု။')
,(11450,3,4,'ဟိုကြည့်သည်ကြည့် မျက်လုံးလည်လျက်ရှိသည်။',NULL)
,(11451,3,7,'၁။ သောကြောင့်။ သဖြင့်။ သည်ဖြစ်၍။ (အကြောင်းပြသည့်အနက်ဖြင့် ဆက်စပ်ပေးသောစကားလုံး)','“မာတ်သူရိယကုမာ မအာလအ်ဂှ် ဗောဓိသတ်စကာဏာ စန္ဒကုမာပၠန်ရ။” (ဇ—၆။ အစွောံ။) = “သူရိယမင်းသားသည် အလွန်ကြာမြင့်သည်ဖြစ်၍ (ဘုရားလောင်းသည်) စန္ဒမင်းသားကို စေပြန်၏။” (ညောင်ကန်) || “ကွးလၞုဟ် မာတ်ဟွံဂွံကွတ်ဂှ် ဟီုဗျိပၠုတ်အ္စာဂွံဟာ၊လ္ပဗျိအ္စာရ ဗျိဇကုဟေၚ်ရ။” = “ပျင်းရိသောတပည့်သည် အတတ်ပညာမရရှိသဖြင့် ဆရာအားအပြစ်ဆို၍ရမည်လော။ ဆရာအား အပြစ်မတၚ်ပါလေနှင့်၊ မိမိကိုသာ အပြစ်တင်ပါလေ။” || “(သၟတ်ဗြဴဂှ်) ဍေံမၞုံစိုတ်မသဝ်တဴတုဲ တြုံတလသ္ၚိဍေံလေဝ်ကီု ခံါသဳဍေံလေဝ်ကီု မာတ်ဍေံဥပ္ပကာတုဲ သ္ဍိုက်မၠိုက်တဴဍေံရ။” (ဇ—၄၄၆။ အစွောံ။) = “ထိုသတို့သမီးသည် နှိမ့်ချကျိုးနွံတုံ့ဝပ်သောစိတ်ရှိ၍ ပြုစုလုပ်ကိုင်ပေးသဖြင့် လၚ်သည်၄င်း ယောက္ခမသည်၄င်း သူမကို ချစ်နှစ်သက်ကုန်၏။” || “မာတ်ဟွံဂွံကောန်ဂှ် တၠညးလ္ပဖဍိုန်စိုတ်ညိဏီအဴ။” (ဇ—၅၃၁။ အစွောံ) = “မြတ်သောမင်းကြီး၊ သားမရသဖြင့် စိတ်မလျှော့ပါနှင့်ဦး။”')
,(11451,3,7,'၂။ —ရင်း။ ဆောင်ရွက်ဆဲဖြစ်ကြောင်း ပြသောစကားလုံး။','“နသၞာ်ၚာၚ်အဲ သကေပ်ကြေဝ်ကၠေံကအ်ဗှ်ေရ” မာတ်ဂးသာ်ဝွံတုဲ ဂတာံသကေပ်တရံၚ်ၚာၚ် (ပ္ဍဲကအ်ပံက်ဂှ်) ရ။ (ဇ—၃၈။ အစွောံ။) = “ငါ့လက်မဖြင့် နင့်လည်ကိုညှပ်ဖြတ်ပစ်အံ့” ဟုဤသို့ဆိုရင်း ဗုဇွန်သည် ဗျိုင်း၏လည်ကို ပိုမိုတင်းကျပ်၍ညှစ်၏။')
,(11452,3,7,'သော်လည်း။ လင့်ကစား။','“မာတ်ရညးအာ ဟွံဆဵုအ္စာရ။” = “သူသွားသော်လည်း ဆရာ့ကိုမတွေ့ပါ။” || “မာတ်ရလုပ်တိတ် အပ္ဍဲဝၚ်မ္ၚးဝၚ် ကၠိုဟ်ခၠၚ်ကဵုဒှ်ကီု နွံစိုတ်သၟိက်ဂွံဒဒှ်ေဒယှ် ဓရီုသ္ကံဟီုဂး တလိန်တမက်ကဵုကမၠောန်မှောင်မှ ညးမဒှ်ပရိစာရိတ်တၠညးဂှ် လ္ပကဵုဂွံဒှ်”သၟိၚ်ဗြာဇ္ဇအမာတ်ဒိန်တံ ဝေတ်ဗ္တောန်လ္ဂန်အိန်။ (အကြီုရာဇာဓိရာဇ်) = “နန်းတွင်းနန်းပြၚ် ဝၚ်ထွက်ပေါက်ရောက်သည်ဖြစ်လင့်ကစား ရှင်ဘုရင်၏အလုပ်အကျွေးဖြစ်ကုန်သော ကိုယ်လုပ်မောင်းမတို့နှင့် ရင်းနှီးအကျွမ်းဝင် စည်းဝေးပြောဆိုကျီစယ်ခြင်း မပြုပါနှင့်။”')
,(11453,3,10,'(နဝိ) မိစ္ဆာ။ မှားသော။',NULL)
,(11454,3,10,'(န) မှားသောအယူ။ မိစ္ဆာဒိဋ္ဌိ။',NULL)
,(11455,3,10,'(န) မှားသောအသက်မွေးခြင်း။',NULL)
,(11456,3,1,'နနွင်း။','မိတ်ခပဵု = နနွင်းနှင့်ထုံး။')
,(11457,3,11,'မိတ်။ အဆွေခင်ပွန်း။ (ပါဠိ—မိတ္တ)',NULL)
,(11459,3,11,'အဆီခဲ။ (ပါဠိ—မေဒ)',NULL)
,(11460,3,1,'သရက်ကင်း။',NULL)
,(11461,3,1,'(ရှေးသုံး) ကသယ်။ ကသယ်မှုန့်။ (ရေချိုးသောအခါ ကြေးတွန်းရသောအမှုန့်တစ်မျိုး။)','“တၞဟ်နဂွံပၚုဟ်မိတ်ကၠေၚ်ဂှ် တွာန်ကသဳကရးမွဲ (သၟိၚ်ပဿိုန်) သကဵုသွက်ဒေံဗြဴဂှ်ရ။” (ဇ—၂၈၃။ အစွောံ။) = “(ကောသလမင်းသည်) မင်းသမီးအား ရေချိုးကသယ်မှုန့်ဘိုးပြု၍ — ကာသိရွာကို ပေးလိုက်၏။” (ညောင်ကန်) || “လစိန်မွဲရ၊ ပၚုဟ်ကျိုၚ်ကျဝ်။ ၚုဟ်မိတ်ကၠေၚ်ကီု၊ သီုၚုဟ်မြမောဝ်။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။)')
,(11462,3,1,'မိတ်ဆွေအပေါင်းအဖော်။',NULL)
,(11463,3,1,'ချစ်သူ။','“မိတ်ဂွိုၚ်မှာယျ၊ စဴပၠန်ရသဒှ်။ မၚ်ဗၠာဲကော်သၟာန်၊ ညးကွာန်တံဂှ်။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “မောင့်ချစ်သူမယ် ရပ်ရွာပြန်ပြန်ပြီထၚ်ပါရဲ့ဟုဆိုကာ လုလင်သည် ရွာသားတို့အား ခေါ်မေး၏။”')
,(11464,3,1,'မပြစ်မှားအပ်သော ခင်ပွန်းကြီးဆယ်ပါး။ (၁၊ ဘုရား။ ၂၊ ပစ္စေကဗုဒ္ဓာ။ ၃၊ရဟန္တာ။ ၄၊ အဂ္ဂသာဝက။ ၅၊ အမိ။ ၆၊ အဖ။ ၇၊ အလေးပြုအပ်သူ။ ၈၊ ဆရာ။ ၉၊ တရားဟောပုဂ္ဂိုလ်။ ၁ဝ၊ မိမိအားပေးကမ်းသူဟူ၍ ဆယ်ပါးရှိသည်။)',NULL)
,(11465,3,1,'ကြၚ်ဘက်။ ဖူးစာ။ ရှေးဘဝက ဒါနပြုဘက်။','“ဗောဓိသတ် ချိုန်မမိၚ်ပရိုၚ်လဟီုညးဂှ်ရ ဟိုတ်ဒှ်ဒါန်တမၠာ ဟိုတ်ဒှ်မိတ်ဒါန်ဂၠိုၚ်ကဵုဝါဂှ်ရ နူမိၚ်ဗက်စိုတ်စပ်အာ (ပ္ဍဲသၟတ်ဗြဴ) ရ။” (ဇ—၃၈၇။ အစွောံ။) = “ဘုရားလောင်းသည် သူတကာတို့၏ဆိုစကားကို ကြားသည်ရှိသော် အကြိမ်ကြိမ်ပေါင်းဖက်ဖူးသော ဖူးစာကြၚ်ဘက် ရှေးရေစက်ဖြစ်ခြင်းကြောင့် ကြားကြားချင်း မိန်းမပျို­ တပ်စွန်းသွား၏။” || ‘မိတ်ဒါန်တမၠာ။’ (ဇ—မဟောဟ်သဓ။ အစွောံ။) = ‘ရှေးဖူးစာကြၚ်ဖက်။’ || “သၟိက်ပမိတ်ဒါန်၊ အဲသၟိက်ဆာန်မိ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ငါသည် မယ့်ကို ဖူးစာကြၚ်ဘက်ပြုလိုချစ်လိုပါ၏။”')
,(11466,3,1,'နနွင်းနက်။ (ပါဠိ—ကပ္ပက)',NULL)
,(11467,3,1,'မိတ်ဆွေအပေါင်းအသင်း။ အဆွေခင်ပွန်း။','“(စိၚ်မ္ၚဵုဂှ်) ကၠဵုမွဲမဒှ်မိတ်ပြဝါနွံရ။” (ဇ—၂၇။ အစွောံ။) = “ထိုမင်္ဂလာဆင်အား အဆွေခင်ပွန်းဖြစ်သော ခွေးတစ်ကောင်ရှိ၏။” || “မိတ်ပြဝါသေဋ္ဌဳမွဲ ကာလကဏ္ဍဳဂးယၟု၊ ဝေၚ်ခနှိက်တိမွဲစွံ။” (ဇ—၈၃။ အစွောံ။) = “ကာလကဏ္ဍဳမည်သော သူဋ္ဌေး၏မြေမှုန့်အတူကစားဘက်ဖြစ်သော အဆွေခင်ပွန်းသည်ရှိ၏။” || ‘ပမိတ်ပြဝါ’ (ကြိ) လည်းရှု။')
,(11468,3,4,'မိတ်ပျက်သည်။ မိတ်ဆွေအဖြစ် ဆက်ဆံရင်းနှီးမှုပျက်ပြားသည်။','“(ဥဿဘကဵုဇာဒိသိုၚ်) ညးၜါဂှ် ဟွံဂတာပ်လအ် မိတ်လီုအာကဵုရၚ်သ္ကံ—။” (ဇ—၃၄၉။ အစွောံ။) = “ထိုနှစ်ခုကုန်သော ဥသဘနှင့်ခြင်္သေ့တို့သည် မကြာမြင့်မီတွင် မိတ်ပျက်သွားကြကုန်၏။”')
,(11469,3,11,'(န) မိတ်ဆွေ။ အဆွေခင်ပွန်း။ မိတ်သဟာယ။ (ပါဠိ—မိတ္တသဟာယ)','“မိတ်သဟာဲမ္ဂးဂှ် ယုတ်ပြဲဟွံဂပ်ဂဝ်သ္ဂး၊ ညးဗလးကဵုဒဒိုက် ဇိုန်ကဵုတသိုက်ဇကုမာန်ဂှ် ဒှ်မိတ်မပြဲရ။” (ဇ—၁၂၁။ အစွောံ။) = “အဆွေခင်ပွန်းမည်သည်ကို ယုတ်သည်မြတ်သည်ဟု မဆိုရာ။ မိမိအား ဒုက္ခမှလွှတ်၍ မိမိ၏ချမ်းသာကို ဆောင်ကြဉ်းပေးနိုင်သောသူသည်သာ မြတ်သောအဆွေခင်ပွန်းမည်၏။” || ‘မိဿဟာဲ’ ဟုလည်း အချို့ရေးနေကြသည်။')
,(11470,3,11,'(န) မိတ်သၚ်္ဂဟ။ ခင်မင်ရင်းနှီးသော အပေါင်းအသင်း။',NULL)
,(11471,3,11,'(န) ကြင်ဖက်။ ကြင်လျာ။ အိမ်ထောင်ဖက်။','“ညးၜါသၟဟ်သၟန် ဒက်လဝ်မိတ်သမ္ဗန္ဓတုဲ—။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = နှစ်ယောက်သားတို့သည် ညီညွတ်ကုန်၍ကြၚ်ဖက်မိတ်ဖွဲ့ကြကုန်၏။” || “ယွံမၞးတံ၊ ပိုဲဇာတိမၞိဟ်မပြဲဝွံဂှ် မွဲဟာန်ကေုာံတိရစ္ဆာန်ဂှ် သကဵုဒှ်မိတ်သမ္ဗန္ဓဂှ် ဟွံထေက်ကြိုက်ဟေၚ်ရ” သၟိၚ်ဂးကဵုနာ်ဂမၠိုၚ်။ (ဇ—ဘူရိဒတ်။ အစွောံ။) = “အချင်းတို့၊ မြတ်သောလူသားဇာတိဖြစ်သောငါတို့သည် တိရစ္ဆာန်နှင့်တကွ အိမ်ထောင်ဖက်ကြၚ်လျာဖြစ်စေခြင်းသည် မလျောက်ပတ်” ဟုမင်းသည် နဂါးတို့အားပြော၏။ || “ရမတ်သၟိၚ်ဓဝ်၊ ဇွောဝ်တဴပၠိတ်ပၠိတ်။ ဂိုဟ်တဴလအိတ်၊ ဂိုဟ်မိတ်အဒံါ။ စံၚ်တူသုန်ဒြာံ၊ သ္ၚံသ္ၚံယာံတဴ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “မင်းသည် ကြၚ်ဖက်ကို နှမြောလွန်းလှသဖြင့် မျက်ရည်တပေါက်ပေါက်ကျကာ ပူဆွေးငိုကြွေး၏။” || “ဃောသ္ဍိုက်လးလေၚ်၊ ဟေၚ်မိတ်အဒံါ။” (လိက်သောဝါနနဟောၚ်) = “ကြၚ်ဖော်နှင့် ချစ်ကြင်နာတုန်းကာလဖြစ်၏။”')
,(11472,3,1,'ကြၚ်ဖော်။ ကြၚ်ဖက်။','“ဗှ်မိတ်အဒံါ၊ ဂြာံသက္ကုဖဵု။” (လိက်မေဃကောန်ဒြာဲ)')
,(11473,3,1,'ချစ်သူ။ ကြၚ်သူ။','“ဟးမဂေါဝ်လောန်၊ ဗြဴကောန်ကုသဵု။ ညာတ်အသဝ်အဵု၊ဂြိုပ်ဒဵုဒေသ။ ဗှ်မိတ်အလေၚ်၊ ကေၚ်ဝေၚ်ဖဴမ။” (လိက်မေဃကောန်ဒြာဲ) = “အို—လှလွန်းသူကုသိုလ်ရှင်မ၊ အံ့ဖွယ်တောတောင်ရေမြေဒေသကို မြင်ရသည်ရှိသော် မောင်နှင့်အတူ ကစားပျော်ဖူးသောချစ်သူမယ်အား အောက်မေ့မိ၏။” || “သၟိၚ်ညာတ်သာ်ဂှ်၊ ဗှ်မိတ်အလေၚ်။ သီုရေဝ်ရောတ်ဟေၚ်၊ ယာံတဴသေၚ်ဟာ။” (လိက်မေဃကောန်ဒြာဲ)')
,(11474,3,1,'ဆရာ့လက်ဆုပ်။ ဆရာကြွင်း။ (ပါဠိ—အာစရိယမုဋ္ဌိ)','“မုဋ္ဌဳအစာဟွံဂွံဖျေံလဝ်တုဲ ဗွဲမသက္ကုသၟိဟ် ပကတ်ကဵုသီုဖအိုတ်ရ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ဆရာ့လက်ဆုပ်မချန်ဘဲ အတတ်အားလုံးကို အကုန်အစင်သင်ကြားပေး၏။” || ‘တၞုၚ်ကွတ်’ နှင့်အတူတူ။')
,(11475,3,1,'အမှား။ မှားယွင်းခြင်း။','“ဒၞာဲမဒှ်မုတ်ဂှ် ကဵုစှ်ေပဲါ၊ ဒၞာဲမဒှ်ဒွး ကဵုဒ္ဂေတ်ဗက်ညိ။” (သၠပတ်ကာလထေ) = “အမှားကို ရှောင်ကြဉ်စေ၊ အမှန်ကို လိုက်နာစေ။” || ဒ္ဂေတ်မုတ် = မှားယွင်းသောအကျင့်။ ဖောက်ပြားသောအကျင့်။ || ပြဝမုတ်၊ ပွမုတ် = မှားယွင်းသောအမှု။ ဖောက်ပြားသောအမှု။ || “ဒဒှ်ဒ္ဂေတ်ပြဝအဲဟွံခိုဟ်ဂှ် အ္စာတီကေတ်ရ” ဂးတုဲ (သမ္ဘာမၚ်ဗၠာဲဂှ်) ဒ္ဂေတ်ပြဝမုတ်ဂှ် ထောံကၠေံရ။ နွံတဴကဵုသဳလစာရဝတ်ပတိပတ်ပၠန်ရ။ (ဇ—၆၅။ အစွောံ။) = “ငါ့အကျင့်မကောင်းသည်ကို ဆရာသိသွားလေပြီတကား” ဟု လုလင်၏မယားသည် ဖောက်ပြားသောအကျင့်ကို စွန့်လေ၏။ ကောင်းသောအကျင့်သီလရှိသည်ဖြစ်ပြန်၏။ || “သမ္ဘာဗမၞးဂှ် ဒှ်ဒုဿဳလ ပအာပြဝမုတ်ရောၚ်။” (ဇ—၂၁၂။ အစွောံ။) = “ပုဏ္ဏား၏မယားသည် ဒုဿီလဖြစ်၍ ဖောက်ပြားသောအမှုကိုပြု၏။” || ကွေတ်မုတ် = မှားယွင်းသောအယူ။ မိစ္ဆာအယူ။ || “ပဟိုတ်ကဵုတဳအာဇဳဝက မဂိုၚ်ကေတ်ကွေတ်မုတ်ဂှ်တုဲ နၚ်္ဂုဋ္ဌဇာတ်ကျာ်တြဲတွံ။” (ဇ—၁၄၄။ အစွောံ။) = “တက္ကတွန်းတို့၏ မိစ္ဆာအယူကိုယူခြင်းကို အကြောင်းပြု၍ ဤနင်္ဂုဋ္ဌဇာတ်ကို ဟောတော်မူ၏။” || ‘လၟုတ်’ (န) နှင့်အတူတူ။')
,(11476,3,12,'(န) စပျစ်သီး။',NULL)
,(11477,3,1,'အမှားအမှန်။','“ကောန်ၚာ်သၟတ်မ္ဂးဂှ် ဟွံတီမုတ်ဒွးရ။” = “ကလေးသူငယ်မည်သည်အမှားအမှန်ကို မသိပါ။” || “ယွံအာစာပိုဲ၊ ဟိုတ်ပိုဲဍိက်မရှာဲအာ နူအာစာမထ္ၜးမုတ်ဒွး (သုၚ်ဒးသုရာရအဴ။)” (ဇ—၈၁။ အစွောံ။) = “ဆရာ၊ အကျွန်ုပ်တို့သည် အမှားအမှန်ကို ညွှန်ပြပေးသောဆရာမှ ဝေးကွာသောကြောင့် သုရာကို သောက်မိကြပါကုန်၏။” || “ယြဴသၟိၚ်မွဲ ပွစရၚ်ကိစ္စမွဲမွဲမပ္တုဲဂှ် ဟွံဂွံစဳစတ်ဗစာရဏာ ဟွံဂွံချပ်ပိုၚ်ခြာမုတ်ဒွးကၠာကြဴတုဲ သၟိၚ်မစဳရေၚ်ကိစ္စမွဲမွဲဂှ် သၟိၚ်ဂှ်ဟွံဆာဲရ။” (ဇ—၅ဝ၅။ အစွောံ။) = “တစ်စုံတစ်ခုသော အမှုကိစ္စကိုပြုသောမင်းသည် အမှားအမှန်ရှေ့နောက်ကို မစိစစ်မဆင်ခြင်မူဘဲပြုလျှင် ထိုမင်းသည်မကောင်း။” || “ယွံကောန်၊ အဲသၟိၚ်မ၊သဒိုဟ်သဒီု ဟွံဗစာရဏာမုတ်ဒွး မဒးဒှ်တုဲရ” သၟိၚ်ဂး။ (ဇ—၅ဝ၅။ အစွောံ။) = “ချစ်သားတော်၊ ငါခမည်းတော်မင်းသည် မိုက်မဲသည်ဖြစ်၍ အမှားအမှန်ကို မဆင်ခြင်မိဖြစ်ခဲ့ရပြီ။” || ‘ဟွံတီမုတ်ဒွးမွဲသာ်’ (ကြိ) လည်းရှု။')
,(11478,3,11,'(န) မုဒ္ဓဋ္ဌာန်။ (အချို့အက္ခရာတို့ကို ရွတ်ဆိုရာ­ ခံတွင်းလေထိခတ်ရာ လျှာထိပ်အရပ်) (ပါဠိ—မုဒ္ဓဋ္ဌာန)',NULL)
,(11479,3,10,'(န) ချစ်ခင်ခြင်း။ မေတ္တာ။',NULL)
,(11480,3,16,'(၁) လှိၚ်သိုက် (ချမ်းသာစွာအိပ်ရ၏။) (၂) ၚုဟ်သိုက် (ချမ်းသာစွာနိုးရ၏။) (၃) ဟွံဂွံလ္ပအ်ညာတ်လ္ပအ်မယုတ်မာ (ယုတ်မာသောအိပ်မက်ကို မမြင်မက်ရ။) (၄) မၞိဟ်သ္ဍိုက် (လူတို့သည် ချစ်မြတ်နိုးကုန်၏။) (၅) ကလော်သ္ဍိုက် (နတ်တို့သည် ချစ်ကုန်၏။) (၆) ဒေဝတဴဒးမၚ်မွဲ (နတ်တို့သည် စောင့်ကုန်၏။) (၇) လွဟ်ဗၞုဟ်ဇြၚ်ကံတ္ၚ ပန်စုတ်ဟွံဒး၊ ပၟတ်ဟွံတူ၊ ဂျိဟွံတိုန် (လက်နက်သည်လည်း မစူးမရှနိုင်၊ မီးသည်လည်းမလောၚ်နိုင်၊ အဆိပ်သည်လည်း မသင့်နိုင်။) (၈) စိုတ်တန်ကြန် (စိတ်တည်ကြည်၏။) (၉) မုက်သ္ဇုၚ်ဂေါဝ် (မျက်နှာအဆင်းသည် အထူးသဖြင့်ကြည်လင်၏။) (၁ဝ) ပကာဂစိုတ်ဟွံဝိဝိၚ် (မတွေမဝေသေရ၏။) (၁၁) ပၟဝ်ဗြဟ္မဝိဟာရ ဓဝ်မေတ္တာဂှ်တုဲ ၜိုန်ဟွံဂွံၛာန်ကီု ဗွဲဥပ္ပစာၛာန်ဂှ် စုတိစိုပ်ဍုၚ်ဗြီုရ။ (မေတ္တာ တရားဖြင့် ဗြဟ္မဝိဟာရကို ပွားများသည်ရှိသော် ဈာန်မရသော်လည်း ဈာန်၏အနီးအနားသို့ ရောက်သဖြင့် ဗြဟ္မာ့ပြည်သို့ လားရ၏။)',NULL)
,(11481,3,11,'(န) မေတ္တာစိတ်။',NULL)
,(11482,3,4,'မေတ္တာသက်ဝၚ်သည်။ မေတ္တာမျှသည်။','“သၟိၚ်ညာတ်ကၞပ်၊ မေတ္တာစပ်အာ။ညာတ်ဒးရုပ်သၟတ်၊ ဗြဴရတ်ကညာ။” (လိက်မၚ်ဗၠာဲဟောံလွဳ) = “ရတနာမယ်ကညာပျိုကို မြင်သည်ရှိသော် မင်းသည် မေတ္တာသက်ဝၚ်ချစ်ကြင်နာသွား၏။”')
,(11483,3,4,'(မိမိမကြိုက်သည်ကို ပြုသောသူအား) ဆက်၍မေတ္တာမထားနိုင်ဖြစ်သည်။မေတ္တာပျက်သည်။','“ဍေံဏအ် ဟိုတ်စိုတ်ယုတ်မာတုဲ အဲမေတ္တာပ္ဍုၚ်အာဣရ။” = “ဤသူသည် ယုတ်မာသောစိတ်ရှိသဖြင့် ငါမေတ္တာပျက်သွားပြီ။”')
,(11484,3,10,'(န) မဉ္ဇူသကပန်း။ (ဟိမဝန္တာ နန္ဒမူလိုဏ်ဝ­ ပေါက်သောပန်းပၚ်။)',NULL)
,(11485,3,10,'(န) မွန်လူမျိုး။','မညဘာသာ = မွန်ဘာသာ။ || ရးမည = မွန်ပြည်။')
,(11486,3,1,'မွန်လူမျိုး။',NULL)
,(11487,3,1,'မွန်ဒိုၚ်၊ မွန်ဒ၊ မွန်ညဟူသသောမွန်သုံးရပ်။','“မန်ဒိုၚ်မန္ဒရ၊ မညသီုပိပၠန်။ မန်ပိဘာသာရ၊ မညရောၚ်တိတ်ဇန်။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။)')
,(11488,3,11,'(န) မန္တန်။ မန္တရား။','“ယွံဗမၞး၊ မန်ဝွံ အနဂ္ဃမန်ရောၚ်။ နိသြဲကဵုမန်ဝွံတုဲ ဒြပ်ဂၠိုၚ်ကလိဂွံရ။” (ဇ—၄၇၄။ အစွောံ။) = “ချစ်သားလုလင်၊ ဤမန္တရားသည် အဘိုးများစွာထိုက်၏။ ဤမန္တရားကိုမှီ၍ သၚ်ချစ်သားအား များစွာသောလာဘ်ပူဇော်သက္ကာရသည် ဖြစ်လတ္တံ့။” (ညောင်ကန်) || “မၚ်ဗၠာဲသဥ္ဇိဝတုန် မန်မက္တဵုဇွဂှ်မကတ် မန်မဆေဝ်ဒဝ်ဇွဂှ်ဟွံကတ်။” (ဇ—၁၅ဝ။အစွောံ။) = “သဥ္ဇိဝလုလင်သည် အလောင်းကိုထစေသော မန္တရားကိုသင်၏။ အလောင်းကိုတားမြစ်သော မန္တရားကိုကားမသၚ်။” || ‘ပၟန်’ (န) လည်းရှု။')
,(11488,3,11,'(ကြိ) (မန္တန်၊ မန္တရားကို) မန်းမှုတ်သည်။ သရဇ္ဈာယ်သည်။ (ပါဠိ—မန္တ)','“(မၚ်ဗၠာဲ) သဥ္ဇိဝရပ်ကြေဟ် မန်မဂၠိုၚ်ကဵုလတုန်တုဲ ဗိုတ်စုတ်ဇွကၠ ခြုဟ်ဇွကၠဒလိုက်က္တဵု—။” (ဇ—၁၅ဝ။ အစွောံ။) = “သဥ္ဇိဝလုလင်သည် ကျောက်စရစ်ကိုကိုင်၍ မန္တရားကို အကြိမ်ကြိမ်သရဇ္ဈာယ်ပြီးလျှင် ကျားသေကို ကျောက်စရစ်ဖြင့်ပစ်၏။ ကျားသေသည် ရုတ်ချည်းထ၏။” || “ဝိဇ္ဇာဓဵုမွဲဂှ် ဍေံမန်ပၟန်တုဲ ပ္ဍဲကာလဗ္တံဂှ် ဍေံလုပ်ကၠုၚ်ပ္ဍဲဂၠံသ္တိက်ဂၞကျာ်ဇၞော်—။” (ဇ—၃၉၁။ အစွောံ။) = “ဝိဇ္ဇာဓိုရ်တစ်ယောက်သည် မန္တရားကိုမန်း၍ သန်းခေါၚ်ယံ­ လာလတ်၍ (မိဖုရားကြီးအိပ်ခန်းဆောင်သို့ ဝၚ်လာ၏။)” (ညောင်ကန်)')
,(11489,3,4,'(ဂါထာ) မန်းမှုတ်သည်။ သရဇ္ဈာယ်သည်။','“ဗမၞးဒစာံ၊ မန်ဂြာံဂါထာ။” (လိက်ဇိဝှစက္က) = “ပုဏ္ဏားရှစ်ယောက်တို့သည် ဂါထာကို မန်းမှုတ်သရဇ္ဈာယ်ကုန်၏။”')
,(11489,3,1,'ဂါထာ။မန္တန်။','“ဝိဇ္ဇာဓဵုပၠန်၊ သှ်ဇျာဲမန်ဂြာံ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “ဝိဇာဓိုရ်သည် မန္တန်ကို မန်းမှုတ်သရဇ္ဈာယ်၏။”')
,(11490,3,11,'(န) စကြဝတေးမင်း။ မန္ဓာတ်မင်း။','(ပါဠိ—မန္ဓာတာ)')
,(11491,3,1,'အခွင့်အာဏာ။','“ကဵုဒှ်စၞ၊ ယက္ခဗြဴကၠာ။ မဂွံလဝ်အဵု၊ အဝဵုမန္တာ။ ဗဳသြဴရာဇာ၊ ကဵုလဝ်ခါဂှ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ဘီလူးမ၏အစာဖြစ်စေဟု ဘီလူးမသည် အခွင့်အာဏာကိုရ၏၊ ဝေဿဝဏ်နတ်မင်းက ထိုစဉ်အခါ အခွင့်ပေးထား၏။” || ‘အမန္တာ’ (န) နှင့်အတူတူ။')
,(11492,3,12,'(န) မန္တရား။','“ပဟိုတ်မဆိုက်ဗ္ဒက် ပ္ဍဲကွတ်မန်ယန်မန်တြဂှ်။” (သၠပတ်ရာဇာသာန်) = “မန္တန်မန္တရားအတတ်­ ကျွမ်းကျင်လိမ္မာခြင်းကြောင့်။” || “နတြဳဇှ်ပၠန်၊ ဥုံသွးမန်တြ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ဂါထာမန်းမှုတ်ခြင်းနှင့် မန္တရား၏အာနုဘော်ဖြင့်။” || ‘မန်ယန်’ (န) နှင့်အဓိပ္ပါယ်အတူတူ။')
,(11493,3,1,'မန္တန်။ မန္တရား။','“ယွံဗမၞး၊ မူရဴကွတ်ဗိုတ်မွဲမွဲမလေပ်တုဲ မူရဴမန်ယန်မွဲ မဂွံပကၚ်ရၚ်လဝ်တုဲ အဲမဒးကဵုလွဵု ဗမၞးမအာတ်တံဂှ်ရော” သၟိၚ်ဂး။ (ဇ—၄၅၆။ အစွောံ။) = “ပုဏ္ဏား၊ အဘယ်မည်သော ဗေဒင်အတတ်ကိုတတ်၍၊ အဘယ်မည်သော မန္တရားကိုပိုင်စိုး၍ သၚ်တောင်းအပ်သောဆုလာဘ်ကို သင့်အားပေးရအံ့နည်း” ဟုမင်းဆို၏။ || “ဍေံမဒှ်ဝိဇ္ဇာဓဵုမလေပ်မန်ယန်—။” (ဇ—၃၉၁။ အစွောံ။) = “ထိုသူကား မန္တရားတတ်သော ဝိဇ္ဇာဓိုရ်တည်း။” || “နဂဥုဲပၠန်၊ မန်ယန်နာနာ။ ဗက်မၚ်မွဲဟေၚ်၊ ကွးဇကုသေၚ်ဟာ။” (လိက်ကာကဒိပ္ပ။ မဟာကြၚ်။) = “ဆေး၊မန္တန်မန္တရားအမျိုးမျိုးတို့ဖြင့် မိမိတပည့်ကို လိုက်လံစောင့်ရှောက်၏။”')
,(11494,3,11,'(န) မာန။',NULL)
,(11495,3,4,'နိုင်သည်။ အနိုင်ရသည်။','“ပ္ဍဲပေဲါပြိုၚ်ဒြေပ်ဏအ် အဲမာန်ရောၚ်။” = “ဤအပြေးပြိုင်ပွဲတွင် ကျွန်တော်နိုင်မည်။”')
,(11495,3,9,' ပြုနိုင်၊ ဖြစ်နိုင်ကြောင်းကို ပြသောစကားလုံး။','ကၠောန်မာန် = လုပ်နိုင်သည်။ || အာမာန် = သွားနိုင်သည်။ || ဒှ်မာန် = ဖြစ်နိုင်သည်။')
,(11496,3,4,'(အိုးစသည်လုပ်ရာတွင် မြေစေးစသည်ကို) လက်ဖြင့်ကိုင်တွယ်ပုံသွင်းသည်။','“တြုံလၟာန်မွဲ တၞဟ်နမာန်ထၟာဲ ဍေံခဲါတိကမၠေတ်ရ။ (ဇ—၄၃၂။ အစွောံ။) = “အိုးထိန်းသည်ယောကျာ်းသည် အိုးလုပ်ရန်အလို့ငှာ မြေစေးကိုတူး၏။” || “ဍုၚ်ပိုဲမၞိဟ်ဝွံဂှ် မာန်ဍိုတ်တုဲ မဂွံဒက်ကၟာၚ်ဍုၚ်ရောၚ်။” (ဇ—၂၄၃။ အစွောံ။) = “ငါတို့လူ့ပြည်­ လက်ဖြင့်အုတ်ကိုလုပ်ပြီးမှမြို့ရိုးဆောက်လုပ်ရကုန်၏။” || “ဗၞတ်မာန်စနုၚ်ထမာဲတံကီုလေဝ် ၜိုန်မှုဟ်သဓတၠပညာ မဒးအာခစလၟာန်ဂှ်ကီု။” (ဇ—၃၇၃။ အစွောံ။) = “ပညာရှိမဟော်သဓာသည်ပၚ် အိုးခွက်တို့ကိုလုပ်သောအိုးထိန်းသည်ကိုလည်း ခစားရသေး၏။”')
,(11497,3,1,'ရန်ပြုလိုစိတ်။ မာန်စောၚ်။ မာန်မာန။','“ကောအဲဂှ်ညးဇမၞော် ပတိုန်လဝ်မာန်စံၚ်ဟွံဒွး။” (အကြီုရာဇာဓိရာဇ်) = “နောင်တော်သည် လူကြီးဖြစ်ပြီး မာန်စောၚ်ထောၚ်ထားသည်မှာမမှန်။” || “အောန်ကဵုမာန်စံၚ် ဟွံဂွံကြံၚ်မ္ၚိုဟ်သ္ကာတ်သာဲ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ရန်ပြုလိုစိတ်နည်းပါး၍ မခက်ထန်မကြမ်းကြုတ်။” || “မာန်စံၚ်ဒဟဵု၊ သီုကဵုဒေါသ။” (လိက်ဟတ္ထိပါလ။အစွောံ။) = “ဒေါသမာန်စောၚ် တောက်လောင်သည်။”')
,(11498,3,4,'မာနကြီးသည်။ ဘဝၚ်မြင့်သည်။','“မၚ်ဗၠာဲကတာဟက စိုတ်သၠုၚ်မာန်ဇၞော်အာ။” (ဇ—၁၂၅။ အစွောံ။) = “ကဋာဟကလုလင်သည် မာနကြီးဘဝၚ်မြင့်သွား၏။”')
,(11499,3,4,'မာန်ဟုန်ပြင်းသည်။ စိတ်လိုက်မာန်ပါပြုသည်။','“ဒေံအဲညးမသုန်ဂှ် စိုတ်ပြဟ်မာန်သ္ကာတ်အာ ဟွံဗစာရဏာရံၚ်ဗိုန်က္ညန်တုဲ — ဇကုမဒးပကာဂစိုတ်တုဲရ။” (ဇ—၁၅၂။ အစွောံ။) = “ငါ့ညီငါးယောက်တို့သည် သေချာစွာမဆင်ခြင်ကြဘဲ စိတ်စောလွန်း၍ စိတ်လိုက်မာန်ပါပြုသဖြင့် သေကြရကုန်၏။”')
,(11500,3,4,'မာနတက်သည်။ ဘဝၚ်မြင့်သည်။','“ကၠဵုဂြိုပ်ဂှ် စိုတ်ဇၞော်မာန်သၠုၚ်အာ တိတ်ပ္တောံၜတ်ကဵုဇာဒိသိုၚ်တုဲ ဒးအိုတ်အာလမျီုရ။” = “မြေခွေးသည် စိတ်ကြီးဝၚ် မာနတက်ကာ ခြင်္သေ့နှင့်နှိုင်းယှဉ်သဖြင့် အသက်ဆုံးရှုံးရလေ၏။”')
,(11501,3,11,'(န) မိန်ရာသီ။ (ဆယ့်နှစ်ရာသီတွင် ငါးနှစ်ကောင်ရုပ်ဖြင့် မှတ်အပ်သော ဆယ့်နှစ်ခုမြောက်ရာသီ။)',NULL)
,(11502,3,4,'ဖက်သည်။ ပိုက်သည်။ ပွေ့ချီသည်။','“ကောန်ၚာ်သၟတ်ဂှ် မိန်လဝ်မိဍေံရ။” = “ကလေးငယ်သည် သူ့မိခင်ကို ဖက်ထားသည်။” || “(သၟိၚ်စိၚ်) နလပှ်ဇွိတ်သပေါတ်ကောန်ၚာ်ဂှ်တုဲမိန်ကေတ်သၟတ်ဂှ်တုဲ ပတိုန်စွံလဝ်လတူကၟံၚ်—။” (ဇ—၁၅၆။ အစွောံ။) = “ဆင်မင်းသည် ကလေးငယ်ကို နှာမောင်းဖြင့် သုံးသပ်ပြီးလျှင် ပွေ့ချီ၍ ဦးကင်းထက်­ တင်ထား၏။” (ညောင်ကန်)')
,(11502,3,9,'တစ်ပွေ့။ တစ်ပိုက်။','ဆံက်ပိမိန် = ကောက်ရိုးသုံးပွေ့။')
,(11503,3,6,'ပါဠိမှဘာသာပြန်ရာတွင်သုံးသော နာမ်ရှေ့ဆက်ဝိဘတ်။','“တယာဇ္ဇဂုတ္တာ၊ ၚ်အဲမိန်သၟိၚ်တ္ၚဲမမၚ်မွဲတဴဂှ်။ ရတ္ၚ်္တံ၊ လုကဴမွဲဗတံ။ ဝိဟာရေမု၊ စိုန်ကဵုဂွံပဒတဴ နတသိုက်ညိ။” (ဇ—၁၅၉။အစွောံ။) = “အရှင်နေမင်းသည် စောင့်ရှောက်အပ်သောငါသည် တစ်ညပတ်လုံး ချမ်းသာစွာနေရပါလို၏။”')
,(11504,3,4,'ဖက်ကိုင်တွဲခေါ်သည်။ ဖေးမသည်။','“ကုသဵုဂှ် မိန်သတဲသ္ၜသဘာ်နၚ်သၟိၚ်မတုဲ ကၠုၚ်က္တဵုဗဒှ်လဝ်သၟိၚ်မပြဲ ဒေါဝ်ဗွဝ်ပိုန်ကုသဵု မဇိုန်ကဵုသၟိၚ်မရောၚ် ဟွံသေၚ်ဟာအဴ။” (ဇ—နာရဒ။ အစွောံ။) = “ထိုကုသိုလ်ကောင်းမှုက ခမည်းတော်မင်းအား ဖက်ကိုင်တွဲခေါ်ဖေးမ၍စည်းစိမ်ပုံအလယ်­ မြတ်သောမင်းအဖြစ်ကို ဆောက်နှင်းပေးသည် မဟုတ်တုံလော။”')
,(11505,3,1,'‘မိၚ်ဒၠုၚ်’ ရှု။',NULL)
,(11506,3,16,'(န) အမိန့်တော်။','“ဟောရာမိၚ်အဵု၊ ယဵုဒုၚ်မိန်ဒဝ်။” (လိက်ဇိဝှစက္က) =“ဟူးရားကြားသည်ရှိသော် မင်းအမိန့်တော်ကို ဦးထိပ်ရွက်၍။”')
,(11507,3,4,'ပွေ့ပိုက်သည်။ ပွေ့ချီသည်။','“နလပှ်စိၚ်ဂှ် မိန်ကေတ်ကောန်ကၠဵုဂှ်တုဲ ပ္တိုန်ဏာလတူကၟံၚ်ဂှ်တုဲ မိန်မံၚ်ပူဗန်တဴရ။” (ဇ—၂၇။ အစွောံ။) = “ဆင်သည် နှာမောင်းဖြင့် ခွေးကလေးကိုပိုက်ချီ၍ ဦးကင်းထက်­တင်လျက် ပွေ့ပိုက်ဖက်ချီ၏။” || “နူကၠာတေံ ဂွံမိန်မံၚ်ဗစလဝ်အဲဍိက်—။” (အကြီုရာဇာဓိရာဇ်) = “ယခင်က ကျွန်ုပ်ကို ပိုက်ချီကျွေးမွေးထားဖူး၏။”')
,(11508,3,4,'ပွေ့ဖက်သည်။ ပိုက်ချီသည်။ ထွေးပိုက်သည်။ (ပါဠိ—ကုသတိ/သဇတိ)','‘ဂုဏ်မိကဵုမၜါ မိန်မအ်ဖျီုဖအအ် မၚ်မွဲဇၞော်သလုၚ်လဝ်ကောန်ဂှ် အနန္တဂုဏ်ရ။’ = ‘သားသမီးကိုကြီးပြင်းလာအောင် ပွေ့ချီပိုက်ထွေး ကျွေးမွေးစောင့်ရှောက်ထားသော မိဘနှစ်ပါး၏ကျေးဇူးကားအနန္တကျေးဇူးတည်း။’ || “ဟိုတ်ဒှ်ကောန်ကၠၚ် ဂွံလွဳပရာဖျီုဖအအ် ဗမဴဗစမိန်မအ် သၟဟ်ကောန်ကီု။” (အကြီုရာဇာဓိရာဇ်) = “မိဘမဲ့ကလေးဖြစ်ခြင်းကြောင့် သားအရင်းပမာ မွေးမြူခွံ့ကျွေးနို့တိုက်ပိုက်ထွေးထားရ၏။” || “သမ္ဘာညးရ၊ ညာတ်ထသပါ။ သၟိက်ဂွံမိန်မအ်၊ ဆအ်လအ်ညဳသာ။ချိုတ်ဒးနရက်၊ ဂၠက်ဒဵုဂတာ။” (လိက်ဂစေံဍာ်မိတ်။ နာဲမန်ၜိုပ်ထဝ်။) = “သူတစ်ပါးမယားကိုမြင်၍ အတူတကွ ပွေ့ဖက်ချစ်ကြင်နာချင်လျှင် သေသောအခါ ငရဲချိုးကပ်လိမ့်မည်။”')
,(11509,3,1,'မီးရှူး။ မီးရှူးမီးတိုၚ်။ (ပါဠိ—ဥက္ကာ/ဒဏ္ဍကဒဳပိကာ)','“ညံၚ်ပၟတ်မိန်ရှော ညးသၠာန်စုတ်ပန်ဒိုဟ်ဇကုကီု။” (ဇ—၂၈၂။ အစွောံ။) = “ကိုယ်၏လေးဘက်လေးတန်မှမီးရှူးဖြင့်ရှို့ဘိသကဲ့သို့။” || “မၞိဟ်ဂမၠိုၚ် ရပ်ကေတ်မိန်ရှောတုဲ ဗက်အာလၟာ်ဇိုၚ်ကမၠတ်ရ။” (ဇ—၃၁၁။ အစွောံ။) = “လူတို့သည် မီးရှူးကိုယူ၍ ခိုးသူ၏ခြေရာသို့ လိုက်သဖြင့်—။” (ညောင်ကန်) || “(ပၟတ်ဂြိုပ်ဂှ်) ညံၚ်ပၟတ်မိန်ရှောမအာစိုပ်ဍာ်ကီု သိုဟ်ပၠိုတ်အာကၠေံ အိုတ်သ္အးရ။” (ဇ—၃၅။ အစွောံ။) = “(ထိုတောမီးသည်) ရေ­ပစ်အပ်သော မြက်မီးရှူးကဲ့သို့ ငြိမ်း၏။” (ညောင်ကန်) || ‘မာဲရှော’ နှင့်အတူတူ။')
,(11510,3,1,'မီးရှူး။','‘မိန်ရှော’ နှင့်အတူတူ။ || “(ခမဳဂှ်) ရံၚ်ညးၜါဂှ်ဟွံစိုပ်တုဲ ကေတ်မိန်ရှောတဴၜံၚ်တုဲ ဒစးကၠုၚ်တုဲ ဂွံညးၜါဂှ်ရ။” (ဇ—၃၁၂။ အစွောံ။) = “(ထိုရဟန်းသည်) ထိုသားအဘတို့၏ လာခြင်းကိုမမြင်၍ မီးရှူးကိုင်လျက် ခရီးဦးကြို၍—။” (ညောင်ကန်) || ‘မိန်ရှောတဲၜံၚ်’ ဟုလည်းတွေ့ရသည်။ || “မိန်ရှောတဲၜံၚ်၊ လ္ၚဵုစံၚ်ဗျာံ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။)')
,(11511,3,4,'ဖေးမသည်။ ပွေ့ချီပို့ဆောင်သည်။','“သမ္ၚေဟ်မွဲဂှ် ကုသဵုကံမိန်သဘာ်ဏာ ပ္ဍဲဍုၚ်နက္ကဘဴ ဂွံဒှ်သၟိၚ်နာ်ရ။” (ဇ—ဝိဓုရ။ အစွောံ။) = “တစ်ယောက်သောသူကြွယ်သည် ကုသိုလ်ကံဖေးမပို့ဆောင်ပေး၍ နဂါးပြည်­ နဂါးမင်းဖြစ်ရ၏။”')
,(11512,3,10,'(န) စွန့်လှူခိုက်ဖြစ်ပေါ်သောစေတနာ။ မုဥ္စစေတနာ။','‘ပုဗ္ဗစေတနာ’၊ ‘အပရစေတနာ’ တို့လည်းရှု။')
,(11513,3,4,'တင်းကျပ်သည်။','“ဒက်လဝ်မောန်ဒၟံၚ်ရ။” = “ချည်ထားသည်မှာ တင်းကျပ်ခိုင်မြဲသည်။”')
,(11514,3,1,'အယူ။ အယူအစွဲ။ အယူဝါဒ။','အမာတ်မၞုံဝါဒဥစ္ဆေဒဂှ် “လိုက်ကီု ပလိုက်ကီု ဟၟဲရ” ဍေံဂးတုဲ ကွေတ်မပ်ဂှ် ဍေံကဵုညးဂိုၚ်ကေတ်ရ။ (ဇ—၅၂၈။ အစွောံ။) = ဥစ္ဆေဒဝါဒရှိသောအမတ်သည် “ပစ္စုပ္ပန်လောကသည်၄င်း တမလွန်လောကသည်၄င်း မရှိ” ဟုဆိုကာ ၄င်းအယူဝါဒကို သူတစ်ပါးတို့အား လက်ခံယူစေ၏။ || (လၟပ် = ကွေတ်။ တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။)')
,(11515,3,4,'၁။ ပျော်သည်။','“ဗ္တံဏအ် အဲဂွံအာပေဲါ အဲမိပ်ကွေံရ။” = “ဒီညကျွန်တော်ပွဲသွားရမည်ဖြစ်၍ ကျွန်တော်တကယ်ပျော်သည်။”')
,(11515,3,4,'၂။ နေကောင်းသည်။ ကျန်းမာသည်။','မံၚ်မိပ် =နေကောင်းသည်။ ကျန်းမာသည်။')
,(11515,3,4,'၃။ မြိန်သည်။','စပုၚ်မိပ် = ထမင်းစားမြိန်သည်။')
,(11516,3,3,'၁။ သာယာသော၊ နာပျော်ဖွယ်သော (အသံ) ။','“(သၟတ်ဗြဴဂှ်) နရမျှာၚ်ဍေံမမိပ်ဂှ်ဍေံဒယှ်ေတုဲ—။” (ဇ—၅ဝ၇။ အစွောံ။) = “ထိုသတို့သမီးသည် သာယာစွာသောအသံဖြင့် သီချင်းသီဆို၍—။” || “ပၞောဝ်ဂစေံပိဂှ် ဇမ္ဗုကမွဲဂှ် ရုပ်ဂေါဝ်ရမျှာၚ်မိပ်တုဲ ညးသ္ဍိုက်မၠိုက်ဂၠိုၚ်။” (ဇ—၅၂၁။ အစွောံ။) = “သုံးခုသောငှက်တို့အနက် ဇမ္ဗုကသည် ရုပ်အဆင်းလှ၍ အသံသာယာသ ဖြင့် လူအများပို၍ ချစ်နှစ်သက်ကုန်၏။” || “ယွံနာဲပိုဲတၠက္ၜၚ်တံ၊ သၟိၚ်ဂစေံဝွံဂှ် ဂေါဝ်ဆာဲလောန်က္ဍၚ်သန်၊ ဗြုမိပ်လောန်က္ဍၚ်သန်၊ သွံကဵုပိုဲညိရအဴ။” (ဇ—၃၃၉။ အစွောံ။) = “အရှင်သင်္ဘောသားတို့၊ ဤငှက်မင်းသည် အဆင်းအလွန်တင့်တယ်ပေစွ။ မြည်သံသာယာနာပျော်ဖွယ်ရှိစွ။ ငါတို့အား ရောင်းပါလော့။” || “နရမျှာၚ်မမိပ်ဂှ် ကျာ်အနုမောဒနာကဵုဥပးဂှ်ရ။” (ဇ—၄၄၂။ အစွောံ။) = “သာယာစွာသောအသံတော်ဖြင့် အနုမောဒနာပြုလိုသည်ဖြစ်၍—။” (ညောင်ကန်)')
,(11516,3,3,'၂။ ချိုမြိန်သော (အစာ) ။','“(သၟိၚ်ဇာဒိသိုၚ်ဂှ်) ရပ်ဂစိုတ်ပြေၚ်ဇၞော်မွဲ ဖျုန်မပြဲရှ်မမိပ်စတုဲ—။” (ဇ—၁၄၃။ အစွောံ။) = “ခြင်္သေ့မင်းသည် တစ်ခုသောကျွဲကြီးကို ဖမ်းသတ်ပြီးလျှင် မြတ်သောအရသာချိုမြိန်သောအသားကို စား၏။” || “သတ်ဇြဲသုံလၟုဟ်ဝွံဂှ် ဍေံမၞုံကဵုရှ် ဍေံမမိပ်လောန်—။” (ဇ—၃၃၄။ အစွောံ။) = “ဤပညောင်သီးအမှည့်သည် အလွန်ချိုမြိန်သော အရသာရှိ၏။”')
,(11517,3,4,'သာယာနာပျော်ဖွယ်ဖြစ်သည်။ နားဝၚ်ချိုသည်။',NULL)
,(11518,3,4,'ဝမ်းသာသည်။ ဝမ်းမြောက်သည်။','“ညးဗၠးအာနူယဲဂှ် အဲမိပ်စိုတ်ကွေံရ။” = “သူရောဂါပျောက်ကင်းသွားလို့ ငါတကယ်ဝမ်းသာမိပါတယ်။”')
,(11519,3,4,'စိတ်နှလုံးပျော်ရွှင်သည်။ ဝမ်းသာသည်။ ဝမ်းမြောက်သည်။','“ကောန်ဗြဴသၟိၚ်မိၚ်တုဲ မိပ်တဴစိုတ်စရိုတ် ဗွဲမလောန်ရ။” (ဇ—၁၂၆။ အစွောံ။) = “မင်းသမီးကြား၍ အလွန်ဝမ်းမြောက်၏။” || “ဂၞကျာ်သၠးဂဝ်ကောန်တြုံမွဲ ညံၚ်ထဝ်ကလောအ်က္တဵုဒှ် ဇန်ဂမၠိုၚ်မိပ်စိုတ်စရိုတ်ဗွဲမလောန်။” (ဇ—၁၅၆။ အစွောံ။) = “မိဖုယားသည် ရွှေတုံးကဲ့သို့သော သားယောကျာ်းတစ်ယောက်ကို ဖွားမြင်လေသော် လူများသည် အလွန်ဝမ်းသာပျော်ရွှင်ကြကုန်၏။”')
,(11520,3,4,'ဝမ်းမြောက်ဝမ်းသာဖြစ်သည်။ စိတ်နှလုံးပျော်ရွှင်သည်။',NULL)
,(11521,3,4,'၁။ ပျော်ရွှင်သည်။','“ညးတအ်ဝေၚ်သဘၚ် မိပ်ဇြိပ်ဒၟံၚ်အိုတ်ရ။” = “သူတို့ပွဲသဘင်ကစား၍ ပျော်ရွှင်နေကြသည်။” || “မိပ်ဇြိပ်ကီုဟာ၊ ဟွံမိပ်ခါဂှ်။” (လိက် ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ပျော်ရွှင်ပါသလား၊ ထိုအခါမပျော်။”')
,(11521,3,4,'၂။ ကျန်းမာသည်။ နေကောင်းသည်။','“ညးတအ်မံၚ်စမိပ်ဇြိပ်ဒၟံၚ်အိုတ်ရဟာ။” = “သူတို့တွေ နေကောင်းကြပါရဲ့လား။”')
,(11521,3,4,'၃။ သာယာနာပျော်ဖွယ်ဖြစ်သည်။','“ဂုတ္တိလသၟာတွိၚ်ဂှ် ယာံသ္ဂောံတိၚ်တုဲ ရှ်သာမိပ်ဇြိပ်လောန်။” (ဇ—၂၄၃။အစွောံ။) = “စောင်းသမားဂုတ္တိလ စောင်းတီးရသည်ရှိသော် အလွန်သာယာနာပျော်ဖွယ်ဖြစ်၏။”')
,(11522,3,4,'ပျော်ရွှင်သည်။ ရွှင်လန်းသည်။','“ယာပ်ယာတုဲကွေံ၊ ရှ်ဒိပ်ဍေံဖာပ်။ ကာယသုခ၊စိတ္တမိပ်မာပ်။ ဒဵုတၞုၚ်သော်၊ ရှ်ဗြော်ဗက်ဇာပ်။” (လိက်ဝိဓူရ) = “သူကျွေးမွေးသော နတ်သုဒ္ဓာအရသာကို သုံးဆောင်ရပြီးနောက် ကိုယ်ချမ်းသာ စိတ်ရွှင်လန်းကာ ဆံဖျားတိုင်အောင် အရသာသည် စိမ့်၍နှံ့သွား၏။” || “မိပ်မာပ်လောန်ဂၠိုၚ်၊ ဂြိုၚ်မံၚ်ဟာဟာ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ပျော်ရွှင်လွန်းကာ တဟားဟားရယ်မောသည်။”')
,(11523,3,4,'စိတ်ရွှင်လန်းသည်။',NULL)
,(11524,3,4,'ပျော်ရွှင်သည်။','“သီုၜါက္ဍိုၚ်ဗတာၚ်နွံသမာဓိ ရာၚ်ဆာဲမိပ်သ္ဇိပ် ဗွဲမလောန်သန်ဟေၚ်။” (အကြီုရာဇာဓိရာဇ်) = “နှစ်ပြည်ထောင်လုံး စိတ်အေးချမ်းခြင်းသမာဓိကိုရ၍ အလွန်လျှင် သာယာပျော်ရွှင်ကြကုန်၏။” || ‘မိပ်ဇြိပ်’ နှင့်အတူတူ။')
,(11525,3,4,'ပျော်ရွှင်သည်။ မွေ့လျော်ဖွယ်ဖြစ်သည်။ သာယာနာပျော်ဖွယ်ဖြစ်သည်။','“ဍေံဟီုဒေါန်လစောန်ရဏောန် မိပ်သ္ၚိပ်လောန်သန်သွံ။ မူဗရုဂှ်သ္ဂးရော။” (ဇ—၅ဝ၇။ အစွောံ။) =“သာယာစွာဆိုမြည်တမ်း၍ မွေ့လျော်နာပျော်ဖွယ်ရှိစွ။ အဘယ်မည်သောအသံပါနည်း။” || “ကြဴဝွံကဝ်တန်၊ မိပ်သ္ၚိပ်သန်ရ။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “နောၚ်ကမ္ဘာတည်၍ မွေ့လျော်ဖွယ်ဖြစ်၏။” || “သတြုဟွံမွဲ၊ ဝဳဝဲသ္ဍးဒဴ။ မိပ်သ္ၚိပ်သန်ရ၊ သၟိၚ်ပဒတဴ။” (လိက်ဗောဓိသတ်စှ်။ပဏ္ဍိတ။) = “ရန်သူမရှိ ရန်သူမှကင်းဝေး၍ မင်းသည် အလွန်ပျော်ရွှင်စွာနေထိုင်၏။” || “မိပ်သ္ၚိပ်ကွေံကြာန်၊ ဋ္ဌာန်နူဒတန်။ ပ္ဍဲဘာဂှ်သ္အး၊ လိက်ဝွံညးဆန်။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “အမှန်တကယ် ပျော်ရွှင်ဖွယ်ဖြစ်သော ထိုကျောင်းတည်ရာအရပ်­ ဤပျို့ကို စီကုံးစပ်ဆိုပါ၏။” || “မိပ်ဟိပ်အဵုဇိုတ်၊ ပ္ဍဲစိုတ်တော်ဆ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ပျော်ရွှင်ဝမ်းမြောက်လျက် စိတ်ထဲတွင်တွက်ဆဆင်ခြင်၏။” || “မိပ်ဟိပ်ရာၚ်ဆာဲ၊ ညံၚ်နာဲသွဝ်ၜါ။” (လိက်ကကၠာ်။ကောန်ဍး။)')
,(11526,3,4,'မှောက်သည်။','“ကောန်ၚာ်ဗှ်ေမိုပ်ဒှ်ရဟာ။” = “နင့်ကလေးမှောက်တတ်ပြီလား။” || သ္တိက်လက်မိုပ် = မှောက်လျက်အိပ်သည်။ || “(သေဋ္ဌဳဂှ်) ညးတိုက်ထနှိက် လောတ်မိုပ်ဒၟံၚ်—။” (ဇ—၇၈။ အစွောံ။) = “ထိုသူဋ္ဌေးကို လူများရိုက်နှက်ကန်ကျောက်၍ မှောက်လျက်လဲနေ၏။”')
,(11527,3,4,'ဝပ်စင်းသည်။ ဝပ်တွားခယသည်။','“အဲဒှ်သၟိၚ်ဝွံ၊ ပိုၚ်ဇမ္မုကိုပ်။ ကဵုအဲဖျေံက္ဍိုပ်၊ မိုပ်မာပၠန်ဟာ။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) = “ဇမ္ဗူဒိပ်ကိုပိုင်စိုးသော မင်းဖြစ်သောငါ့အားဦးချဝပ်စင်းစေဦးမည်လော။”')
,(11528,3,5,'ဝမ်းသာအယ်လဲဖြင့်။ (?)','“ညာတ်ကောကၠုၚ်စိုပ်၊ မိုပ်မိုပ်မာမာ။ မိပ်စိုတ်စရိုတ်၊ ဝိုတ်ထောံအဟာ။” (လိက်ဇိဝှစက္က) = “အစ်ကိုရောက်လာသည်ကိုမြင်သော် ဝမ်းသာအယ်လဲဖြင့် အလွန်ဝမ်းမြောက်သည်ဖြစ်၍ အစားအသောက်ကိုပင် မေ့သွားရ၏။”')
,(11529,3,1,'ယောကျာ်းလေး၏ အမည်ရှေ့တွင် တပ်ခေါ်သောစကား။ မောင်။ မင်း။','မာံအံၚ်မန် =မောင်အောင်မွန်။ မင်းအောင်မွန်။')
,(11530,3,1,'ရင်းပြားပင််။ (ဝန်းသောရွက်ဆိုင်ရှိ ဆေးဖက်ဝင်ပင်နိမ့်တစ်မျိုး။)',NULL)
,(11531,3,4,'(အစာကို) ပါးစောင်နှစ်ဖက်­ ပြည့်ဖောင်းအောင်ထားသည်။ (ပါဠိ—အဝဂဏ္ဍကာရက)','မေမ်စစၞ = ပလုတ်ပလောင်းစားသည်။ || “စပုၚ်မ္ဂး ဟွံဂပ်ဂဝ်မေမ်စရ။” = “ထမင်းစားလျှင် ပလုတ်ပလောင်းမစားသင့်။” || “အဝဂဏ္ဍကာရကံ၊ ပွမမေံပုၚ်ပ္ဍဲကၞိၚ် ညံၚ်ရဴကၞုဲမမေံသစ္ဆုဂှ်သ္ပတုဲ။” (ပြကိုဟ်ဒ္ဂေတ်ပဋိပတ်သာမဏဳ။ မာံရွှေငိုး။) = “မျောက်သည် သစ်သီးကို ပါးစောၚ်­ထားသကဲ့သို့ ထမင်းကို ပါးစောၚ်­ထားခြင်း။”')
,(11532,3,4,'သီချုပ်သည်။','မောမ်ထမန်ယာတ် = အဝတ်၏အနားကို သီချုပ်သည်။ || “သၞာဂဇအ်ကောမ်၊ မောမ်ညံၚ်ဟွံစာ်။” (ကောန်ဖေန်ကောန်ၛၚ်) = “ထိုၚ်စရာခင်းနှီးကို မစုတ်အောင်သီချုပ်သည်။”')
,(11533,3,1,'၁။ မဲပြား။ စာရေးတံမဲ။',NULL)
,(11533,3,1,'၂။ မဲနယ်။',NULL)
,(11533,3,1,'၃။ မြည်းသတ္တဝါ။',NULL)
,(11534,3,1,'မဲနယ်။',NULL)
,(11535,3,1,'မိုးမခပင်။','‘မၚ်ဂြာဲ’ ရှု။')
,(11536,3,1,'၁။ မာလောနွယ်။ ပြိတ်နွယ်။ (မှီရာအပၚ်ကို ဖျက်ဆီးတတ်သော ကျမ်းဂန်လာနားမထောင်ကြီးတစ်မျိုး။) (ပါဠိ—မာလုဝ)','“ညံၚ်ဇုက်မာဲလဴမဂွါန်ဆု ထဗိုၚ်ဗဒေါမ်ဆု၊ ဆုဂှ်ဟွံဒေါမ်ဇုက်မာဲလဴမဒးကှ်အာကီု။” (ဇ—၁၄၇။ အစွောံ။) = “သစ်ပင်ကိုလှဲရန် သစ်ပင်ပေါ်နွယ်တက်သော မာလောနွယ်ကဲ့သို့ သစ်ပင်ကမလဲဘဲ မာလောနွယ်သာ ခြောက်သွားရ၏။”')
,(11536,3,1,'၂။ အင်ပင်။ (နီညိုရောၚ်အခေါက်နှင့် ကြီးမားပြန့်ကားသောအရွက်ရှိသည့် ပၚ်စောက်ကြီးတစ်မျိုး။)','“ညးမသုန်မပ္တံကဵုအိန်ဂှ် — သၠမာဲလဴပ္ဍဲဂြိုပ်ဟေမဝန် တၟာဂဒူဂှ် ကေတ်နၚ်ရ။” (ဇ—၅၃၅။ အစွောံ။) =“သိကြားမင်းအစရှိသော ငါးယောက်ကုန်သောသူတို့သည် ဟိမဝန္တာတောမှ ဂဒူးပမာဏရှိအၚ်ရွက်ကို ဆောင်ခဲ့ကုန်၏။”')
,(11537,3,1,'မီးရှူး။ မြက်မီးရှူး။','‘(ဣသိ) ပ္ဍေန်မာဲသော—။’ (ဇ—၆၃။ အစွောံ။) =‘ရသေ့သည် မြက်မီးရှူးကို ထွန်းညှိသည်။’ || “(ဗောဓိသတ်) ရံၚ်ညးၜါဟွံစိုပ် တ္ၚဲဂၠုအာတုဲ ပ္ဍေန်မာဲရှောတုဲ ဒစးကၠုၚ်ဂွံညးၜါတုဲ—။” (ဇ—၃၁၂။ အစွောံ။) = “ဘုရားလောင်းသည် ထိုသူနှစ်ဦးတို့ မရောက်လာသည်ရှိသော် မိုးချုပ်မှောင်သွားပြီဖြစ်သဖြင့် မီးရှူးကိုထွန်း၍ လိုက်လာရာ ထိုသူနှစ်ဦးတို့ကိုတွေ့၏။” || ‘မိန်ရှော’ နှင့်အတူတူ။')
,(11538,3,1,'၁။ ပိုးလက်ကိုင်ပုဝါ။ ပိုးထည်။','“မာဲသုတ်ဗကေတ်ဒက်ဂၞဴ။” (ဇ—ဝိဓုရ။ အစွောံ။) || “မၞိဟ်တ္ၚီုဒးစိၚ်တရာဗညာဂှ် လာဘ်သကာတၠညးကဵုဟွံဂတာပ် မာဲသုတ်မွဲပ္ဍဲသၟိၚ်မဇိုတ်မုက်သၟိၚ်ဗိုတ်ကဵု။” (အကြီုရာဇာဓိရာဇ်) = “တရဖျား၏ဆင်ကို ထိုးနှက်လိုက်သောသူကို ဘုရင်သည် ဆုလာဘ်ပေးမခၚ်၍ မျက်နှာသုတ်သော ပိုးလက်ကိုင်ပုဝါကို ပစ်ပေး၏။”')
,(11538,3,1,'၂။ မွန်လူမျိုးများ လက်ထပ်သောအခါ လူကြီးများအားဝေငှရန် ပိုးပုဝါဖြင့်ဖုံးထားသော ဆေးလိပ်၊ ကွမ်းသီးစသည် ထုပ်ထားသောအထုပ်။ (= တၟာဲသုတ်?)',NULL)
,(11539,3,1,'ပုဆိန်။',NULL)
,(11540,3,4,'ရနံ့မွှေးသည်။','“မူရဴမြမဝ်မွဲ မမောဝ်လောန်ပ္ဍဲလိုက်ကီု ပ္ဍဲပလိုက်လေကီု ဟီုကဵုအဲညိရမရှာတ်။” (သၠပတ်ဂတာံထဝ်) = “မင်းမြတ်၊ အဘယ်အမွှေးနံ့သာသည် လောက­၄င်း တမလွန်လောက­၄င်း အလွန်မွှေးသည်ကို အကျွန်ုပ်အား ပြောကြားပါလော့။”')
,(11541,3,4,'၁။ တိုးများသည်။ တိုးပွားသည်။','“နူအယုက်သတ်တံမဒှ်စှ်သၞာံဂှ် ကၠံသၞာံမွဲသၞာံမောဝ်တိုန်အာ ဒဵုကဵုစိုပ်အယုက်သတ်တံ မွဲအသၚ်ဃဲ။” (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “သတ္တဝါများ၏သက်တမ်းသည် ဆယ်နှစ်သက်တမ်းမှ အနှစ်တစ်ရာလျှင် တစ်နှစ်တိုးများလာပြီး သက်တမ်းတစ်သင်္ချေသို့ရောက်၏။” || “ကဵု (ဣသိ) စံၚ်ပူဇဴသတ်ဇိုၚ်ပန်တုဲ အယုက်မရာတ်မဝ်တိုန်အာညံၚ်အယုက်အဲဣန်ကီုရ” ဣန်ဂး။ (ဇ—၄၃၃။ အစွောံ။) = “မင်းမြတ်၊ သင်သည် ရသေ့အားအခြေလေးချောင်းသတ္တဝါတို့ကို ယဇ်ပူဇော်စေသည်ရှိသော် သင်မင်းမြတ်၏အသက်သည် ငါသိကြားမင်း၏အသက်ကဲ့သို့ တိုးများတက်လာလတ္တံ့။”')
,(11541,3,4,'၂။ (သင်္ချာ) မြှောက်သည်။','“(၆) မောဝ်ကဵု (၅) မ္ဂး ဂွံ (၃ဝ) ရ။” = “(၆) ကို (၅) နှင့်မြှောက်လျှင် (၃ဝ) ရရှိသည်။” || ‘ပၟဝ်’ (ကြိ) လည်းရှု။')
,(11542,3,4,'မွှေးကြိုင်သည်။','“(ပ္ကဴဂှ်) ဂိုၚ်ပ္ဍးတမာဲ၊ အမြာဲမောဝ်ဇောဝ်။” (လိက်ဝိဓူရ) =“ထိုပန်းသည် ရနံ့သင်းပျံ့မွှေးကြိုင်၏။”')
,(11543,3,4,'မွှေးကြိုင်သည်။ သင်းပျံ့သည်။','“မောဝ်တမာဲတဴ၊ ရဴကြက်စလန်။” (လိက်မၚ်ဗၠာဲသ္ၚိတူ) = “စန္ဒကူးနံ့သာကဲ့သို့ မွှေးကြိုင်၏။” || “စလှန်ဒိပ်ဆာဲ၊ မောဝ်တမာဲပြဟ်။” (လိက်ရတနပဇ္ဇောတ) = “နတ်စန္ဒကူးနံ့သာသည် လျင်မြန်စွာသင်းပျံ့သွား၏။”')
,(11544,3,4,'မွှေးကြိုင်သည်။ ထုံသင်းသည်။','“သီုရုပ်လေဝ်ဂေါဝ်၊ ဇကုမောဝ်ထီု။” (လိက်သောဝါနနဟောၚ်) = “ရုပ်လည်းလှပ၍ ကိုယ်လည်းမွှေးကြိုင်၏။”')
,(11545,3,4,'ကြိုင်သင်းသည်။ ကြိုင်လှိုင်သည်။','“ဒေဝတဴပန်ဂှ် စရှ်ပ္ကဴဒိပ်ကက္ကာရုဂှ်တုဲ မောဝ်ပ္ဍးအာအလုံဍုၚ်ရ။” (ဇ—၃၂၆။ အစွောံ။) = “နတ်သားလေးယောက်တို့သည် ကက္ကာရုနတ်ပန်းကို ပန်ဆင်ကုန်၍ မြို့အလုံးသည် တစ်စပ်တည်း မွှေးပျံ့ကြိုင်လှိုင်နေ၏။”')
,(11546,3,4,'မွှေးကြိုင်သည်။','“ကြုက်ထဝ်သိၚ်ဃဵု၊ ဍုဟ်ဂဵုမောဝ်မာ။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “သရက်သီးသီဟိုဠ်သီးတို့သည် မှည့်ဝင်းမွှေးကြိုင်နေကုန်၏။”')
,(11547,3,5,'ကြည်ကြည်သာသာ။ ညင်ညင်သာသာ။','“ပရာန်တုဲ လက်ဒေါန်ဒလောံဗ္တောန်ကဵုဒှ်၊ ဒလောံဗ္တောန်မောဝ်ဝ်သာသာကဵုဒှ်။” (ပြကိုဟ်မ္ၚိုလ်ပိစှ်ောဒစာံ) = “ကြိမ်းမောင်းဆဲဆို၍ ဆုံးမသည်ဖြစ်စေ၊ ကြည်ကြည်သာသာဆုံးမသည်ဖြစ်စေ။”')
,(11548,3,4,'မွှေးကြိုင်သည်။','“ပ္ကဴကြက်စလန်၊ ဂဒအ်ညန်ကြံၚ်။ ပၠးထာၚ်မောဝ်လှောင်၊တ္ၜူလှောင်ထိုၚ်သာဲ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “စန္ဒကူးနံ့သာပန်းသည် အဖူးရင့်လုနီး၍ပွင့်ချပ်ကိုဖွင့်ကာ မွှေးကြိုင်လှ၍ ပျားပိတုန်းတို့ကို ညှို့ယူယစ်မူးစေ၏။” || “လစသြိုဟ်ဂှ်၊ ဒကှ်ၜါဍောၚ်။ ရာၚ်တမိုဟ်ဆာဲ၊ အမြာဲမောဝ်လှောင်။” (လိက်သောဝါနနဟောၚ်) = “ရင်ဘတ်တည်းဟူသောအိုၚ်­ ပဒုမ္မာကြာနှစ်ပွင့်တို့သည် မိုမောက်တင့်တယ်စွာပွင့်လန်း၍ ရနံ့မွှေးကြိုင်နေ၏။”')
,(11549,3,3,'၁။ မောက်မာသော။ ရိုင်းပျသော။ ရင့်သီးသော။ ပြင်းထန်သော။','“(ဍိက်မ္ဂးဂှ်) ဒုဟ်တၠမပ္တံပါၚ်မသ္ကာတ် ပွမမဵုဂှ် လ္ပသ္ၚဳ။ ဂုန်တၠမပ္တံပုၚ်ဂၞဴ၊ ဗွိုက်လတက်၊ သ္ၚိဒၟံၚ်—ဂှ်ဟေၚ် သ္ၚဳညိ။” (ဇ—၁၃၁။ အစွောံ။) = “ကျွန်မည်သည်ကား နှုတ်ကြမ်းခြင်း အပြုအမူရင့်သီးခြင်းစသော သခင်၏အပြစ်ကိုမရှုမူ၍ သခင်ကပေးကမ်းသော ဝမ်းစာ၊ အဝတ်အထည်၊ အိမ်ရာစသော သခင်၏ကျေးဇူးကိုသာ ရှုပါလေ။” || “(အဲ) မလက်လဝ် နဂလာန်မမဵုဂှ် အဲအာတ်မၞးတံ သၠးဒုဟ်ကဵုအဲရ၊ အေၚ်ဒုၚ်ဒုဟ်ကဵုအဲညိရ။” (အကြီုရာဇာဓိရာဇ်) = “မောက်မာရင့်သီးသောစကားဖြင့် သင်တို့အား ငါဆဲဆိုထားသည်များကို ငါ့အား အပြစ်လွှတ်သည်းခံကြပါရန် ငါတောင်းခံပါ၏။” || “ကာလသတ်တံ အယုက်မအောန်လောန်နူကၠံသၞာံဂှ် ကိလေသသတီု ကိလေသမမဵု ဓဝ်ကိလေသဂၠိုၚ်လောန်။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “လူ့သက်တမ်းအနှစ်တစ်ရာအောက် နိမ့်သောကာလ­ လူတို့သည်ကိလေသာထူပြော၏။ ကိလေသာပြင်းထန်၏။ ကိလေသာတရားများလွန်း၏။”')
,(11549,3,3,'၂။ မာကျောသော။ ကြမ်းသော။','ယာတ်မမဵု = မာကြမ်းသောအဝတ်။ || ‘ရုန်မဵု’ (နဝိ) လည်းရှု။')
,(11550,3,3,'၁။ မောက်မာသော။ ရိုင်းပျသော။ ရင့်သီးသော။','“ဂလာန်ဗှ်ေမဟီုဝွံ ဒှ်မမဵုရုန်ကဵုညးဇမၞော်။” (အကြီုရာဇာဓိရာဇ်) = “နင်ပြောသောစကားသည် ကြီးသူကိုရိုင်းပျရာကျသည်။” || “ပွမဟွံဂွံဟီုဂးဂလာန်မိုဝ်ရုန်သ္ကာတ်မြဟ်ကြံကြ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “မောက်မာရင့်သီးရုန့်ရင်းသောစကားကို မပြောဆိုခြင်း။” || “လၟုဟ်ကောန်မၞုဿမွဲ နွံဒၟံၚ်ပ္ဍဲကဵုဥဒျာန်တေံဂှ်မဵုရုန်ကြံကြညိညဟွံသေၚ်။” (သၠပတ်စန္ဒဝတဳ) = “ယခုထိုဥယျာဉ်­ရှိသော တစ်ယောက်သောလူသားသည် နည်းနည်းနောနော ရင့်သီးဆိုးသွမ်းသည်မဟုတ်။” || “ဍေံမိၚ်တုဲဍေံပၞတ် ဂလာန်ဍေံမဵုရုန်အာ။” (အာန်ဇုနာန်) = “သူကြားပြီး သူအမျက်ထွက်၍ သူ့စကားရင့်သီးသွား၏။”')
,(11550,3,3,'၂။ ကြမ်းသော။ မာကျောသော။','“လးသၞာဟွံမိုဝ်ရုန် ဖုန်၊ ထဍဳ၊ ဒၞဳ၊ ထကဝ်၊ ကၟဝ်၊ ခဴဇဴ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “မမာကျောသောအခင်းအနှီးဖြစ်ကုန်သော မွေ့ရာ၊ ဖုံ၊ ခေါင်းအုံး၊ဖျာ၊ ကမ္ဗလာ၊ ကော်ဇော အစရှိသည်တို့ကိုခင်း၍—။”')
,(11550,3,3,'၃။ (ဝေဒနာ) ပြင်းထန်သော။ နှိပ်စက်တတ်သော။','“တြုံမှာအသဝ်၊ ကျာ်ဗွဝ်ဂုန်။ ယဲဂၞဴမဵုရုန်၊ ဖဍုန်ဒုက္ခ။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “အံ့ဖွယ်မဟာယောကျာ်းမြတ်ဖြစ်သော ဂုဏ်ကျေးဇူးနှင့်ပြည့်စုံသော မြတ်စွာဘုရားကိုပင်လည်းဝမ်းတော်လားသောရောဂါသည် ပြင်းထန်စွာနှိပ်စက်၍ ဒုက္ခပေးသေး၏။” || ‘ရုန်မဵု’ နှင့်အတူတူ။')
,(11551,3,1,'အချွန်။','မှ်ဗနောတ် = စူးအချွန်။')
,(11552,3,1,'မဲနယ်။',NULL)
,(11553,3,11,'(န) မိဿရာသီ။',NULL)
,(11554,3,1,'တစ်မိုက်အတိုင်းအတာ။ (ခြောက်လက်မ)',NULL)
,(11555,3,1,'ကြေး။ ကြေးညှော်။','“ဟုံဍာ်မ္ဂး တုဟ်မိဟ်ကဵုသ္အးညိ။” = “ရေချိုးလျှင်ကြေးစၚ်အောင် ကြေးတွန်းပါ။” || “ဂွံတုဲနၚ်ပြဟ်၊ ဂၟိဟ်ဂှ်အဆတ်။ အဲမာန်ရုပ်ကၠာ၊ ကညာဂေါဝ်တ္ၜတ်။” (လိက်မၚ်ဗၠာဲဟောံလွဳ) = “ထိုကြေးကိုရပြီးလျှင် အမြန်ယူလာကာ လှပနုပျိုသောကညာရုပ်ကို ငါကိုင်တွယ်ပုံသွင်းပြုလုပ်၏။” || “ဂၟိဟ်ဇကုဂှ်၊ တုဟ်ပေါတ်တုဲစိ။ ဂွံမွဲပသာ၊ကေတ်ဏာဒမၠိ။” (လိက်မၚ်ဗၠာဲဟောံလွဳ) = “မိမိ၏ကြေးကို ပွတ်တွန်း၍ တစ်ပိဿာရသည်ကိုမြဲစွာယူသွား၏။”')
,(11556,3,1,'၁။ လုံခွက်။ (ရွှေ၊ ငွေ၊ သတ္တုစသည်ကို အရည်ကျိုရန် မြေစေးနှင့်ပြုလုပ်ထားသောမီးခံခွက်။)','“ရုပ်သာ်သၟိၚ်ဒြာဲထဝ်ဂှ် ပတၠသော်ဇကုဗကေတ်တဴ ရဴသာ်ထဝ်သိၚ်ဃနိက် ညးမချူလဝ် ပ္ဍဲကဵုပါၚ်မိဟ်ဂှ်ကီုရအဴ။” (သၠပတ်ဗြဟ္မဒတ္တ ဂၞကျာ်ခေမာဝတဳ) = “ရွှေသမင်မင်း၏ရုပ်အဆင်းသည် လုံခွက်အဝ­ သွေးထားအပ်သော သိၚ်္ဂနိက်ရွှေအဆင်းကဲ့သို့ဖြစ်၏။”')
,(11556,3,1,'၂။ ရွှေကျင်သောမိုက်ခွက်။ (= ခရော်မိဟ်)',NULL)
,(11557,3,1,'၁။ နှာခေါင်း။',NULL)
,(11557,3,1,'၂။ အစွန်း။ အစွန်အဖျား။','မုဟ်သၞာ် = သံလျက်အစွန်းအသွား။')
,(11558,3,1,'ဆောင်းရာသီ။',NULL)
,(11559,3,4,'(အအေးမိနှာစေး၍) နှာခေါင်းပိတ်သည်။',NULL)
,(11560,3,1,'အၚူ။',NULL)
,(11561,3,1,'ရင်။ ရင်ညွန့်။ အရှိုက်။','“(ကၞုဲဒမၠာန်ဂှ် တိုန်အာစးပြေၚ်ဒမြိုဟ်ဂှ်) ပြေၚ်ဂှ်ဂရိုက်ပ္တုံကၠေံကၞုဲဂှ် ပ္ဍဲတိတုဲ နကဵုဒြၚ်သွာၚ်တက် ဒးမုဟ်ဂြိုဟ်တုဲ — ကၞုဲဂှ်ပကာဂစိုတ်ရ။” (ဇ—၂၇၈။အစွောံ။) = “ထိုလျှပ်ပေါ်သောမျောက်သည် ထိုကျွဲဆိုး၏ကျောပေါ်သို့တက်ရာ ကျွဲသည် မျောက်ကိုခါ၍ မြေ­ကျစေလျက် ဦးချိုဖြင့် ရင်လွှဲရိုက်ခတ်၍ ထိုမျောက်သည်သေ၏။” || “သၟိၚ်ကလာဗုဂှ် ထနိက်စုတ်မုဟ်ဂြိုဟ်ရသိတုဲ သ္ဍးအာကၠေံရ။” (ဇ—၃၁၃။ အစွောံ။) = “(ကလာဗုမင်းသည်) ဘုရားလောင်း (ရသေ့) ၏ရၚ်ကို ခြေဖြင့်ကျောက်၍ သွား၏။” (ညောင်ကန်) || “လၟသောနုတ္တရဂှ်ဟိုတ်ပန်ဒးမုဟ်ဂြိုဟ်ဂှ် မှဆဒ္ဒန်မဒးပကာဂစိုတ်။” (ဓမ္မသာတ်။ MDT VII) = “သောနုတ္တရမုဆိုးက ရၚ်ညွန့်ကို ပစ်ခတ်ထိမှန်၍ ဆဒ္ဒန်ဆင်မင်းသေရ၏။”')
,(11562,3,1,'အစွန်အဖျားအရပ်ဒေသ။ လူသူမှဝေးသောအရပ်။',NULL)
,(11563,3,1,'‘ထော်’ တွင်ရှု။',NULL)
,(11564,3,4,'နှုတ်ရဲသည်။ နှုတ်ကြမ်းသည်။','“မၞိဟ်မုဟ်ပါၚ်ဂံၚ်၊ ဟီုဂၠံၚ်ရောဒး။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “နည်းလမ်းမကျပြောဆိုသော နှုတ်ရဲနှုတ်ကြမ်းသောလူ။”')
,(11565,3,1,'တိုင်းပြည်၏အစွန်အဖျားဒေသ။','ကွာန်မုဟ်ရး = တိုင်းစွန်ရွာ။')
,(11566,3,1,'အစွန်အဖျား။ အစွန်းအဖျား။','မုဟ်လအိတ်မွဲလ္ပာ် = တစ်ဖက်စွန်း။ || “ဗမၞး ပြာပ်အာပ္ဍဲဇရေၚ်ညးဂမၠိုၚ်တုဲ — ဂ္ဇံဒၟံၚ်ပ္ဍဲမုဟ်လ္အိတ်ညးဂမၠိုၚ်ဂှ်ရ။” (ဇ—၄ဝ၂။ အစွောံ။) =“ပုဏ္ဏားသည် လူပရိသတ်ရှိရာသို့သွား၍ ပရိသတ်အစွန်­ ထိုင်နေ၏။”')
,(11567,3,1,'‘မုဟ်’ ရှု။',NULL)
,(11568,3,4,'ကြုံတွေ့သည်။','မအ်ဘဲသတြု = ဘေးရန်ကြုံတွေ့သည်။ || “မဒးမအ်ဘဲ၊ သ္ကန်ဒဲလသာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ဘေးတွေ့၍ သေဆုံးရ၏။”')
,(11569,3,4,'၁။ ရိုသေဆည်းကပ်သည်။ ရိုသေလေးမြတ်သည်။','မအ်ဂြအ်ကျာ်ဓဝ်သၚ်။= ဘုရားတရားသံဃာကို ရိုသေဆည်းကပ်သည်။ || “ဖာဲပ္ကဴဝွံတုန်၊ သ္ၚာမသုန်သွဝ်။ ဗြိုမ်တအ်မအ်ဂြအ်၊ သဳကၠဳဇအ်သဝ်။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “ကြာငါးပွင့်­ သင်္ကန်းလျာငါးစုံကိုဗြဟ္မာတို့က အရိုအသေအလေးအမြတ်ပြုထားကြကုန်၏။” || “ဖဵုဂွံမအ်ဂြအ်၊ ကလအ်ရဴဂဴ။ ပကဵုဒးဒဒိုက်၊ ပရိုက်ဥပ္ပဒြဴ။” (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “ရိုသေစွာဆည်းကပ်ကန်တော့ရသော အကျိုးအားကြောင့် ဘေးမသီရန်မခပါစေနှင့်။” || “သၟိက်ဂွံမအ်ဂြအ်၊ ကလအ်မိမၜါ။” (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “မိဘနှစ်ပါးကို ရိုသေဆည်းကပ်ကန်တော့လို၏။”')
,(11569,3,4,'၂။နှစ်သက်လိုလားသည်။ ဝမ်းမြောက်လိုလားသည်။','“(ညံၚ်ကောန်ၜိုပ်ထဝ်) ညာတ်ၝောံပဝ်စဴဗက်တက်သၞေၚ်ဒစေၚ်ကအ် မအ်ဂြအ်ဝါၚ်ဒုၚ်ၝောံကီု။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ရွှေဟင်္သာသားငယ်သည် ပျံသန်းပြန်ရောက်လာသော မိခင်ကိုမြင်သည်နှင့် တောင်ပံကိုခတ် လည်ကိုစောင်း၍ဝမ်းမြောက်လိုလားစွာ မိခင်မကြီးကို ကြိုဆိုသကဲ့သို့။” || “တေံကောန်ဒြာဲတေံ ညာတ်ၝောံစဴနူဂြိုပ် ပၚ်က္ဍိုပ် လယှ်ဇိုၚ် ပကိုင်ဗတ ဂဒိုၚ်သၠကတောဝ် တယောဝ်ကအ် မအ်ဂြအ်ထဒၟကၠုၚ် ဝါၚ်ဒုၚ်ၝောံကီု။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “သမင်သားငယ်သည် တောမှပြန်လာသော မိခင်သမင်မကြီးကို မြင်သည်ရှိသော် ခေါင်းကိုပင့် ခြေကိုခါ အမြီးကိုထောၚ် နားရွက်ကိုကား လည်ကိုဆန့်လျက် နှစ်သက်ဝမ်းမြောက်လိုလားစွာ မိခင်အား လာ၍ကြိုဆို၏။”')
,(11570,3,4,'ကူညီသည်။ မစသည်။ စောၚ်မသည်။','“ယဝ်အဲဂွံပြာပ်အာ သ္ၚိမဟာဒိုက်ဂတ်တုဲ ဂွံပ္တုဲကေၚ်ကာဖျိန်ပုၚ်ဖျိန်သွ ဂွံဗိုၚ်ကၠောန်ရီုဗၚ်မအ်ဇအ်မ္ဂး ခိုဟ်သန်ရ” သၟိၚ်ဣန်ချပ်။ (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “ဤသူဆင်းရဲအိမ်သို့ ငါသွားရောက်၍ ထမင်းဟင်းချက်သောအမှု­ဝိုင်းကူလုပ်ကိုင်မစရသော် ကောင်းလေစွ” ဟုသိကြားမင်းကြံ၏။')
,(11571,3,1,'ခံတပ်။',NULL)
,(11572,3,1,'အမည်မဖော်နိုင်သော တောသစ်သီးတစ်မျိုး။','“သစ္ဆုမပ္တံကဵုသတ်မုက်၊ သတ်ဗၠတ်၊ သတ်ဣဥူ၊ မ္ၚူ၊ မ္ၚ၊ သတ်ဗၚ်ယ၊ သတ်ချ—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) || “သတ်မုက်၊ သတ်ဗၠတ်၊ဣဥူ၊ မၚူ၊ ဗၚ်ယ—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။)')
,(11573,3,6,'အပြင်။ အပ။','မ္ၚးသ္ၚိ = အိမ်အပြင်။ || ပရေၚ်ပညာမ္ၚးဘာ = ကျောင်းပြင်ပပညာရေး။ || “မၚ်ဗၠာဲဂှ် — တိတ်အာမ္ၚးဍုၚ်ရ။” (ဇ—၃၇၇။ အစွောံ။) = “လုလင်သည် မြို့ပြၚ်သို့ထွက်သွား၏။”')
,(11574,3,3,'ရာသီအချိန်မဟုတ်သော။ ရာသီအချိန်ပြင်ပဖြစ်သော။','“တၞံကြုက်သ္ၚိပိုဲ သတ်ဒၟံၚ်သီုပ္ဍဲကာလ သီုမ္ၚးကာလရ။” = “ကျွန်တော်တို့အိမ်မှ သရက်ပၚ်သည် ရာသီချိန်တွင်ရော ရာသီချိန်ပြင်ပတွင်ရော အသီးသီးသည်။”')
,(11575,3,3,'လက်ခံနိုင်ဖွယ်အမူအကျင့်မှအပဖြစ်သော။ လက်ခံနိုင်ဖွယ်အမူအကျင့်မဟုတ်သော။','“မူယြဴဂး၊ တြုံမ္ၚးဂြန်။” (လိက်သောဝါနနဟောၚ်) = “လက်ခံနိုင်ဖွယ်အမူအကျင့်မရှိသော အဘယ်မည်သောယောကျာ်းနည်း။” || “သၠေအ်ကေတ်ဒြပ်ညး၊ မ္ၚးနူဂြန်။” (လိက်လက္ခဏပိ) = “လက်ခံနိုင်ဖွယ်အမူအကျင့်မဟုတ်ဘဲ သူတစ်ပါးဥစ္စာကို လှည့်ပတ်ဖြားယောင်းယူခြင်း။” || “လှေအ်ကေတ်ဒြပ်ညး၊ မ္ၚးနူဂြန်။ ဒးနရက်ကၠာ၊ စှ်ၜါကဝ်ပ္တန်။” (လိက်ကာလထေ)')
,(11576,3,5,'စိတ်၏ပြင်ပ။ မသိစေပဲ။','“မ္ၚးစိုတ်ညး လ္ပကေတ်ဒြပ်ညးညိ။” = “ပိုင်ရှင်မသိစေဘဲ (ပိုင်ရှင်၏စိတ်ပြင်ပတွင်) သူတစ်ပါး၏ဥစ္စာကို မယူပါနှင့်။”')
,(11577,3,6,'မှတစ်ပါး။','“မ္ၚးနူအဲတုဲ ဇၟာပ်မၞိဟ်အာပေဲါအိုတ်ရ။” =“ငါမှတစ်ပါး လူတိုင်းပွဲသွားကြသည်။” || “မ္ၚးနူဖျုန်ဂၠဴ အဲစဖအိုတ်ရ။” = “အမဲသားမှတစ်ပါး ကျွန်တော်အကုန်စားသည်။”')
,(11578,3,5,'မျက်ကွယ်တွင်။ ကွယ်ရာတွင်။','“သမ္ဘာမပြဲမ္ဂးဂှ် ဒြပ်တၠသ္ၚိမဂၠာဲဂွံနၚ်ဂှ် ဟွံရပ်စပ်ပၠေၚ်ထောံကၠေံ မ္ၚးမတ်တၠသ္ၚိရ။” = “မြတ်သောမယားမည်သည် လင်ယောကျ်ား လုပ်ကိုင်ရှာဖွေ၍ ရလာသောဥစ္စာကို လင်ယောကျ်ား၏မျက်ကွယ်တွင် သုံးဖြုန်းပစ်ခြင်းမပြုပါ။” || “မ္ၚးစိုတ်ညး၊ မ္ၚးမတ်ကၠာ။ ကၠတ်ထဝ်သြန်ကီု၊ သီုကောန်သမ္ဘာ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။)')
,(11579,3,1,'သာသနာပ။ မြတ်စွာဘုရား၏ သာသနာတော်မရှိသောကာလ။','ခမဳမ္ၚးသာသနာ= သာသနာပရဟန်း။ || “ၜိုန်ကျာ်တြဲဟွံက္တဵုဒှ်ကီု ၜိုန်ဒှ်တဴမ္ၚးသာသနာဂှ်ကီုလေဝ် ပခမဳတုဲ—။” (ဇ—၄ဝ၃။ အစွောံ။) = “မြတ်စွာဘုရားမပွင့်သော်လည်း သာသနာပ­ဖြစ်သော်လည်း ရဟန်းပြု၍—။')
,(11580,3,3,'ခန္ဓာ၏ပြင်ပဖြစ်သော။',NULL)
,(11581,3,11,'(န) မင်္ဂလာ။','‘မ္ၚဵုရအဴ’ = ‘မင်္ဂလာပါရှင်/ခင်ဗျား။’ || မ္ၚဵုထပ်တဲ၊ မ္ၚဵုသၞက်ကရောဲ= လက်ထပ်မင်္ဂလာ။ || မ္ၚဵုတိုန်သ္ၚိ = အိမ်တက်မင်္ဂလာ။ || မ္ၚဵုစဝ်ကပေါဝ် = ကၚ်ပွန်းတပ်မင်္ဂလာ || မ္ၚဵုပထပိုဲခမဳ = ရှင်ပြုရဟန်းခံမင်္ဂလာ။ || မ္ၚဵုပိစှ်ောဒစာံ = (မြတ်စွာဘုရားဟောကြားတော်မူသော) သုံးဆယ့်ရှစ်ဖြာသောမင်္ဂလာ။')
,(11582,3,4,'နှိုးသည်။',NULL)
,(11583,3,4,'စိတ်ကိုနှိုးဆော်သည်။','“ကျာ်ဇၞော်အစွောံ ကာလအာယုက်ဂွံပေၚ် (၈ဝ) ဂှ် မ္ၚုဟ်စိုတ်တုဲ ပလွဳစဳရေၚ်ခၞံဗဒှ်လဝ် ဇာတ်မသုန်ကၠံမသုန်စှ်ော ဗွဲဘာသာမန်ရ။” = “ဝေါဆရာတော်သည် သက်တော် (၈ဝ) ပြည့်သောကာလတွင် စိတ်ကိုနှိုးဆော်၍ မွန်ဘာသာဇာတ်ငါးရာငါးဆယ်ကို အားထုတ်စီရင်ပြုစုခဲ့သည်။”')
,(11584,3,4,'‘မ္ၚိုဟ်ထဍိုဟ်’ ရှု။',NULL)
,(11585,3,16,'မာသည်။—သော။','“ပုၚ်ဏအ်မ္ၚိုဟ်ကွေံကွေံရ။” = “ဤထမင်းသည် အလွန်မာသည်။” || “ကောန်ညးဒိုက်ခၞံၚ် သ္ၚုကဆံၚ်လ္ပမ္ၚိုဟ်။” = “သူဆင်းရဲသည် ဆန်ကြမ်းကိုမာသည်ဟု မရေရွတ်ပါလေနှင့်။”')
,(11586,3,16,'မာကျောသည်။—သော။ မာကြမ်းသည်။—သော။ ကြမ်းတမ်းသည်။—သော။','“ဂလာန်မမ္ၚိုဟ်ကြံၚ်ဂှ် လ္ပဟီုညိ။” = “မာကျောသောစကားကို မပြောပါနှင့်။” || “ပူဂဵုသမၠီု၊ လဟီုမ္ၚိုဟ်ကြံၚ်။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “သူမိုက်သည်အပြောအဆို မာကျောကြမ်းတမ်း၏။” || “သမၠီုသဒိုဟ်၊ စိုတ်မ္ၚိုဟ်ကြံၚ်။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “မိုက်မဲသောလူ့ဗာလသည် စိတ်ခက်ထန်ကြမ်းတမ်း၏။”')
,(11587,3,4,'မာကျောသည်။ မောက်မာသည်။','“ဂလာန်ဟွံခိုဟ် မ္ၚိုဟ်ခဏံၚ်ကြံၚ်သ္ကာတ်ဂှ်လ္ပဟီုညိ။” (ဇ—၈၈။ အစွောံ။) = “မာကျောကြမ်းတမ်းသော မကောင်းသောစကားကို မဆိုရာ။” || “မ္ၚိုဟ်ခၞံၚ်ကၠာ၊ ဟွံညှာဒည။ လဟီုကြံသ္ကာတ်၊ သေသာတ်က္ဍၚ်ပြ။” (လိက်ကောန်သၟိၚ်ပိ။မာံခစုန်အံက်။) = “မာကျောမောက်မာ မညှာမရွံ့ ကြမ်းတမ်းသောစကားကို အခိုၚ်အမာပြောဆို၏။”')
,(11588,3,4,'၁။ ကြမ်းကြုတ်သည်။ ရုန့်ရင်းသည်။ ရက်စက်သည်။ ခက်ထန်သည်။','“ယွံနာဲပိုဲတံ၊ အင်္ဂုလိမာ ၜိုန်မဒှ်ကမၠတ်မ္ၚိုဟ်ထဍိုဟ် ဆီတဍေက်ဒၟံၚ်ပ္ဍဲတဲကီုလေဝ် ကျာ်တြဲပိုဲဂှ် နတဲသၟး ဟွံမွဲကဵုလွဟ်မွဲသာ်တုဲ မဂွံဝေတ်ကၠေံအင်္ဂုလိမာဂှ် အံသဝ်လောန်ကွေံရ။” (ဇ—၅၃၇။ အစွောံ။) = “ငါ့ရှင်တို့၊ သဗ္ဗညုဘုရားသခင်သည် ရုန့်ရင်းကြမ်းကြုတ်စွာသော လက်­သွေးစွန်းသော ခိုးသူကြီးဖြစ်သော အင်္ဂုလိမာလကိုစၚ်လျက် လက်နက်ကိုင်စွဲတော်မမူဘဲ ဆုံးမတော်မူသည်မှာ သြော်အံ့ဖွယ်ရှိစွ။” || “ယွံတဳလတံ၊ သၟတ်ကောန်တြုံသၟိၚ်ဗောဓိကုမာဂှ်ဒဇန်သဟာသဳလောန်သန်သွံ။ ဝဍ္ဎကဳဗဳသကဝ်ဓယှ်ဂှ် ကဵုတွဵုပ္တိတ်ကၠေံမတ်သီုၜါမ္ဂးဝွံဂှ် သြမ္ၚိုဟ်ထဍိုဟ်လောန်သန်သွံ၊ သြသ္အဵုသ္အာ်လောန်သန်သွံ၊ သြသ္ကာတ်မြဟ်လောန်သန်သွံ။” (ဇ—၃၅၃။ အစွောံ။) = “ငါ့ရှင်တို့၊ ဗောဓိကုမာမင်းသားသည် အလွန်လျှင် ရက်စက်ကြမ်းကြုတ်၏။ လက်သမားကျော်၏ မျက်စိနှစ်ဖက်လုံးကို ဖောက်ထုတ်ပစ်စေသည်မှာ သြော်ရုန့်ရင်းလေစွ၊ သြော်ကြမ်းကြုတ်လေစွ၊ သြော်နိုင်ထက်ကလူမူတတ်လေစွ။”')
,(11588,3,4,'၂။ (ဝမ်းနည်းခြင်း၊ ပူဆွေးခြင်းစသည်) စိတ်ခံစားမှုကင်းမဲ့သည်။ နှလုံးခိုင်မာသည်။ စိတ်ခိုင်မာသည်။','“ယွံမၞးတံ၊ ဒေံဍေံမွဲဂှ် မၞးတံရံၚ်ရ။ ပ္ဍဲကောဍေံမချိုတ်အာဂှ်ကီုလေဝ် ဆဗၞတ်မုက္ခဝါဍေံလီုအာညိညကီု ဟွံမွဲသွံ။ စိုတ်ဍေံမ္ၚိုဟ်ထဍိုဟ်လောန်။” (ဇ—၃၁၇။ အစွောံ။) = “အချင်းတို့၊ ကြည့်ကြကုန်လော။ အစ်ကိုသေလတ်သော် ဤသူအား မျက်နှာညှိုးခြင်းမျှသည်လည်းမရှိ။ အလွန်လျှင်နှလုံးခိုင်မာ၏။” || ‘မ္ၚောဟ်ထဍောဟ်’ ဟုလည်း အနည်းအားဖြင့်တွေ့ရသည်။')
,(11589,3,16,'သၚ်။',NULL)
,(11590,3,16,'သင်တို့။',NULL)
,(11591,3,12,'(န) ပတ္တမြား။',NULL)
,(11592,3,1,'ကျောက်မျက်ရွဲ။ (ပါဠိ—ဝေဠုရိယ)',NULL)
,(11593,3,1,'ပတ္တမြားနီ။','“(ဗောဓိသတ်ဒှ်က) ဂဍောၚ်မတ်ၜါ ညံၚ်မၞိက်လောဟိတာ်မပေါတ်ပ္တိုန်လဝ်အရံၚ်ကီု။” (ဇ—၇၅။ အစွောံ။) = “ဘုရားလောင်းသည် ငါးမျိုး­ဖြစ်၍ မျက်လုံးနှစ်ခုတို့သည် ကောင်းစွာသွေးအပ်ပြီးသော နီသောပတ္တမြားလုံးနှင့်တူကုန်၏။”')
,(11594,3,1,'ပတ္တမြားညို။ ဣန္ဒနီလာကျောက်။ မြကျောက်ညို။ နီလာ။ (ပါဠိ—ဣန္ဒနဳလ','နဳလမဏိ) || “က္ၜၚ်ထဝ်ဂှ် ဒယိုင်ယာဍေံပိဂှ် မတၟုဲတဴနမတ်မၞိက်လမ္စံက်၊ ဇုက်ယာက္ၜၚ်ဂှ် မတၟုဲတဴနထဝ်၊ ယာတ်သၠယာဂှ် မတၟုဲတဴနသြန်၊ ချူကဵုသၠသၞေဝ်ဂှ် ဍေံတၟုဲတဴနထဝ်ဟေၚ်။” (ဇ—၄၄၂။ အစွောံ။) = “ထိုလှေ၏သုံးခုသော လင်းယဉ်တိုၚ်တို့သည် ပတ္တမြားညိုဖြင့်ပြီးကုန်၏။ စက်ကြိုးတို့သည် ရွှေဖြင့်ပြီးကုန်၏။ ရွက်တို့သည် ငွေဖြင့်ပြီးကုန်၏။ တက်မ၊ ထိုးဝါးတို့သည် ရွှေစင်အတိပြီးသည်သာလျှင် ဖြစ်ကုန်၏။ (ညောင်ကန်) || “(ပ္ဍဲဒေါဝ်လစဆဒ္ဒန်ဂှ်) ဍာ်ဂှ်အရံၚ်ဍေံဒှ်ညံၚ်ရဴသာ်မၞိက်လမ္စံက်ကီုရ။” (ဇ—၅၁၄။ အစွောံ။) = “ထိုဆဒ္ဒန်အိုၚ်၏အလယ်­ —မြအဆင်းနှင့်တူသော ရေသည်သာလျှင်တည်၏။” (ညောင်ကန်) || “ကၠာတေံဂှ် ဍာ်လစဝွံ သ္ဇုၚ်သ္အးညံၚ်သာ်မၞိက်လစံက်ကီု။” (ဇ—၂၅၇။ အစွောံ။) = “ရှေး­ဤရေကန်ဝယ် ရေသည်ကြည်၏။မြအဆင်းနှင့်တူ၏။” (ညောင်ကန်)')
,(11595,3,1,'အစိုင်အခဲ။ (ပါဠိ—ပိဏ္ဍဳ)','မၞိမ်ပသဲ = သံခဲ။ (= ကလောအ်ပသဲ) (ပါဠိ—လောဟပိဏ္ဍ)')
,(11596,3,3,'ရှိသော။',NULL)
,(11596,3,4,'ရှိသည်။','“ဆသြန်မွဲလ္ၚီကီု မနွံကုအဲရ။” = “ကျွန်တော့်မှာ ငွေတစ်ထောင်မျှသာရှိသည်။”')
,(11597,3,3,'ရှိသော။ (နှင့်) ပြည့်စုံသော။ (နာမဝိသေသနပုဒ်ကို ဖွဲ့စည်းရာတွင်သုံးသည်။','ဥပမာ —')
